    /// Build an all-valid Float64 column from already-typed contiguous values.
    ///
    /// This is the typed ingestion counterpart to `Column::new(DType::Float64,
    /// Vec<Scalar>)` for sources that have already proven every value is a
    /// valid f64.
    #[must_use]
    /// Build an all-valid Float64 column WITHOUT scanning `data` for NaN. The
    /// caller must have already proven `data` is NaN-free (otherwise a NaN slot
    /// would wrongly claim valid). Identical to the no-NaN branch of
    /// [`Self::from_f64_values`]. (br-frankenpandas-9houf)
    #[doc(hidden)]
    pub fn from_f64_values_all_valid_unchecked(data: Vec<f64>) -> Self {
        let len = data.len();
        Self {
            dtype: DType::Float64,
            values: ScalarValues::lazy_all_valid_float64(data),
            validity: ValidityMask::all_valid(len),
            data: None,
        }
    }

    /// Build an already-proven NaN-free Float64 buffer without either a scan or
    /// the `Arc<[f64]>` conversion copy used by the slice-backed constructor.
    ///
    /// The caller must establish the same no-NaN precondition as
    /// [`Self::from_f64_values_all_valid_unchecked`]. This owns and moves the
    /// freshly-produced vector into the column backing.
    #[must_use]
    #[doc(hidden)]
    pub fn from_f64_values_all_valid_owned_unchecked(data: Vec<f64>) -> Self {
        Self::from_f64_all_valid_with_finite_opt(data, None)
    }

    #[must_use]
    #[doc(hidden)]
    pub fn from_f64_combine_first_all_valid(
        left: Arc<[f64]>,
        right: Arc<[f64]>,
        left_validity: &ValidityMask,
    ) -> Self {
        let len = left_validity.len();
        debug_assert!(left.len() >= len);
        debug_assert!(right.len() >= len);
        Self {
            dtype: DType::Float64,
            values: ScalarValues::lazy_combine_first_float64(
                left,
                right,
                Arc::from(left_validity.packed_words_for_scan()),
                len,
            ),
            validity: ValidityMask::all_valid(len),
            data: None,
        }
    }

    pub fn from_f64_values(data: Vec<f64>) -> Self {
        let mut has_nan = false;
        let mut all_finite = true;
        for value in &data {
            has_nan |= value.is_nan();
            all_finite &= value.is_finite();
        }
        Self::from_f64_values_with_finite_witness(data, has_nan, all_finite)
    }

    /// Like `from_f64_values` but, for the all-valid (no-NaN) case, MOVES the
    /// owned `Vec<f64>` into the backing (`Arc::new`, one tiny box) instead of
    /// `Arc::from(Vec)`'s cold-buffer realloc-copy (~5.7ms/1M, page-fault-bound).
    /// For op OUTPUTS that just wrote a hot Vec (cumsum/cummax/cummin/cumprod)
    /// this is a 6-8x op-side win. Bit-identical: the single NaN scan is the same
    /// one `from_f64_values` runs, and a NaN-bearing output routes to the
    /// identical `from_f64_values` (NaN-as-missing) path. The resulting
    /// `LazyAllValidFloat64Vec` backing is semantically identical to
    /// `LazyAllValidFloat64` (it just isn't keyed by the Arc<[f64]>-specific
    /// take_positions/binary zero-copy fast paths — fine for terminal outputs).
    #[must_use]
    pub fn from_f64_values_owned(data: Vec<f64>) -> Self {
        if data.iter().any(|v| v.is_nan()) {
            return Self::from_f64_values(data);
        }
        let len = data.len();
        Self {
            dtype: DType::Float64,
            values: ScalarValues::lazy_all_valid_float64_owned(data),
            validity: ValidityMask::all_valid(len),
            data: None,
        }
    }

    /// Build a nullable Float64 column from a raw `data` buffer plus an EXPLICIT
    /// validity mask, WITHOUT re-deriving validity from NaN. The `LazyNullableFloat64`
    /// backing renders each slot as: validity-set ⇒ present `Float64(data)`;
    /// cleared-bit-with-NaN-datum ⇒ present `Float64(NaN)`; cleared-bit-with-
    /// non-NaN-datum ⇒ `Null(NullKind::NaN)`. This is the only constructor that
    /// reproduces the per-element Scalar path's three-way representation for typed
    /// nullable arithmetic outputs (a GENERATED NaN must stay a present
    /// `Float64(NaN)`, an absent operand must be `Null`). Callers set the validity
    /// bit iff the slot is present AND its datum is non-NaN.
    #[must_use]
    pub fn from_f64_values_nullable(data: Vec<f64>, validity: ValidityMask) -> Self {
        debug_assert_eq!(data.len(), validity.len());
        Self {
            dtype: DType::Float64,
            values: ScalarValues::lazy_nullable_float64(data, validity.clone()),
            validity,
            data: None,
        }
    }

    fn from_f64_values_with_finite_witness(
        data: Vec<f64>,
        has_nan: bool,
        all_finite: bool,
    ) -> Self {
        let len = data.len();
        // pandas treats NaN in a float column as MISSING. The Scalar path
        // (Column::new -> ValidityMask::from_values) already marks NaN invalid
        // via Scalar::is_missing, so this typed-ingestion path must agree —
        // otherwise a caller passing NaN gets a column claiming all-valid and
        // as_f64_slice would hand the NaN out as a real value. Fast all-valid
        // path (cheap u64::MAX fill) when no NaN is present; per-bit mask only
        // when one is. (br-frankenpandas-jyhf7)
        let validity = if has_nan {
            ValidityMask::from_f64(&data)
        } else {
            ValidityMask::all_valid(len)
        };
        Self {
            dtype: DType::Float64,
            values: ScalarValues::lazy_all_valid_float64_with_finite(data, Some(all_finite)),
            validity,
            data: None,
        }
    }

    /// Read the cached all-finite witness of an all-valid Float64 column, if it
    /// has already been resolved. Never forces a scan (`None` when unknown).
    /// Used by finiteness-preserving maps (e.g. `abs`) to carry the input's
    /// witness onto the output for free.
    fn f64_finite_witness(&self) -> Option<bool> {
        self.values.all_valid_float64_finite_witness()
    }

    /// Build an all-valid Float64 column as a ZERO-COPY WINDOW into a shared
    /// buffer: `data[start .. start + len]`.
    ///
    /// Added for the transposed-frame plan, whose output has one column per
    /// SOURCE ROW — 100_000 of them at the 100k fixture. Building each as its own
    /// heap `Column` costs one allocation, one `OnceLock` init and one drop per
    /// output column; profiled on `df_transpose_full_materialize_positional`
    /// those three lines were ~43% of the whole lane (drop_glue 14.49%, OnceLock
    /// machinery ~14.8%, mimalloc ~14%). A page of output columns can instead
    /// share ONE gathered buffer, with each column a window into it.
    ///
    /// The caller guarantees the window is all-valid and NaN-free, exactly as
    /// [`Self::from_f64_all_valid_with_finite_opt`] requires; the window bounds
    /// are debug-asserted by the underlying `ScalarValues` constructor.
    #[must_use]
    pub fn from_f64_shared_window(data: Arc<[f64]>, start: usize, len: usize) -> Self {
        Self {
            dtype: DType::Float64,
            values: ScalarValues::lazy_all_valid_float64_slice(data, start, len),
            validity: ValidityMask::all_valid(len),
            data: None,
        }
    }

    /// Build an all-valid (no-NaN) Float64 column from a values buffer, carrying
    /// an optional pre-known all-finite witness WITHOUT scanning. The caller
    /// guarantees the buffer has no NaN (NaN ⇒ missing under pandas semantics);
    /// `from_f64_values` is the scanning constructor for unproven input.
    fn from_f64_all_valid_with_finite_opt(data: Vec<f64>, all_finite: Option<bool>) -> Self {
        // Caller has proven all-valid (no NaN), so MOVE the hot output Vec into
        // the backing (Arc::new) instead of lazy_all_valid_float64_with_finite's
        // Arc::from(Vec) cold-realloc-copy (~5.7ms/1M). Flips abs/fabs/round/neg
        // and the other all-valid f64 producers from the arc-copy floor.
        let len = data.len();
        Self {
            dtype: DType::Float64,
            values: ScalarValues::lazy_all_valid_float64_owned_with_finite(data, all_finite),
            validity: ValidityMask::all_valid(len),
            data: None,
        }
    }

    fn from_f64_values_owned_with_validity(
        data: Vec<f64>,
        validity: ValidityMask,
        all_finite: Option<bool>,
    ) -> Self {
        debug_assert_eq!(data.len(), validity.len());
        Self {
            dtype: DType::Float64,
            values: ScalarValues::lazy_all_valid_float64_owned_with_finite(data, all_finite),
            validity,
            data: None,
        }
    }

    /// Build an all-valid Float64 column from immutable chunks that are already
    /// in output row order. The caller must have proven that every value in
    /// every chunk is non-NaN; otherwise pandas missing-value semantics require
    /// [`Self::from_f64_values`] instead.
    #[doc(hidden)]
    #[must_use]
    pub fn from_f64_all_valid_chunks(chunks: Vec<(Arc<[f64]>, usize, usize)>, len: usize) -> Self {
        debug_assert_eq!(
            chunks
                .iter()
                .map(|(_, _, chunk_len)| *chunk_len)
                .sum::<usize>(),
            len
        );
        let chunks: Vec<Float64Chunk> = chunks
            .into_iter()
            .map(|(data, start, chunk_len)| Float64Chunk::new(data, start, chunk_len))
            .collect();
        Self {
            dtype: DType::Float64,
            values: ScalarValues::lazy_all_valid_float64_chunks(Arc::from(chunks), len),
            validity: ValidityMask::all_valid(len),
            data: None,
        }
    }

    /// As [`Self::from_f64_all_valid_chunks`], but taking each chunk's buffer by
    /// pointer move instead of by copy.
    ///
    /// br-frankenpandas-284ul. `from_f64_all_valid_chunks` takes `Arc<[f64]>`,
    /// and a producer holding a freshly `collect()`ed `Vec<f64>` can only reach
    /// that type through `Arc::from(Vec)`, which allocates and memcpys. For the
    /// 8 MB-per-call elementwise path that copy is the entire saving the
    /// write-once form was supposed to buy, so this constructor is what makes the
    /// lever arithmetic work out rather than cancel.
    #[doc(hidden)]
    #[must_use]
    pub fn from_f64_all_valid_owned_chunks(
        chunks: Vec<(Arc<Vec<f64>>, usize, usize)>,
        len: usize,
    ) -> Self {
        Self::from_f64_all_valid_owned_chunks_with_finite(chunks, len, None)
    }

    /// As [`Self::from_f64_all_valid_owned_chunks`], carrying the all-finite
    /// witness the producer already computed.
    ///
    /// br-frankenpandas-284ul. See
    /// [`ScalarValues::lazy_all_valid_float64_chunks_with_finite`] — discarding a
    /// witness that is already in hand costs a later full read of the output and
    /// would cancel the saving this path exists to make.
    #[doc(hidden)]
    #[must_use]
    pub fn from_f64_all_valid_owned_chunks_with_finite(
        chunks: Vec<(Arc<Vec<f64>>, usize, usize)>,
        len: usize,
        all_finite: Option<bool>,
    ) -> Self {
        debug_assert_eq!(
            chunks
                .iter()
                .map(|(_, _, chunk_len)| *chunk_len)
                .sum::<usize>(),
            len
        );
        let chunks: Vec<Float64Chunk> = chunks
            .into_iter()
            .map(|(data, start, chunk_len)| Float64Chunk::owned(data, start, chunk_len))
            .collect();
        Self {
            dtype: DType::Float64,
            values: ScalarValues::lazy_all_valid_float64_chunks_with_finite(
                Arc::from(chunks),
                len,
                all_finite,
            ),
            validity: ValidityMask::all_valid(len),
            data: None,
        }
    }

    /// Build an all-valid Float64 column whose values are the dot product of
    /// all-valid finite input columns with one finite right-hand column.
    ///
    /// The caller must prove every operand is finite, so every output slot is
    /// valid and NaN-free. Materialization preserves the eager dot kernel's
    /// `l = 0..k` accumulation order for each row.
    #[doc(hidden)]
    #[must_use]
    pub fn from_f64_all_valid_dot_product(
        a_cols: Vec<(Arc<[f64]>, usize)>,
        b_col: Arc<[f64]>,
        len: usize,
    ) -> Self {
        debug_assert_eq!(a_cols.len(), b_col.len());
        Self::from_f64_all_valid_dot_product_shared(&Float64DotAPanel::new(a_cols, len), b_col, len)
    }

    /// Build one output column of a dot product against a SHARED left-hand
    /// (`A`) panel. `DataFrame::dot` builds the panel ONCE and clones the inner
    /// `Arc` per output column (one refcount bump) instead of rebuilding the
    /// `k` `Float64DotInput`s + a fresh `Arc<[..]>` for every column — the prior
    /// `from_f64_all_valid_dot_product` did the latter `n` times, an O(n·k)
    /// Arc-and-alloc construction tax that dominated `df.dot` construction.
    /// How many chunks a dot of `total_work` multiply-adds over `columns`
    /// output columns should be split into, given `available` workers.
    ///
    /// br-frankenpandas-03fp5. Exposed so the frame-level pooled dispatch uses
    /// the SAME rule and the SAME `FP_DOT_WORK_PER_WORKER` knob as the scoped
    /// path it replaced, rather than always chunking to the pool width — a tiny
    /// dot should not dispatch 64 jobs through channels to multiply four numbers.
    #[doc(hidden)]
    #[must_use]
    pub fn dot_chunk_count(
        total_work: u128,
        available: usize,
        columns: usize,
        work_per_chunk: u128,
    ) -> usize {
        ScalarValues::dot_worker_count(
            total_work,
            work_per_chunk,
            available,
            ScalarValues::dot_materialization_worker_cap(),
            columns,
        )
    }

    /// One output column of a dot product, as owned data.
    ///
    /// br-frankenpandas-03fp5. Exposed so the ORCHESTRATOR can decide how to
    /// parallelise: everything this needs is `Arc`-backed, so a caller can clone
    /// the handles into a `'static` job and hand it to a persistent worker pool
    /// instead of paying a `thread::scope` spawn per call. The arithmetic is the
    /// same `materialize_float64_dot` the lazy path runs, so which mechanism
    /// computes it cannot change a value.
    #[doc(hidden)]
    #[must_use]
    pub fn dot_column_data(a_panel: &Float64DotAPanel, b_col: &[f64], len: usize) -> Vec<f64> {
        ScalarValues::materialize_float64_dot(&a_panel.0, b_col, len)
    }

    /// Pack a dot A panel once, for reuse by every worker of one product.
    ///
    /// br-frankenpandas-mti15. Returns an EMPTY vec when the blocked kernel is
    /// not available on this CPU, so a caller can prepack unconditionally and
    /// `dot_columns_data_blocked` will simply take its per-column arm. See
    /// [`fp_dot_kernel::pack_a_panel`] for the layout.
    #[doc(hidden)]
    #[must_use]
    pub fn pack_dot_panel(a_panel: &Float64DotAPanel, len: usize) -> Vec<f64> {
        if !ScalarValues::dot_kernel_available() {
            return Vec::new();
        }
        let a_slices = ScalarValues::dot_panel_slices_from(&a_panel.0, len);
        fp_dot_kernel::pack_a_panel(&a_slices, len)
    }

    /// SEVERAL output columns of one dot product, in a single pass over the A
    /// panel.
    ///
    /// br-frankenpandas-mti15. This is the batched sibling of
    /// [`Self::dot_column_data`], and it exists because the per-column entry
    /// re-streams the whole A panel for EVERY column it is called with — which is
    /// what the pooled orchestrator in `DataFrame::dot` was doing, once per
    /// column, on every worker. The blocked kernel holds an 8x6 output tile in
    /// vector registers across the whole `k` loop instead, so A is streamed
    /// `n / 6` times per worker.
    ///
    /// BIT-IDENTICAL to calling [`Self::dot_column_data`] once per column: every
    /// output element still accumulates `j = 0..k` in the same order with a
    /// separate multiply and add. `packed` may be empty or the wrong length, in
    /// which case the kernel packs for itself.
    ///
    /// ⚠️ `packed` MUST come from [`Self::pack_dot_panel`] called on THIS panel.
    /// The packed bytes carry no evidence of which product they came from, so a
    /// mismatched buffer of the right length would produce finite, plausible,
    /// wrong numbers. The caller owns that pairing; it cannot be checked here.
    #[doc(hidden)]
    #[must_use]
    pub fn dot_columns_data_blocked(
        a_panel: &Float64DotAPanel,
        packed: &[f64],
        b_cols: &[&[f64]],
        len: usize,
    ) -> Vec<Vec<f64>> {
        if b_cols.len() < 2 || !ScalarValues::dot_kernel_available() {
            return b_cols
                .iter()
                .map(|b_col| ScalarValues::materialize_float64_dot(&a_panel.0, b_col, len))
                .collect();
        }
        let a_slices = ScalarValues::dot_panel_slices_from(&a_panel.0, len);
        fp_dot_kernel::materialize_float64_dot_block_prepacked(packed, &a_slices, b_cols, len)
    }

    pub fn from_f64_all_valid_dot_product_shared(
        a_panel: &Float64DotAPanel,
        b_col: Arc<[f64]>,
        len: usize,
    ) -> Self {
        debug_assert_eq!(a_panel.0.len(), b_col.len());
        Self {
            dtype: DType::Float64,
            values: ScalarValues::lazy_all_valid_float64_dot(Arc::clone(&a_panel.0), b_col, len),
            validity: ValidityMask::all_valid(len),
            data: None,
        }
    }

    /// Build all columns of a finite all-valid Float64 pairwise corr/cov matrix
    /// over a shared lazy plan.
    ///
    /// The caller must prove that every input value is finite and that every
    /// output cell is finite under `stat`/`min_periods`. This mirrors the
    /// no-NaN branch of `DataFrame`'s eager pairwise matrix kernel, but defers
    /// the `O(n_cols^2 * n_rows)` moment/Gram work until a consumer reads the
    /// result values.
    #[doc(hidden)]
    #[must_use]
    pub fn from_f64_all_valid_pairwise_stat_matrix_columns(
        cols: Vec<(Arc<[f64]>, usize)>,
        row_len: usize,
        stat: PairwiseFloat64Stat,
        min_periods: usize,
    ) -> Vec<Self> {
        let inputs: Vec<Float64PairwiseStatInput> = cols
            .into_iter()
            .map(|(data, start)| Float64PairwiseStatInput::new(data, start, row_len))
            .collect();
        let plan = Arc::new(Float64PairwiseStatMatrixPlan::new(
            Arc::from(inputs),
            row_len,
            stat,
            min_periods,
        ));
        let n = plan.column_len();
        (0..n)
            .map(|col| Self {
                dtype: DType::Float64,
                values: ScalarValues::lazy_all_valid_float64_pairwise_stat_matrix_column(
                    Arc::clone(&plan),
                    col,
                ),
                validity: ValidityMask::all_valid(n),
                data: None,
            })
            .collect()
    }

    /// Build a shared lazy row plan for a homogeneous all-valid Float64
    /// transpose. Each `(Arc, start)` source is one original column with
    /// `row_len` readable rows.
    #[doc(hidden)]
    #[must_use]
    pub fn f64_transpose_rows_plan(
        cols: Vec<(Arc<[f64]>, usize)>,
        row_len: usize,
    ) -> Float64TransposeRows {
        let inputs: Vec<Float64TransposeInput> = cols
            .into_iter()
            .map(|(data, start)| Float64TransposeInput::new(data, start, row_len))
            .collect();
        Float64TransposeRows {
            plan: Arc::new(Float64TransposeRowsPlan::new(Arc::from(inputs), row_len)),
        }
    }

    /// Build one all-valid Float64 output row over a shared transpose plan.
    /// Scalar and typed reads materialize exactly the eager row-copy order.
    #[doc(hidden)]
    #[must_use]
    pub fn from_f64_transpose_row(plan: &Float64TransposeRows, source_row: usize) -> Self {
        debug_assert!(source_row < plan.plan.row_len);
        let len = plan.plan.column_len();
        Self {
            dtype: DType::Float64,
            values: ScalarValues::lazy_all_valid_float64_transpose_row(
                Arc::clone(&plan.plan),
                source_row,
            ),
            validity: ValidityMask::all_valid(len),
            data: None,
        }
    }

    /// Public (hidden) for fp-join's fused dense outer-merge builder
    /// (br-frankenpandas-343ho); invalid slots carry the 0.0-datum convention
    /// and materialize `Scalar::Null(NullKind::NaN)`.
    #[doc(hidden)]
    pub fn from_f64_values_with_validity(data: Vec<f64>, validity: ValidityMask) -> Self {
        debug_assert_eq!(data.len(), validity.len());
        if validity.all() {
            // All-valid → MOVE the Vec into the backing (from_f64_values_owned)
            // rather than from_f64_values' Arc::from realloc-copy. Bit-identical:
            // _owned falls back to from_f64_values on any stray NaN. Benefits every
            // caller whose output happens to carry no missing (bfill/interpolate/…).
            return Self::from_f64_values_owned(data);
        }
        Self {
            dtype: DType::Float64,
            values: ScalarValues::lazy_nullable_float64(data, validity.clone()),
            validity,
            data: None,
        }
    }

    /// Nullable Int64 counterpart of `from_f64_values_with_validity`
    /// (br-frankenpandas-lt5qx): invalid slots materialize
    /// `Scalar::Null(NullKind::Null)` (= `missing_for_dtype(Int64)`), valid
    /// slots `Scalar::Int64(data[i])`. Public (hidden) for fp-join's fused
    /// dense left-merge builder (br-frankenpandas-7wxoc).
    #[doc(hidden)]
    pub fn from_i64_values_with_validity(data: Vec<i64>, validity: ValidityMask) -> Self {
        debug_assert_eq!(data.len(), validity.len());
        if validity.all() {
            return Self::from_i64_values_owned(data);
        }
        Self {
            dtype: DType::Int64,
            values: ScalarValues::lazy_nullable_int64(data, validity.clone()),
            validity,
            data: None,
        }
    }

    /// Datetime64 counterpart of [`Self::from_i64_values_with_validity`]: invalid
