    /// Element-wise arctangent of y/x.
    pub fn atan2(&self, other: &Self) -> Result<Self, ColumnError> {
        if self.len() != other.len() {
            return Err(ColumnError::LengthMismatch {
                left: self.len(),
                right: other.len(),
            });
        }
        if let Some(out) = self.typed_float_binary_par(other, |y, x| y.atan2(x)) {
            return Ok(out);
        }
        // Nullable/mixed: both-present ⇒ y.atan2(x), either-missing ⇒ NaN⇒missing —
        // the typed_nan_propagate_binary rule (atan2 of finite/±inf never yields a
        // non-input NaN, so bit-identical to the Scalar loop below).
        if let Some(out) = self.typed_nan_propagate_binary(other, |y, x| y.atan2(x)) {
            return Ok(out);
        }
        let mut out = Vec::with_capacity(self.values.len());
        for (y, x) in self.values.iter().zip(&other.values) {
            if y.is_missing() || x.is_missing() {
                out.push(Scalar::Float64(f64::NAN));
                continue;
            }
            let yf = y.to_f64().map_err(ColumnError::Type)?;
            let xf = x.to_f64().map_err(ColumnError::Type)?;
            out.push(Scalar::Float64(yf.atan2(xf)));
        }
        Self::new(DType::Float64, out)
    }

    /// Element-wise Euclidean distance sqrt(x^2 + y^2).
    pub fn hypot(&self, other: &Self) -> Result<Self, ColumnError> {
        if self.len() != other.len() {
            return Err(ColumnError::LengthMismatch {
                left: self.len(),
                right: other.len(),
            });
        }
        if let Some(out) = self.typed_float_binary_par(other, |a, b| a.hypot(b)) {
            return Ok(out);
        }
        // Nullable/mixed: hypot of finite/±inf never yields a non-input NaN, so the
        // both-present ⇒ f, else NaN⇒missing rule is bit-identical to the Scalar loop.
        if let Some(out) = self.typed_nan_propagate_binary(other, |a, b| a.hypot(b)) {
            return Ok(out);
        }
        let mut out = Vec::with_capacity(self.values.len());
        for (a, b) in self.values.iter().zip(&other.values) {
            if a.is_missing() || b.is_missing() {
                out.push(Scalar::Float64(f64::NAN));
                continue;
            }
            let af = a.to_f64().map_err(ColumnError::Type)?;
            let bf = b.to_f64().map_err(ColumnError::Type)?;
            out.push(Scalar::Float64(af.hypot(bf)));
        }
        Self::new(DType::Float64, out)
    }

    /// Element-wise floating-point remainder (fmod).
    pub fn fmod(&self, other: &Self) -> Result<Self, ColumnError> {
        if self.len() != other.len() {
            return Err(ColumnError::LengthMismatch {
                left: self.len(),
                right: other.len(),
            });
        }
        if let Some(out) = self.typed_float_binary(other, |a, b| a % b) {
            return Ok(out);
        }
        // Nullable/mixed: both-present ⇒ a%b, either-missing ⇒ NaN⇒missing. `a%0` (or
        // inf%b) yields NaN, which from_f64_values marks missing — exactly as the
        // Scalar loop's Float64(NaN) ⇒ Self::new does. Bit-identical.
        if let Some(out) = self.typed_nan_propagate_binary(other, |a, b| a % b) {
            return Ok(out);
        }
        let mut out = Vec::with_capacity(self.values.len());
        for (a, b) in self.values.iter().zip(&other.values) {
            if a.is_missing() || b.is_missing() {
                out.push(Scalar::Float64(f64::NAN));
                continue;
            }
            let af = a.to_f64().map_err(ColumnError::Type)?;
            let bf = b.to_f64().map_err(ColumnError::Type)?;
            out.push(Scalar::Float64(af % bf));
        }
        Self::new(DType::Float64, out)
    }

    /// Element-wise copysign: magnitude of self with sign of other.
    pub fn copysign(&self, other: &Self) -> Result<Self, ColumnError> {
        if self.len() != other.len() {
            return Err(ColumnError::LengthMismatch {
                left: self.len(),
                right: other.len(),
            });
        }
        if let Some(out) = self.typed_float_binary(other, |m, s| m.copysign(s)) {
            return Ok(out);
        }
        // Nullable/mixed: copysign of finite/±inf magnitude never yields a non-input
        // NaN, so both-present ⇒ m.copysign(s), else NaN⇒missing is bit-identical.
        if let Some(out) = self.typed_nan_propagate_binary(other, |m, s| m.copysign(s)) {
            return Ok(out);
        }
        let mut out = Vec::with_capacity(self.values.len());
        for (mag, sign) in self.values.iter().zip(&other.values) {
            if mag.is_missing() || sign.is_missing() {
                out.push(Scalar::Float64(f64::NAN));
                continue;
            }
            let mf = mag.to_f64().map_err(ColumnError::Type)?;
            let sf = sign.to_f64().map_err(ColumnError::Type)?;
            out.push(Scalar::Float64(mf.copysign(sf)));
        }
        Self::new(DType::Float64, out)
    }

    /// Element-wise sign: -1, 0, or 1.
    pub fn sign(&self) -> Result<Self, ColumnError> {
        // Typed, dtype-preserving fast path (all-valid only): Int64 -> Int64
        // (-1/0/1), Float64 -> Float64. all-valid Float64 has no NaN so the
        // is_nan branch never fires; -0.0 -> 0.0 (neither >0.0 nor <0.0), exactly
        // as the scalar loop. Bit-identical.
        if let Some(data) = self.as_i64_slice() {
            return Ok(Self::from_i64_values_owned(
                data.iter()
                    .map(|&x| {
                        if x > 0 {
                            1
                        } else if x < 0 {
                            -1
                        } else {
                            0
                        }
                    })
                    .collect(),
            ));
        }
        if let Some(data) = self.as_f64_slice() {
            // sign(all-valid) ∈ {-1.0, 0.0, 1.0} — always finite, never NaN — so
            // the output is provably all-valid AND all-finite. Skip the
            // from_f64_values has_nan/all_finite rescan with a `Some(true)`
            // witness (mirror of abs). Bit-identical (same -1/0/1, -0.0→0.0).
            let out: Vec<f64> = data
                .iter()
                .map(|&x| {
                    if x > 0.0 {
                        1.0
                    } else if x < 0.0 {
                        -1.0
                    } else {
                        0.0
                    }
                })
                .collect();
            return Ok(Self::from_f64_all_valid_with_finite_opt(out, Some(true)));
        }
        let mut out = Vec::with_capacity(self.values.len());
        for v in &self.values {
            if v.is_missing() {
                out.push(Scalar::Float64(f64::NAN));
                continue;
            }
            match v {
                Scalar::Int64(x) => {
                    let s = if *x > 0 {
                        1
                    } else if *x < 0 {
                        -1
                    } else {
                        0
                    };
                    out.push(Scalar::Int64(s));
                }
                Scalar::Float64(x) => {
                    let s = if x.is_nan() {
                        f64::NAN
                    } else if *x > 0.0 {
                        1.0
                    } else if *x < 0.0 {
                        -1.0
                    } else {
                        0.0
                    };
                    out.push(Scalar::Float64(s));
                }
                _ => {
                    return Err(ColumnError::Type(TypeError::NonNumericValue {
                        value: format!("{v:?}"),
                        dtype: self.dtype,
                    }));
                }
            }
        }
        let dtype = match self.dtype {
            DType::Int64 => DType::Int64,
            _ => DType::Float64,
        };
        Self::new(dtype, out)
    }

    /// Test element-wise for negative sign bit.
    ///
    /// Matches np.signbit(x). Returns True for negative values including -0.0.
    pub fn signbit(&self) -> Result<Self, ColumnError> {
        // Typed fast path (all-valid only, output Bool): Int64 sign via x < 0,
        // Float64 via is_sign_negative (so -0.0 -> true). Bit-identical; all-valid
        // ⇒ the missing -> Bool(false) branch never applies.
        if let Some(data) = self.as_i64_slice() {
            return Ok(Self::from_bool_values(
                data.iter().map(|&x| x < 0).collect(),
            ));
        }
        if let Some(data) = self.as_f64_slice() {
            return Ok(Self::from_bool_values(
                data.iter().map(|&x| x.is_sign_negative()).collect(),
            ));
        }
        let mut out = Vec::with_capacity(self.values.len());
        for v in &self.values {
            if v.is_missing() {
                out.push(Scalar::Bool(false));
                continue;
            }
            match v {
                Scalar::Int64(x) => out.push(Scalar::Bool(*x < 0)),
                Scalar::Float64(x) => out.push(Scalar::Bool(x.is_sign_negative())),
                _ => {
                    return Err(ColumnError::Type(TypeError::NonNumericValue {
                        value: format!("{v:?}"),
                        dtype: self.dtype,
                    }));
                }
            }
        }
        Self::new(DType::Bool, out)
    }

    /// Compute the Heaviside step function.
    ///
    /// Matches np.heaviside(x, h0). Returns:
    /// - 0 where x < 0
    /// - h0 where x == 0
    /// - 1 where x > 0
    pub fn heaviside(&self, h0: f64) -> Result<Self, ColumnError> {
        // Typed fast path (all-valid or nullable Float64/Int64 ⇒ Float64 out): present
        // ⇒ x<0?0:x>0?1:h0. The `is_nan ⇒ NaN` guard is REQUIRED: typed_float_unary's
        // nullable arm passes a valid-bit-set NaN datum through `f` (it drops only
        // validity-unset slots), and heaviside's bare comparisons would fall to the
        // `else` (⇒ h0, a finite VALUE) instead of NaN — so the kernel must propagate
        // NaN itself, making it match the Scalar loop's is_missing(NaN)⇒NaN (from_f64
        // _values then marks it missing). Int64 has no NaN so the guard is inert there.
        if let Some(out) = self.typed_float_unary(|x| {
            if x.is_nan() {
                f64::NAN
            } else if x < 0.0 {
                0.0
            } else if x > 0.0 {
                1.0
            } else {
                h0
            }
        }) {
            return Ok(out);
        }
        let mut out = Vec::with_capacity(self.values.len());
        for v in &self.values {
            if v.is_missing() {
                out.push(Scalar::Float64(f64::NAN));
                continue;
            }
            match v {
                Scalar::Int64(x) => {
                    let val = if *x < 0 {
                        0.0
                    } else if *x > 0 {
                        1.0
                    } else {
                        h0
                    };
                    out.push(Scalar::Float64(val));
                }
                Scalar::Float64(x) => {
                    let val = if x.is_nan() {
                        f64::NAN
                    } else if *x < 0.0 {
                        0.0
                    } else if *x > 0.0 {
                        1.0
                    } else {
                        h0
                    };
                    out.push(Scalar::Float64(val));
                }
                _ => {
                    return Err(ColumnError::Type(TypeError::NonNumericValue {
                        value: format!("{v:?}"),
                        dtype: self.dtype,
                    }));
                }
            }
        }
        Self::new(DType::Float64, out)
    }

    /// Element-wise greatest common divisor.
    ///
    /// Matches np.gcd(x, y). Works on integer values.
    pub fn gcd(&self, other: &Self) -> Result<Self, ColumnError> {
        if self.len() != other.len() {
            return Err(ColumnError::LengthMismatch {
                left: self.len(),
                right: other.len(),
            });
        }
        // Typed Int64 fast path (both-present ⇒ Int64(gcd), else Null(Null)); same
        // kernel + missing rule as the Scalar loop below, no Scalar materialization.
        if let Some(out) = self.typed_i64_both_present_binary(other, Self::compute_gcd_i64) {
            return Ok(out);
        }
        let mut out = Vec::with_capacity(self.values.len());
        for (a, b) in self.values.iter().zip(&other.values) {
            if a.is_missing() || b.is_missing() {
                out.push(Scalar::Null(NullKind::Null));
                continue;
            }
            match (a, b) {
                (Scalar::Int64(x), Scalar::Int64(y)) => {
                    out.push(Scalar::Int64(Self::compute_gcd_i64(*x, *y)));
                }
                _ => {
                    return Err(ColumnError::Type(TypeError::NonNumericValue {
                        value: format!("{a:?}"),
                        dtype: self.dtype,
                    }));
                }
            }
        }
        Self::new(DType::Int64, out)
    }

