    /// Element-wise left bit shift.
    ///
    /// Matches np.left_shift(x, y). Shifts bits of x left by y positions.
    pub fn left_shift(&self, other: &Self) -> Result<Self, ColumnError> {
        if self.len() != other.len() {
            return Err(ColumnError::LengthMismatch {
                left: self.len(),
                right: other.len(),
            });
        }
        // Typed Int64 fast path (both-present ⇒ Int64(x << clamp(y)), else Null(Null));
        // same kernel + missing rule as the Scalar loop below, no Scalar materialization.
        if let Some(out) =
            self.typed_i64_both_present_binary(other, |x, y| x.wrapping_shl(y.clamp(0, 63) as u32))
        {
            return Ok(out);
        }
        let mut out = Vec::with_capacity(self.values.len());
        for (a, b) in self.values.iter().zip(&other.values) {
            if a.is_missing() || b.is_missing() {
                out.push(Scalar::Null(NullKind::Null));
                continue;
            }
            match (a, b) {
                (Scalar::Int64(x), Scalar::Int64(y)) => {
                    let shift = (*y).clamp(0, 63) as u32;
                    out.push(Scalar::Int64(x.wrapping_shl(shift)));
                }
                _ => {
                    return Err(ColumnError::Type(TypeError::NonNumericValue {
                        value: format!("{a:?}"),
                        dtype: self.dtype,
                    }));
                }
            }
        }
        Self::new(DType::Int64, out)
    }

    /// Element-wise right bit shift.
    ///
    /// Matches np.right_shift(x, y). Shifts bits of x right by y positions.
    pub fn right_shift(&self, other: &Self) -> Result<Self, ColumnError> {
        if self.len() != other.len() {
            return Err(ColumnError::LengthMismatch {
                left: self.len(),
                right: other.len(),
            });
        }
        // Typed Int64 fast path (both-present ⇒ Int64(x >> clamp(y)), else Null(Null));
        // same kernel + missing rule as the Scalar loop below, no Scalar materialization.
        if let Some(out) =
            self.typed_i64_both_present_binary(other, |x, y| x.wrapping_shr(y.clamp(0, 63) as u32))
        {
            return Ok(out);
        }
        let mut out = Vec::with_capacity(self.values.len());
        for (a, b) in self.values.iter().zip(&other.values) {
            if a.is_missing() || b.is_missing() {
                out.push(Scalar::Null(NullKind::Null));
                continue;
            }
            match (a, b) {
                (Scalar::Int64(x), Scalar::Int64(y)) => {
                    let shift = (*y).clamp(0, 63) as u32;
                    out.push(Scalar::Int64(x.wrapping_shr(shift)));
                }
                _ => {
                    return Err(ColumnError::Type(TypeError::NonNumericValue {
                        value: format!("{a:?}"),
                        dtype: self.dtype,
                    }));
                }
            }
        }
        Self::new(DType::Int64, out)
    }

    /// Element-wise bitwise NOT (invert).
    pub fn bitwise_not(&self) -> Result<Self, ColumnError> {
        if let Some(out) = self.typed_bool_unary(|value| !value) {
            return Ok(out);
        }
        // Typed Int64 (all-valid + nullable): `!x` over the raw &[i64], dtype-preserving
        // with NO NaN, so it preserves missingness exactly (output validity == input
        // validity — a masked slot's `!garbage` is hidden). Bit-identical to the Scalar
        // loop: present ⇒ Int64(!x); missing ⇒ Null(Null) == missing_for_dtype(Int64) ==
        // from_i64_values_with_validity's cleared bit == the loop's v.clone() of an
        // Int64-missing slot. Mirror of the abs/neg nullable-Int64 arms.
        if let Some(data) = self.as_i64_slice() {
            return Ok(Self::from_i64_values_owned(
                data.iter().map(|&x| !x).collect(),
            ));
        }
        if self.dtype == DType::Int64
            && let Some((data, _)) = self.as_i64_slice_with_validity()
        {
            let out: Vec<i64> = data.iter().map(|&x| !x).collect();
            return Ok(Self::from_i64_values_with_validity(
                out,
                self.validity.clone(),
            ));
        }
        let mut out = Vec::with_capacity(self.values.len());
        for v in &self.values {
            if v.is_missing() {
                out.push(Scalar::Null(NullKind::Null));
                continue;
            }
            match v {
                Scalar::Int64(x) => out.push(Scalar::Int64(!x)),
                Scalar::Bool(x) => out.push(Scalar::Bool(!x)),
                _ => {
                    return Err(ColumnError::Type(TypeError::NonNumericValue {
                        value: format!("{v:?}"),
                        dtype: self.dtype,
                    }));
                }
            }
        }
        Self::new(self.dtype, out)
    }

    /// Alias for bitwise_not.
    pub fn invert(&self) -> Result<Self, ColumnError> {
        self.bitwise_not()
    }

    /// Element-wise maximum, NaN propagates.
    pub fn maximum(&self, other: &Self) -> Result<Self, ColumnError> {
        if self.len() != other.len() {
            return Err(ColumnError::LengthMismatch {
                left: self.len(),
                right: other.len(),
            });
        }
        // all-valid ⇒ no NaN (NaN floats mark the column invalid), so the scalar
        // loop's is_nan branch never fires and the result is af.max(bf).
        if let Some(out) = self.typed_float_binary(other, f64::max) {
            return Ok(out);
        }
        if let Some(out) = self.typed_nan_propagate_binary(other, f64::max) {
            return Ok(out);
        }
        let mut out = Vec::with_capacity(self.values.len());
        for (a, b) in self.values.iter().zip(&other.values) {
            if a.is_missing() || b.is_missing() {
                out.push(Scalar::Float64(f64::NAN));
                continue;
            }
            let af = a.to_f64().map_err(ColumnError::Type)?;
            let bf = b.to_f64().map_err(ColumnError::Type)?;
            if af.is_nan() || bf.is_nan() {
                out.push(Scalar::Float64(f64::NAN));
            } else {
                out.push(Scalar::Float64(af.max(bf)));
            }
        }
        Self::new(DType::Float64, out)
    }

    /// Typed nullable pairwise fast path for the NaN-PROPAGATING element-wise binaries
    /// (`maximum`/`minimum`): both columns Float64/Int64 (all-valid or nullable). The
    /// result is `f(x, y)` only when BOTH slots are present, else `Float64(NaN)` — bit-
    /// identical to the Scalar loop (`a.is_missing() || b.is_missing() ⇒ NaN`, and the
    /// redundant `af.is_nan() || bf.is_nan()` check drops nothing for present values,
    /// which are non-NaN by is_missing). get_present == !is_missing (validity-set AND
    /// non-NaN for Float64, KEEPING ±inf; validity-set for Int64). Output is Float64:
    /// from_f64_values marks the either-missing NaN slots missing, exactly as
    /// Self::new(Float64, [Float64(NaN)]) does. Covers mixed i64×f64. `None` unless
    /// both columns expose a typed numeric view.
    /// Euclid GCD of two i64 (non-negative). Shared by `gcd`/`lcm` typed + Scalar arms.
    fn compute_gcd_i64(mut a: i64, mut b: i64) -> i64 {
        a = a.abs();
        b = b.abs();
        while b != 0 {
            let t = b;
            b = a % b;
            a = t;
        }
        a
    }

    /// Element-wise LCM of two i64. Shared by `lcm`'s typed + Scalar arms.
    fn compute_lcm_i64(x: i64, y: i64) -> i64 {
        let g = Self::compute_gcd_i64(x, y);
        if g == 0 { 0 } else { (x.abs() / g) * y.abs() }
    }

    /// Typed fast path for Int64-preserving two-column ops whose result is
    /// `Int64(f(x,y))` when BOTH slots are present and MISSING (`Null(Null)` ==
    /// missing_for_dtype(Int64)) when either is absent — i.e. gcd/lcm/bitwise_&|^ on
    /// Int64 inputs. Reads both raw &[i64] + validity and reuses the input-present
    /// mask, instead of materializing BOTH columns' Vec<Scalar> + a trailing
    /// Vec<Scalar> result + Column::new. Bit-identical to the Scalar loop: same `f`
    /// over the same present pairs; a cleared bit in `from_i64_values_with_validity`
    /// renders `Null(Null)`, exactly the `Scalar::Null(NullKind::Null)` those loops
    /// push. `None` unless BOTH columns are typed Int64 (the loops' non-Int64 arm
    /// errors or is a different dtype — kept on the Scalar path).
    fn typed_i64_both_present_binary(&self, other: &Self, f: fn(i64, i64) -> i64) -> Option<Self> {
        if self.dtype != DType::Int64 || other.dtype != DType::Int64 {
            return None;
        }
        let (l, lv) = self.as_i64_slice_with_validity()?;
        let (r, rv) = other.as_i64_slice_with_validity()?;
        let n = l.len().min(r.len());
        let mut out = vec![0_i64; n];
        let mut vmask = ValidityMask::all_valid(n);
        for i in 0..n {
            if lv.get(i) && rv.get(i) {
                out[i] = f(l[i], r[i]);
            } else {
                vmask.set(i, false);
            }
        }
        Some(Self::from_i64_values_with_validity(out, vmask))
    }

    fn typed_nan_propagate_binary(&self, other: &Self, f: fn(f64, f64) -> f64) -> Option<Self> {
        let (sa, sb) = (self.typed_numeric_values()?, other.typed_numeric_values()?);
        let n = sa.len().min(sb.len());
        let out: Vec<f64> = (0..n)
            .map(|i| match (sa.get_present(i), sb.get_present(i)) {
                (Some(x), Some(y)) => f(x, y),
                _ => f64::NAN,
            })
            .collect();
        Some(Self::from_f64_values(out))
    }

    /// Typed nullable pairwise fast path for the NaN/missing-IGNORING element-wise
    /// binaries (`fmax`/`fmin`): both columns Float64/Int64 (all-valid or nullable).
    /// The result is `f(x, y)` when BOTH present, the single present value when only
    /// ONE is, else `Float64(NaN)` (both absent) — bit-identical to the Scalar loop,
    /// which reads `to_f64().ok()` per side and skips a NaN operand (`if x.is_nan()
    /// => y`, `(Some, None) => x`, …): get_present drops exactly the NaN AND null
    /// slots that fmax/fmin's is_nan / None arms treat as "not usable", so the four
    /// (present, present) cases collapse to this match. get_present KEEPS ±inf.
    /// Output is Float64; from_f64_values marks the both-absent NaN slots missing,
    /// exactly as Self::new(Float64, [Float64(NaN)]) does. Covers mixed i64×f64.
    fn typed_nan_ignore_binary(&self, other: &Self, f: fn(f64, f64) -> f64) -> Option<Self> {
        let (sa, sb) = (self.typed_numeric_values()?, other.typed_numeric_values()?);
        let n = sa.len().min(sb.len());
        let out: Vec<f64> = (0..n)
            .map(|i| match (sa.get_present(i), sb.get_present(i)) {
                (Some(x), Some(y)) => f(x, y),
                (Some(x), None) => x,
                (None, Some(y)) => y,
                (None, None) => f64::NAN,
            })
            .collect();
        Some(Self::from_f64_values(out))
    }

    /// Element-wise minimum, NaN propagates.
    pub fn minimum(&self, other: &Self) -> Result<Self, ColumnError> {
        if self.len() != other.len() {
            return Err(ColumnError::LengthMismatch {
                left: self.len(),
                right: other.len(),
            });
        }
        if let Some(out) = self.typed_float_binary(other, f64::min) {
            return Ok(out);
        }
        if let Some(out) = self.typed_nan_propagate_binary(other, f64::min) {
            return Ok(out);
        }
        let mut out = Vec::with_capacity(self.values.len());
        for (a, b) in self.values.iter().zip(&other.values) {
            if a.is_missing() || b.is_missing() {
                out.push(Scalar::Float64(f64::NAN));
                continue;
            }
            let af = a.to_f64().map_err(ColumnError::Type)?;
            let bf = b.to_f64().map_err(ColumnError::Type)?;
            if af.is_nan() || bf.is_nan() {
                out.push(Scalar::Float64(f64::NAN));
            } else {
                out.push(Scalar::Float64(af.min(bf)));
            }
        }
        Self::new(DType::Float64, out)
    }

    /// Element-wise maximum, ignoring NaN.
    pub fn fmax(&self, other: &Self) -> Result<Self, ColumnError> {
        if self.len() != other.len() {
            return Err(ColumnError::LengthMismatch {
                left: self.len(),
                right: other.len(),
            });
        }
        // all-valid numeric ⇒ both to_f64().ok() are Some(non-NaN), so the result
        // is x.max(y) — same as `maximum` on this domain.
        if let Some(out) = self.typed_float_binary(other, f64::max) {
            return Ok(out);
        }
        if let Some(out) = self.typed_nan_ignore_binary(other, f64::max) {
            return Ok(out);
        }
        let mut out = Vec::with_capacity(self.values.len());
        for (a, b) in self.values.iter().zip(&other.values) {
            let af = a.to_f64().ok();
            let bf = b.to_f64().ok();
            let result = match (af, bf) {
                (Some(x), Some(y)) if x.is_nan() => y,
                (Some(x), Some(y)) if y.is_nan() => x,
                (Some(x), Some(y)) => x.max(y),
                (Some(x), None) => x,
                (None, Some(y)) => y,
                (None, None) => f64::NAN,
            };
            out.push(Scalar::Float64(result));
        }
        Self::new(DType::Float64, out)
    }

    /// Element-wise minimum, ignoring NaN.
    pub fn fmin(&self, other: &Self) -> Result<Self, ColumnError> {
        if self.len() != other.len() {
            return Err(ColumnError::LengthMismatch {
                left: self.len(),
                right: other.len(),
            });
        }
        if let Some(out) = self.typed_float_binary(other, f64::min) {
            return Ok(out);
        }
        if let Some(out) = self.typed_nan_ignore_binary(other, f64::min) {
            return Ok(out);
        }
        let mut out = Vec::with_capacity(self.values.len());
        for (a, b) in self.values.iter().zip(&other.values) {
            let af = a.to_f64().ok();
            let bf = b.to_f64().ok();
            let result = match (af, bf) {
                (Some(x), Some(y)) if x.is_nan() => y,
                (Some(x), Some(y)) if y.is_nan() => x,
                (Some(x), Some(y)) => x.min(y),
                (Some(x), None) => x,
                (None, Some(y)) => y,
                (None, None) => f64::NAN,
            };
            out.push(Scalar::Float64(result));
        }
        Self::new(DType::Float64, out)
    }

    fn typed_bool_binary<F>(&self, other: &Self, op: F) -> Option<Self>
    where
        F: Fn(bool, bool) -> bool,
    {
        let left = self.as_bool_slice()?;
        let right = other.as_bool_slice()?;
        (left.len() == right.len()).then(|| {
            Self::from_bool_values(
                left.iter()
                    .zip(right)
                    .map(|(&left_value, &right_value)| op(left_value, right_value))
                    .collect(),
            )
        })
    }

    fn typed_bool_unary<F>(&self, op: F) -> Option<Self>
    where
        F: Fn(bool) -> bool,
    {
        let data = self.as_bool_slice()?;
        Some(Self::from_bool_values(
            data.iter().map(|&value| op(value)).collect(),
        ))
    }

    /// Raw packed `&[bool]` backing + validity mask for a Bool column, covering
    /// BOTH the all-valid backings (`as_bool_slice`: contiguous / LazyAllValidBool
    /// / LazyShiftedBool, whose `self.validity` is the all-valid sentinel) and the
    /// `LazyNullableBool` variant (data + its validity). Returns None for non-Bool
    /// dtypes and for eager Scalar-backed Bool columns carrying mixed NullKind
    /// values (validity not all AND not LazyNullableBool) — those keep the generic
    /// Scalar path, mirroring the fillna/dropna variant-gating.
    fn bool_data_and_validity(&self) -> Option<(&[bool], &ValidityMask)> {
        if self.dtype != DType::Bool {
            return None;
        }
        if let ScalarValues::LazyNullableBool { data, validity, .. } = &self.values {
            return Some((data.as_ref(), validity));
        }
        let slice = self.as_bool_slice()?;
        Some((slice, &self.validity))
    }

    /// Nullable-capable sibling of `typed_bool_binary`: both operands are Bool
    /// columns (all-valid OR `LazyNullableBool`). Apply `op` over the raw bool
    /// slices — a masked slot computes a throwaway value the combined mask then
    /// hides — and AND the two validity masks so the output is missing exactly
    /// where either input is missing, matching the Scalar loop's
    /// `a.is_missing() || b.is_missing() ⇒ Null(Null)`. Present slots use the same
    /// `op(a, b)` on the same bools, and `from_bool_values_with_validity`
    /// materializes a missing slot as `Null(Null) == missing_for_dtype(Bool)`, so
    /// this is bit-identical to the generic loop for Bool×Bool. Skips the
    /// Vec<Scalar> materialization + Column::new. None for non-Bool / mixed
    /// operands (generic numeric-coercing path retained) or length mismatch.
    fn typed_bool_binary_nullable<F>(&self, other: &Self, op: F) -> Option<Self>
    where
        F: Fn(bool, bool) -> bool,
    {
        let (ld, lv) = self.bool_data_and_validity()?;
        let (rd, rv) = other.bool_data_and_validity()?;
        if ld.len() != rd.len() {
            return None;
        }
        let bools: Vec<bool> = ld.iter().zip(rd).map(|(&a, &b)| op(a, b)).collect();
        let out_valid = lv.and_mask(rv);
        Some(Self::from_bool_values_with_validity(bools, out_valid))
    }

    /// Logical AND between two boolean columns.
    pub fn logical_and(&self, other: &Self) -> Result<Self, ColumnError> {
        if self.len() != other.len() {
            return Err(ColumnError::LengthMismatch {
                left: self.len(),
                right: other.len(),
            });
        }
        if let Some(out) = self.typed_bool_binary(other, |left, right| left && right) {
            return Ok(out);
        }
        if let Some(out) = self.typed_bool_binary_nullable(other, |left, right| left && right) {
            return Ok(out);
        }
        let mut out = Vec::with_capacity(self.values.len());
        for (a, b) in self.values.iter().zip(&other.values) {
            if a.is_missing() || b.is_missing() {
                out.push(Scalar::Null(NullKind::Null));
                continue;
            }
            let av = match a {
                Scalar::Bool(x) => *x,
                _ => a.to_f64().map(|v| v != 0.0).unwrap_or(false),
            };
            let bv = match b {
                Scalar::Bool(x) => *x,
                _ => b.to_f64().map(|v| v != 0.0).unwrap_or(false),
            };
            out.push(Scalar::Bool(av && bv));
        }
        Self::new(DType::Bool, out)
    }

    /// Logical OR between two boolean columns.
    pub fn logical_or(&self, other: &Self) -> Result<Self, ColumnError> {
        if self.len() != other.len() {
            return Err(ColumnError::LengthMismatch {
                left: self.len(),
                right: other.len(),
            });
        }
        if let Some(out) = self.typed_bool_binary(other, |left, right| left || right) {
            return Ok(out);
        }
        if let Some(out) = self.typed_bool_binary_nullable(other, |left, right| left || right) {
            return Ok(out);
        }
        let mut out = Vec::with_capacity(self.values.len());
        for (a, b) in self.values.iter().zip(&other.values) {
            if a.is_missing() || b.is_missing() {
                out.push(Scalar::Null(NullKind::Null));
                continue;
            }
            let av = match a {
                Scalar::Bool(x) => *x,
                _ => a.to_f64().map(|v| v != 0.0).unwrap_or(false),
            };
            let bv = match b {
                Scalar::Bool(x) => *x,
                _ => b.to_f64().map(|v| v != 0.0).unwrap_or(false),
            };
            out.push(Scalar::Bool(av || bv));
        }
        Self::new(DType::Bool, out)
    }

    /// Logical XOR between two boolean columns.
    pub fn logical_xor(&self, other: &Self) -> Result<Self, ColumnError> {
        if self.len() != other.len() {
            return Err(ColumnError::LengthMismatch {
                left: self.len(),
                right: other.len(),
            });
        }
        if let Some(out) = self.typed_bool_binary(other, |left, right| left ^ right) {
            return Ok(out);
        }
        if let Some(out) = self.typed_bool_binary_nullable(other, |left, right| left ^ right) {
            return Ok(out);
        }
        let mut out = Vec::with_capacity(self.values.len());
        for (a, b) in self.values.iter().zip(&other.values) {
            if a.is_missing() || b.is_missing() {
                out.push(Scalar::Null(NullKind::Null));
                continue;
            }
            let av = match a {
                Scalar::Bool(x) => *x,
                _ => a.to_f64().map(|v| v != 0.0).unwrap_or(false),
            };
            let bv = match b {
                Scalar::Bool(x) => *x,
                _ => b.to_f64().map(|v| v != 0.0).unwrap_or(false),
            };
            out.push(Scalar::Bool(av ^ bv));
        }
        Self::new(DType::Bool, out)
    }

    /// Logical NOT (element-wise negation to boolean).
    pub fn logical_not(&self) -> Result<Self, ColumnError> {
        if let Some(out) = self.typed_bool_unary(|value| !value) {
            return Ok(out);
        }
        // Typed Int64/Float64 (all-valid + nullable ⇒ Bool out): logical_not of a
        // numeric is `!(v != 0) == (v == 0)`. Build the Bool buffer straight over the
        // raw slice + an explicit validity mask, skipping the Vec<Scalar> materialization
        // + Column::new. Bit-identical to the Scalar loop: present ⇒ Bool(v == 0);
        // missing (validity-unset, OR a valid-bit-set NaN for Float64 which the loop's
        // is_missing() drops) ⇒ Null(Null) == missing_for_dtype(Bool). Int64 has no NaN
        // so present == validity-set; Float64 present == validity-set AND non-NaN
        // (matching the loop's `to_f64()` on a NON-missing scalar). ±inf ⇒ inf != 0 ⇒
        // Bool(false), kept. No from_f64_values NaN-render trap (Bool out + explicit
        // mask). Other dtypes / mixed keep the Scalar path.
        if self.dtype == DType::Int64
            && let Some((data, validity)) = self.as_i64_slice_with_validity()
        {
            let bools: Vec<bool> = data.iter().map(|&x| x == 0).collect();
            return Ok(Self::from_bool_values_with_validity(
                bools,
                validity.clone(),
            ));
        }
        if self.dtype == DType::Float64
            && let Some((data, validity)) = self.as_f64_slice_with_validity()
        {
            let mut bools = vec![false; data.len()];
            let mut vmask = ValidityMask::all_valid(data.len());
            for i in 0..data.len() {
                if validity.get(i) && !data[i].is_nan() {
                    bools[i] = data[i] == 0.0;
                } else {
                    vmask.set(i, false);
                }
            }
            return Ok(Self::from_bool_values_with_validity(bools, vmask));
        }
        let mut out = Vec::with_capacity(self.values.len());
        for v in &self.values {
            if v.is_missing() {
                out.push(Scalar::Null(NullKind::Null));
                continue;
            }
            let bv = match v {
                Scalar::Bool(x) => *x,
                _ => v.to_f64().map(|x| x != 0.0).unwrap_or(false),
            };
            out.push(Scalar::Bool(!bv));
        }
        Self::new(DType::Bool, out)
    }

    /// Borrow the raw `&[i64]` nanosecond backing + validity + NaT sentinel for an
    /// all-valid or nullable `Datetime64`/`Timedelta64` column. `None` for any other
    /// dtype or a non-materialized temporal backing (which keeps the generic Scalar
    /// path). Shared by the typed temporal arms of `binary_comparison` and
    /// `compare_scalar`; a method (not a closure) so the borrows tie to `self`.
    fn temporal_i64_backing(&self) -> Option<(&[i64], &ValidityMask, i64)> {
        let (all_valid, nat) = match self.dtype {
            DType::Datetime64 => (self.as_datetime64_slice(), Timestamp::NAT),
            DType::Timedelta64 => (self.as_timedelta64_slice(), Timedelta::NAT),
            _ => return None,
        };
        if let Some(slice) = all_valid {
            return Some((slice, &self.validity, nat));
        }
        match &self.values {
            ScalarValues::LazyNullableDatetime64 { data, validity, .. }
            | ScalarValues::LazyNullableTimedelta64 { data, validity, .. } => {
                Some((data.as_slice(), validity, nat))
            }
            _ => None,
        }
    }

    /// Element-wise comparison producing a `Bool`-typed column.
    ///
    /// Both columns must have the same length. Missing values (Null or NaN)
    /// propagate: if either operand is missing, the result is missing.
    pub fn binary_comparison(&self, right: &Self, op: ComparisonOp) -> Result<Self, ColumnError> {
        if self.len() != right.len() {
            return Err(ColumnError::LengthMismatch {
                left: self.len(),
                right: right.len(),
            });
        }

        // Typed fast path: both operands are all-valid contiguous Float64,
        // Int64, or Bool, so compare over the buffers and build the Bool result via
        // from_bool_values — no Scalar materialization or per-element dispatch.
        // Bit-identical to scalar_compare's same-dtype arm (the identical `a <op>
        // b`); all-valid inputs mean no Null branch, and the comparisons never
        // see a NaN (as_f64_slice excludes it).
        // Hoist `op` out of the element loop into six monomorphic branchless
        // closures so each comparison auto-vectorizes (a per-element `match op`
        // is opaque to the vectorizer and serializes the loop — the same lever
        // as `Series::between`). Bit-identical: the comparison performed per
        // element is unchanged, only the control flow that selects it moves out.
        if let (Some(l), Some(r)) = (self.as_f64_slice(), right.as_f64_slice()) {
            let zip = || l.iter().zip(r);
            let bools: Vec<bool> = match op {
                ComparisonOp::Gt => zip().map(|(&a, &b)| a > b).collect(),
                ComparisonOp::Lt => zip().map(|(&a, &b)| a < b).collect(),
                ComparisonOp::Eq => zip().map(|(&a, &b)| a == b).collect(),
                ComparisonOp::Ne => zip().map(|(&a, &b)| a != b).collect(),
                ComparisonOp::Ge => zip().map(|(&a, &b)| a >= b).collect(),
                ComparisonOp::Le => zip().map(|(&a, &b)| a <= b).collect(),
            };
            return Ok(Self::from_bool_values(bools));
        }
        if let (Some(l), Some(r)) = (self.as_i64_slice(), right.as_i64_slice()) {
            let zip = || l.iter().zip(r);
            let bools: Vec<bool> = match op {
                ComparisonOp::Gt => zip().map(|(&a, &b)| a > b).collect(),
                ComparisonOp::Lt => zip().map(|(&a, &b)| a < b).collect(),
                ComparisonOp::Eq => zip().map(|(&a, &b)| a == b).collect(),
                ComparisonOp::Ne => zip().map(|(&a, &b)| a != b).collect(),
                ComparisonOp::Ge => zip().map(|(&a, &b)| a >= b).collect(),
                ComparisonOp::Le => zip().map(|(&a, &b)| a <= b).collect(),
            };
            return Ok(Self::from_bool_values(bools));
        }
        if let (Some(l), Some(r)) = (self.as_bool_slice(), right.as_bool_slice()) {
            let zip = || l.iter().zip(r);
            let bools: Vec<bool> = match op {
                ComparisonOp::Gt => zip().map(|(&a, &b)| a && !b).collect(),
                ComparisonOp::Lt => zip().map(|(&a, &b)| !a && b).collect(),
                ComparisonOp::Eq => zip().map(|(&a, &b)| a == b).collect(),
                ComparisonOp::Ne => zip().map(|(&a, &b)| a != b).collect(),
                ComparisonOp::Ge => zip().map(|(&a, &b)| a >= b).collect(),
                ComparisonOp::Le => zip().map(|(&a, &b)| a <= b).collect(),
            };
            return Ok(Self::from_bool_values(bools));
        }
        // Typed NULLABLE Bool fast path (sister to the all-valid Bool arm above): the
        // all-valid arm needs BOTH `as_bool_slice()` (validity.all()), so any pair with a
        // nullable Bool operand — (nullable, nullable), (all-valid, nullable), (nullable,
        // all-valid) — fell to the generic per-element Scalar loop over Vec<Scalar::Bool>.
        // Read the raw `&[bool]` backings + validity and apply the SAME per-op bool
        // expressions, carrying the combined validity (present iff BOTH present == the
        // generic `!(l.is_missing() || r.is_missing())`; Bool has no NaN sentinel, so
        // "missing" is validity-unset only — no buffer scan). Bit-identical to the generic
        // path's `scalar_compare` Bool arm. A local `fn` ties the borrows to the `&Column`.
        fn bool_backing(col: &Column) -> Option<(&[bool], &ValidityMask)> {
            if col.dtype != DType::Bool {
                return None;
            }
            if let Some(slice) = col.as_bool_slice() {
                return Some((slice, &col.validity));
            }
            if let ScalarValues::LazyNullableBool { data, validity, .. } = &col.values {
                return Some((data.as_slice(), validity));
            }
            None
        }
        if let (Some((l, lv)), Some((r, rv))) = (bool_backing(self), bool_backing(right)) {
            let zip = || l.iter().zip(r);
            let bools: Vec<bool> = match op {
                ComparisonOp::Gt => zip().map(|(&a, &b)| a && !b).collect(),
                ComparisonOp::Lt => zip().map(|(&a, &b)| !a && b).collect(),
                ComparisonOp::Eq => zip().map(|(&a, &b)| a == b).collect(),
                ComparisonOp::Ne => zip().map(|(&a, &b)| a != b).collect(),
                ComparisonOp::Ge => zip().map(|(&a, &b)| a >= b).collect(),
                ComparisonOp::Le => zip().map(|(&a, &b)| a <= b).collect(),
            };
            return Ok(Self::from_bool_values_with_validity(bools, lv.and_mask(rv)));
        }
        // Typed MIXED Int64×Float64 fast path: the both-same-dtype arms above miss a
        // mixed numeric pair, dropping it to the generic per-element Scalar
        // `scalar_compare`. Build an f64 view per side (an all-valid Float64 borrows its
        // `&[f64]`; an all-valid Int64 maps `v as f64` once) and compare with the hoisted
        // op. Bit-identical to `scalar_compare`'s Int64/Float64 arm, which promotes both
        // to f64 (`a as f64 <op> b`); `as_f64_slice`/`as_i64_slice` are all-valid with no
        // present NaN, so there is no Null/NaN branch. Both-Int64 keeps the EXACT i64
        // compare arm above (never f64-promoted here — matters for |v| > 2^53). A local
        // `fn` (not a closure) so elision ties the `Cow<'_>` output to the `&Column` arg.
        fn f64_view(col: &Column) -> Option<std::borrow::Cow<'_, [f64]>> {
            if let Some(d) = col.as_f64_slice() {
                Some(std::borrow::Cow::Borrowed(d))
            } else {
                col.as_i64_slice()
                    .map(|d| std::borrow::Cow::Owned(d.iter().map(|&v| v as f64).collect()))
            }
        }
        if let (Some(lv), Some(rv)) = (f64_view(self), f64_view(right)) {
            let (l, r) = (lv.as_ref(), rv.as_ref());
            let zip = || l.iter().zip(r);
            let bools: Vec<bool> = match op {
                ComparisonOp::Gt => zip().map(|(&a, &b)| a > b).collect(),
                ComparisonOp::Lt => zip().map(|(&a, &b)| a < b).collect(),
                ComparisonOp::Eq => zip().map(|(&a, &b)| a == b).collect(),
                ComparisonOp::Ne => zip().map(|(&a, &b)| a != b).collect(),
                ComparisonOp::Ge => zip().map(|(&a, &b)| a >= b).collect(),
                ComparisonOp::Le => zip().map(|(&a, &b)| a <= b).collect(),
            };
            return Ok(Self::from_bool_values(bools));
        }
        // Typed NULLABLE Float64 fast path (sister to the compare_scalar nullable arm):
        // the all-valid arms above bail on ANY missing, so a nullable Float64 vs
        // nullable Float64 pair fell to the generic per-element Scalar `scalar_compare`
        // over `Vec<Scalar>`. Compare over the two raw `&[f64]` (masked slots' bools are
        // never observed) and carry the combined validity (present iff BOTH present).
        // Bit-identical to the Scalar path: a present pair (both validity-set, so both
        // non-NaN — fp clears the validity bit for any NaN) yields `Bool(a <op> b)` (the
        // same `scalar_compare` "both to f64" branch), an either-missing slot yields the
        // invalid bit == `Null(NullKind::Null)`. `lv AND rv` is exactly the generic
        // `!(l.is_missing() || r.is_missing())`.
        if let (Some((ld, lv)), Some((rd, rv))) = (
            self.as_f64_slice_with_validity(),
            right.as_f64_slice_with_validity(),
        ) {
            let zip = || ld.iter().zip(rd);
            let bools: Vec<bool> = match op {
                ComparisonOp::Gt => zip().map(|(&a, &b)| a > b).collect(),
                ComparisonOp::Lt => zip().map(|(&a, &b)| a < b).collect(),
                ComparisonOp::Eq => zip().map(|(&a, &b)| a == b).collect(),
                ComparisonOp::Ne => zip().map(|(&a, &b)| a != b).collect(),
                ComparisonOp::Ge => zip().map(|(&a, &b)| a >= b).collect(),
                ComparisonOp::Le => zip().map(|(&a, &b)| a <= b).collect(),
            };
            return Ok(Self::from_bool_values_with_validity(bools, lv.and_mask(rv)));
        }
        // Typed NULLABLE Int64 fast path (sister to the nullable Float64 arm above): a
        // nullable Int64 vs nullable Int64 pair also fell to the generic Scalar
        // `scalar_compare`. Compare the two raw `&[i64]` EXACTLY — never f64-promoted,
        // matching `scalar_compare`'s both-Int64 branch (an i64 comparison; matters for
        // `|v| > 2^53` where `v as f64` would round) — and carry the combined validity.
        // Bit-identical: present pair (both validity-set) => `Bool(a <op> b)`, either
        // missing => the invalid bit == `Null(NullKind::Null)`; `lv AND rv` is exactly
        // the generic `!(l.is_missing() || r.is_missing())`. All-valid Int64 pairs still
        // take the exact-i64 borrow arm higher up (fires first).
        if let (Some((ld, lv)), Some((rd, rv))) = (
            self.as_i64_slice_with_validity(),
            right.as_i64_slice_with_validity(),
        ) {
            let zip = || ld.iter().zip(rd);
            let bools: Vec<bool> = match op {
                ComparisonOp::Gt => zip().map(|(&a, &b)| a > b).collect(),
                ComparisonOp::Lt => zip().map(|(&a, &b)| a < b).collect(),
                ComparisonOp::Eq => zip().map(|(&a, &b)| a == b).collect(),
                ComparisonOp::Ne => zip().map(|(&a, &b)| a != b).collect(),
                ComparisonOp::Ge => zip().map(|(&a, &b)| a >= b).collect(),
                ComparisonOp::Le => zip().map(|(&a, &b)| a <= b).collect(),
            };
            return Ok(Self::from_bool_values_with_validity(bools, lv.and_mask(rv)));
        }
        // Typed MIXED-NULLABLE fast path: a nullable Int64 vs nullable Float64 pair (either
        // side nullable, dtypes differ) matched neither same-dtype nullable arm above and
        // fell to the generic Scalar `scalar_compare`. Build a validity-aware f64 view per
        // side (an all-valid/nullable Float64 borrows its `&[f64]` + validity; an
        // all-valid/nullable Int64 maps `v as f64` + validity) and compare f64-promoted,
        // carrying the combined validity. Bit-identical to `scalar_compare`'s Int64/Float64
        // arm (which promotes both to f64); present iff both present (`lv AND rv`), masked
        // slots' bools never observed. Both-Int64 already took the EXACT-i64 nullable arm
        // above (never reaches here), so no Int64 pair is f64-promoted; both-Float64 took
        // its arm. A local `fn` so elision ties the outputs' lifetimes to the `&Column`.
        fn nullable_f64_view(col: &Column) -> Option<(std::borrow::Cow<'_, [f64]>, &ValidityMask)> {
            if let Some((d, v)) = col.as_f64_slice_with_validity() {
                Some((std::borrow::Cow::Borrowed(d), v))
            } else if let Some((d, v)) = col.as_i64_slice_with_validity() {
                Some((
                    std::borrow::Cow::Owned(d.iter().map(|&x| x as f64).collect()),
                    v,
                ))
            } else {
                None
            }
        }
        if let (Some((lc, lv)), Some((rc, rv))) =
            (nullable_f64_view(self), nullable_f64_view(right))
        {
            let (l, r) = (lc.as_ref(), rc.as_ref());
            let zip = || l.iter().zip(r);
            let bools: Vec<bool> = match op {
                ComparisonOp::Gt => zip().map(|(&a, &b)| a > b).collect(),
                ComparisonOp::Lt => zip().map(|(&a, &b)| a < b).collect(),
                ComparisonOp::Eq => zip().map(|(&a, &b)| a == b).collect(),
                ComparisonOp::Ne => zip().map(|(&a, &b)| a != b).collect(),
                ComparisonOp::Ge => zip().map(|(&a, &b)| a >= b).collect(),
                ComparisonOp::Le => zip().map(|(&a, &b)| a <= b).collect(),
            };
            return Ok(Self::from_bool_values_with_validity(bools, lv.and_mask(rv)));
        }

        // Typed Utf8 fast path (all-valid AND nullable, either side): both operands are
        // contiguous-Utf8 (an all-valid `LazyContiguousUtf8`/hex backing, or a
        // `LazyNullableUtf8`). The generic loop below materializes BOTH `Vec<Scalar::Utf8>`
        // (a heap `String` per row × two columns) just to feed `scalar_compare`, whose
        // Utf8 arm is `a <op> b` on the two `String`s == byte-lexicographic `str::cmp`.
        // Compare each row's raw `&[u8]` spans directly and combine the validity with
        // `and_mask` (present iff BOTH present == the generic `!(l.is_missing() ||
        // r.is_missing())`). Bit-identical: `&[u8]` order == `String` order for valid
        // UTF-8 (same lever as the typed Utf8 `searchsorted` / `compare_scalar`), a
        // present pair ⇒ `Bool(lrow <op> rrow)`, an either-missing slot ⇒ the invalid bit
        // == `Null(NullKind::Null)` (its empty-span bool is never observed). A local `fn`
        // (not a closure) ties the borrowed spans/validity lifetimes to the `&Column`.
        fn utf8_spans(col: &Column) -> Option<(&[u8], &[usize], &ValidityMask)> {
            if col.dtype != DType::Utf8 {
                return None;
            }
            if let ScalarValues::LazyNullableUtf8 {
                bytes,
                offsets,
                validity,
                ..
            } = &col.values
            {
                return Some((bytes, offsets, validity));
            }
            let (bytes, offsets) = col.as_utf8_contiguous()?;
            Some((bytes, offsets, &col.validity))
        }
        if let (Some((lb, lo, lv)), Some((rb, ro, rv))) = (utf8_spans(self), utf8_spans(right)) {
            let n = lo.len() - 1;
            let lrow = |i: usize| &lb[lo[i]..lo[i + 1]];
            let rrow = |i: usize| &rb[ro[i]..ro[i + 1]];
            let bools: Vec<bool> = match op {
                ComparisonOp::Gt => (0..n).map(|i| lrow(i) > rrow(i)).collect(),
                ComparisonOp::Lt => (0..n).map(|i| lrow(i) < rrow(i)).collect(),
                ComparisonOp::Eq => (0..n).map(|i| lrow(i) == rrow(i)).collect(),
                ComparisonOp::Ne => (0..n).map(|i| lrow(i) != rrow(i)).collect(),
                ComparisonOp::Ge => (0..n).map(|i| lrow(i) >= rrow(i)).collect(),
                ComparisonOp::Le => (0..n).map(|i| lrow(i) <= rrow(i)).collect(),
            };
            return Ok(Self::from_bool_values_with_validity(bools, lv.and_mask(rv)));
        }

        // Typed TEMPORAL fast path: both operands are Datetime64, or both are
        // Timedelta64 (all-valid OR nullable). Temporal scalars are i64 nanoseconds
        // but are NOT numeric to `to_f64`, so the generic loop below routes any
        // PRESENT temporal pair through `scalar_compare` -> `Scalar::to_f64()`, which
        // returns `Err(NonNumericValue)` — i.e. `s_dt1 < s_dt2` / `s_td1 == s_td2`
        // ERROR outright today (only the Series-vs-scalar `compare_scalar` path
        // handled temporal). Compare the raw `&[i64]` backings EXACTLY — pandas
        // compares datetime64[ns]/timedelta64[ns] as i64; an f64 promotion would
        // round for `|ns| > 2^53` (epoch-ns are ~1.6e18) — and mask a row where
        // either side is missing: validity bit unset OR the NaT sentinel in the
        // buffer, which is EXACTLY the generic path's `l.is_missing() ||
        // r.is_missing()` (`Datetime64(NAT)`/`Timedelta64(NAT)` materialize as
        // missing). A masked slot's bool (computed over a NaT sentinel) is never
        // observed. `temporal_i64_backing` (a Column method, shared with `compare_scalar`)
        // borrows the raw ns backing + validity + NaT sentinel for an all-valid or nullable
        // Datetime64/Timedelta64 column.
        if self.dtype == right.dtype
            && let (Some((l, lv, nat)), Some((r, rv, _))) =
                (self.temporal_i64_backing(), right.temporal_i64_backing())
        {
            let zip = || l.iter().zip(r);
            let bools: Vec<bool> = match op {
                ComparisonOp::Gt => zip().map(|(&a, &b)| a > b).collect(),
                ComparisonOp::Lt => zip().map(|(&a, &b)| a < b).collect(),
                ComparisonOp::Eq => zip().map(|(&a, &b)| a == b).collect(),
                ComparisonOp::Ne => zip().map(|(&a, &b)| a != b).collect(),
                ComparisonOp::Ge => zip().map(|(&a, &b)| a >= b).collect(),
                ComparisonOp::Le => zip().map(|(&a, &b)| a <= b).collect(),
            };
            let mut present = lv.and_mask(rv);
            for (i, (&a, &b)) in l.iter().zip(r).enumerate() {
                if a == nat || b == nat {
                    present.set(i, false);
                }
            }
            return Ok(Self::from_bool_values_with_validity(bools, present));
        }

        let values = self
            .values
            .iter()
            .zip(&right.values)
            .map(|(l, r)| -> Result<Scalar, ColumnError> {
                if l.is_missing() || r.is_missing() {
                    return Ok(Scalar::Null(NullKind::Null));
                }
                let result = scalar_compare(l, r, op)?;
                Ok(Scalar::Bool(result))
            })
            .collect::<Result<Vec<_>, _>>()?;

        Self::new(DType::Bool, values)
    }

    /// Element-wise equality, matching `pd.Series.eq()`.
    pub fn eq(&self, right: &Self) -> Result<Self, ColumnError> {
        self.binary_comparison(right, ComparisonOp::Eq)
    }

    /// Element-wise inequality, matching `pd.Series.ne()`.
    pub fn ne(&self, right: &Self) -> Result<Self, ColumnError> {
        self.binary_comparison(right, ComparisonOp::Ne)
    }

    /// Element-wise less-than comparison, matching `pd.Series.lt()`.
    pub fn lt(&self, right: &Self) -> Result<Self, ColumnError> {
        self.binary_comparison(right, ComparisonOp::Lt)
    }

    /// Element-wise less-than-or-equal comparison, matching `pd.Series.le()`.
    pub fn le(&self, right: &Self) -> Result<Self, ColumnError> {
        self.binary_comparison(right, ComparisonOp::Le)
    }

    /// Element-wise greater-than comparison, matching `pd.Series.gt()`.
    pub fn gt(&self, right: &Self) -> Result<Self, ColumnError> {
        self.binary_comparison(right, ComparisonOp::Gt)
    }

    /// Element-wise greater-than-or-equal comparison, matching `pd.Series.ge()`.
    pub fn ge(&self, right: &Self) -> Result<Self, ColumnError> {
        self.binary_comparison(right, ComparisonOp::Ge)
    }

    /// Compare every element against a scalar value, producing a `Bool`-typed column.
    ///
    /// Missing values in the column propagate as missing in the result.
    pub fn compare_scalar(&self, scalar: &Scalar, op: ComparisonOp) -> Result<Self, ColumnError> {
        if scalar.is_missing() {
            // Comparing against missing always produces all-missing.
            let values = vec![Scalar::Null(NullKind::Null); self.len()];
            return Self::new(DType::Bool, values);
        }

        // Typed fast path (br-frankenpandas-2kpwa): when self is an all-valid
        // contiguous numeric buffer, compare against the scalar directly over the
        // typed slice and build the Bool result via from_bool_values, skipping the
        // per-element Scalar dispatch in scalar_compare and the 32-byte Scalar alloc
        // for every output cell. Bit-identical to the scalar path:
        //   * Float64 self vs any numeric scalar reduces in scalar_compare to the
        //     final "convert both to f64" branch, i.e. `v <op> scalar.to_f64()`.
        //   * Int64 self vs Int64 scalar takes scalar_compare's both-Int64 branch,
        //     i.e. the i64 comparison. (Int64 vs float scalar still uses the AoS
        //     path so f64-promotion semantics stay identical.)
        if let Some(data) = self.as_f64_slice()
            && let Ok(s) = scalar.to_f64()
        {
            // Hoist the `op` match OUT of the per-element closure: a `match op`
            // inside the map body is a loop-invariant branch that blocks SIMD
            // (scalar eq was 0.44x pandas). Six monomorphic `v <op> s` loops each
            // auto-vectorize to a packed f64 compare. Bit-identical (same per-op
            // comparison; only the dispatch moved out of the loop).
            let bools: Vec<bool> = match op {
                ComparisonOp::Gt => data.iter().map(|&v| v > s).collect(),
                ComparisonOp::Lt => data.iter().map(|&v| v < s).collect(),
                ComparisonOp::Eq => data.iter().map(|&v| v == s).collect(),
                ComparisonOp::Ne => data.iter().map(|&v| v != s).collect(),
                ComparisonOp::Ge => data.iter().map(|&v| v >= s).collect(),
                ComparisonOp::Le => data.iter().map(|&v| v <= s).collect(),
            };
            return Ok(Self::from_bool_values(bools));
        }
        if let Some(data) = self.as_i64_slice()
            && let Scalar::Int64(s) = scalar
        {
            let s = *s;
            // Hoist `op` out of the closure (see the Float64 arm) so each
            // monomorphic i64 compare loop auto-vectorizes. Bit-identical.
            let bools: Vec<bool> = match op {
                ComparisonOp::Gt => data.iter().map(|&v| v > s).collect(),
                ComparisonOp::Lt => data.iter().map(|&v| v < s).collect(),
                ComparisonOp::Eq => data.iter().map(|&v| v == s).collect(),
                ComparisonOp::Ne => data.iter().map(|&v| v != s).collect(),
                ComparisonOp::Ge => data.iter().map(|&v| v >= s).collect(),
                ComparisonOp::Le => data.iter().map(|&v| v <= s).collect(),
            };
            return Ok(Self::from_bool_values(bools));
        }

        // Nullable Float64 fast path: the all-valid `as_f64_slice` above bails on
        // ANY NaN/missing, so a nullable Float64 column fell to the generic
        // per-element Scalar dispatch + 32-byte Scalar/cell (compare on a 10%-null
        // 5M column was ~415ms / 237x slower than pandas). Compare over the raw
        // &[f64] and carry the source validity onto a typed nullable Bool result.
        // Bit-identical to the Scalar path: present slot ⇒ `Bool(v <op> s)` (same
        // `scalar_compare` "convert both to f64" branch for Float64 vs numeric),
        // missing slot ⇒ `from_bool_values_with_validity`'s invalid bit, which is
        // `Null(NullKind::Null)` (= the Scalar path's missing arm); the bool value
        // at a masked slot is never observed.
        if let Some((data, validity)) = self.as_f64_slice_with_validity()
            && let Ok(s) = scalar.to_f64()
        {
            // Hoist `op` out of the closure (see the all-valid Float64 arm): the
            // compare over the raw &[f64] vectorizes; masked slots are dropped by
            // the carried validity, so the bool value there is never observed.
            // Bit-identical.
            let bools: Vec<bool> = match op {
                ComparisonOp::Gt => data.iter().map(|&v| v > s).collect(),
                ComparisonOp::Lt => data.iter().map(|&v| v < s).collect(),
                ComparisonOp::Eq => data.iter().map(|&v| v == s).collect(),
                ComparisonOp::Ne => data.iter().map(|&v| v != s).collect(),
                ComparisonOp::Ge => data.iter().map(|&v| v >= s).collect(),
                ComparisonOp::Le => data.iter().map(|&v| v <= s).collect(),
            };
            return Ok(Self::from_bool_values_with_validity(
                bools,
                validity.clone(),
            ));
        }

        // Nullable Int64 sibling: keep comparisons exact over the raw i64 buffer
        // and carry the source validity into the Bool result. The all-valid arm
        // above already handles dense Int64; without this nullable arm we fell
        // through to `values()` and allocated one 32-byte Scalar per input and
        // output cell. This deliberately accepts only an Int64 scalar because
        // mixed Int64/Float64 comparison uses scalar_compare's f64-promotion
        // semantics. Masked slots' computed bools are never observed.
        if let Some((data, validity)) = self.as_i64_slice_with_validity()
            && let Scalar::Int64(s) = scalar
        {
            let s = *s;
            let bools: Vec<bool> = match op {
                ComparisonOp::Gt => data.iter().map(|&v| v > s).collect(),
                ComparisonOp::Lt => data.iter().map(|&v| v < s).collect(),
                ComparisonOp::Eq => data.iter().map(|&v| v == s).collect(),
                ComparisonOp::Ne => data.iter().map(|&v| v != s).collect(),
                ComparisonOp::Ge => data.iter().map(|&v| v >= s).collect(),
                ComparisonOp::Le => data.iter().map(|&v| v <= s).collect(),
            };
            return Ok(Self::from_bool_values_with_validity(
                bools,
                validity.clone(),
            ));
        }

        // Typed Utf8 fast path: an all-valid contiguous-Utf8 column compared against a
        // Utf8 scalar. The generic loop below drives `self.values.iter()`, which
        // materializes the WHOLE `Vec<Scalar::Utf8>` — one heap `String` per row (via
        // the `get_or_init` OnceCell) — purely to feed `scalar_compare`, whose Utf8 arm
        // is `a <op> b` on the two `String`s == byte-lexicographic `str::cmp`. Instead
        // compare each row's raw `&[u8]` span (`bytes[offsets[i]..offsets[i+1]]`) against
        // the needle bytes directly and build the Bool via `from_bool_values`.
        // Bit-identical: `&[u8]` lexicographic order == `&str`/`String` order for valid
        // UTF-8 (same lever as the typed Utf8 `searchsorted`), so `row <op> needle`
        // matches `scalar_compare(row, needle, op)` for every op. `as_utf8_contiguous`
        // gates on an all-valid backing, so the generic path's `is_missing ⇒ Null(Null)`
        // branch never applies here; a nullable / Eager / non-contiguous Utf8 column
        // declines the accessor and keeps the missing-aware generic path. Hoist `op` out
        // of the per-row closure (mirror of the numeric arms) so each row runs one
        // monomorphic slice compare.
        if let Scalar::Utf8(needle) = scalar
            && let Some((bytes, offsets)) = self.as_utf8_contiguous()
        {
            let needle = needle.as_bytes();
            let n = offsets.len() - 1;
            let row = |i: usize| &bytes[offsets[i]..offsets[i + 1]];
            let bools: Vec<bool> = match op {
                ComparisonOp::Gt => (0..n).map(|i| row(i) > needle).collect(),
                ComparisonOp::Lt => (0..n).map(|i| row(i) < needle).collect(),
                ComparisonOp::Eq => (0..n).map(|i| row(i) == needle).collect(),
                ComparisonOp::Ne => (0..n).map(|i| row(i) != needle).collect(),
                ComparisonOp::Ge => (0..n).map(|i| row(i) >= needle).collect(),
                ComparisonOp::Le => (0..n).map(|i| row(i) <= needle).collect(),
            };
            return Ok(Self::from_bool_values(bools));
        }

        // Nullable sibling of the arm above: a NULLABLE contiguous-Utf8 column
        // (`LazyNullableUtf8`, the shape a CSV/parquet load or `from_utf8_values_with
        // _validity` produces for a string column WITH missing rows) declined
        // `as_utf8_contiguous` (which gates on `validity.all()`), so it fell to the
        // generic `Vec<Scalar::Utf8>` materialization. Read the raw `&[u8]` spans +
        // validity directly: compare every present row's span against the needle (an
        // invalid slot carries an empty span whose computed bool the carried validity
        // then hides) and carry the source validity onto a nullable Bool result.
        // Bit-identical to the generic path: present ⇒ `Bool(row <op> needle)` (the same
        // `scalar_compare` Utf8 arm), missing ⇒ `from_bool_values_with_validity`'s
        // invalid bit == `Null(NullKind::Null)` (= the generic `is_missing` arm).
        // `LazyNullableUtf8Range` (join-output shape, no contiguous byte backing) and
        // Eager nullable Utf8 keep the generic path.
        if let Scalar::Utf8(needle) = scalar
            && let ScalarValues::LazyNullableUtf8 {
                bytes,
                offsets,
                validity,
                ..
            } = &self.values
        {
            let needle = needle.as_bytes();
            let n = offsets.len() - 1;
            let row = |i: usize| &bytes[offsets[i]..offsets[i + 1]];
            let bools: Vec<bool> = match op {
                ComparisonOp::Gt => (0..n).map(|i| row(i) > needle).collect(),
                ComparisonOp::Lt => (0..n).map(|i| row(i) < needle).collect(),
                ComparisonOp::Eq => (0..n).map(|i| row(i) == needle).collect(),
                ComparisonOp::Ne => (0..n).map(|i| row(i) != needle).collect(),
                ComparisonOp::Ge => (0..n).map(|i| row(i) >= needle).collect(),
                ComparisonOp::Le => (0..n).map(|i| row(i) <= needle).collect(),
            };
            return Ok(Self::from_bool_values_with_validity(
                bools,
                validity.clone(),
            ));
        }

        // Typed TEMPORAL scalar fast path: a Datetime64 column vs a (non-NaT) Datetime64
        // scalar, or a Timedelta64 column vs a (non-NaT) Timedelta64 scalar. Temporal
        // scalars are i64 nanoseconds but are NOT numeric to `to_f64`, so the generic loop
        // below routes a PRESENT row through `scalar_compare` -> `Scalar::to_f64()`, which
        // returns `Err(NonNumericValue)` — i.e. `df["date"] > threshold` (the canonical
        // time-series filter) ERRORS today. Compare the raw `&[i64]` backing to the
        // scalar's ns EXACTLY — pandas compares datetime64[ns]/timedelta64[ns] as i64; an
        // f64 promotion would round for `|ns| > 2^53` (epoch-ns are ~1.6e18) — and mask a
        // row whose column value is missing (validity bit unset OR the NaT sentinel in the
        // buffer, == the generic `v.is_missing()`). A NaT scalar keeps the generic path.
        let temporal_needle = match (self.dtype, scalar) {
            (DType::Datetime64, Scalar::Datetime64(s)) if *s != Timestamp::NAT => Some(*s),
            (DType::Timedelta64, Scalar::Timedelta64(s)) if *s != Timedelta::NAT => Some(*s),
            _ => None,
        };
        if let Some(needle) = temporal_needle
            && let Some((data, validity, nat)) = self.temporal_i64_backing()
        {
            let bools: Vec<bool> = match op {
                ComparisonOp::Gt => data.iter().map(|&v| v > needle).collect(),
                ComparisonOp::Lt => data.iter().map(|&v| v < needle).collect(),
                ComparisonOp::Eq => data.iter().map(|&v| v == needle).collect(),
                ComparisonOp::Ne => data.iter().map(|&v| v != needle).collect(),
                ComparisonOp::Ge => data.iter().map(|&v| v >= needle).collect(),
                ComparisonOp::Le => data.iter().map(|&v| v <= needle).collect(),
            };
            let mut present = validity.clone();
            for (i, &v) in data.iter().enumerate() {
                if v == nat {
                    present.set(i, false);
                }
            }
            return Ok(Self::from_bool_values_with_validity(bools, present));
        }

        let values = self
            .values
            .iter()
            .map(|v| -> Result<Scalar, ColumnError> {
                if v.is_missing() {
                    return Ok(Scalar::Null(NullKind::Null));
                }
                let result = scalar_compare(v, scalar, op)?;
                Ok(Scalar::Bool(result))
            })
            .collect::<Result<Vec<_>, _>>()?;

        Self::new(DType::Bool, values)
    }

    /// Select elements where `mask` is `true`, producing a new column.
    ///
    /// The mask must be a `Bool`-typed column of the same length.
    /// Missing values in the mask are treated as `false` (not selected).
    pub fn filter_by_mask(&self, mask: &Self) -> Result<Self, ColumnError> {
        if mask.dtype == DType::Null {
            if self.len() != mask.len() {
                return Err(ColumnError::LengthMismatch {
                    left: self.len(),
                    right: mask.len(),
                });
            }
            return Self::new(self.dtype, Vec::new());
        }
        if mask.dtype != DType::Bool {
            return Err(ColumnError::InvalidMaskType { dtype: mask.dtype });
        }
        if self.len() != mask.len() {
            return Err(ColumnError::LengthMismatch {
                left: self.len(),
                right: mask.len(),
            });
        }

        // Typed fast path (br-frankenpandas-lei31 family): gather the contiguous
        // f64/i64 buffer by the mask directly, skipping the 32-byte Scalar clone
        // and the dtype-coercion scan in Column::new. Bit-identical — selects the
        // same positions in the same order, and an all-valid source yields an
        // all-valid result, exactly as the Scalar path + Column::new would.
        //
        // When the mask is an all-valid Bool column (the usual shape — it just
        // came out of a comparison), read its contiguous `bool` buffer instead of
        // `mask.values` (which would force the lazy-bool mask to materialize a
        // full Vec<Scalar::Bool>). `as_bool_slice` returns the raw bits, and for
        // an all-valid bool column `bits[i] == matches!(values[i],
        // Scalar::Bool(true))`, so selection is identical.
        if let Some(mask_bits) = mask.as_bool_slice() {
            if let Some(data) = self.as_f64_slice() {
                let gathered: Vec<f64> = data
                    .iter()
                    .zip(mask_bits)
                    .filter_map(|(&v, &m)| m.then_some(v))
                    .collect();
                return Ok(Self::from_f64_values_owned(gathered));
            }
            if let Some(data) = self.as_i64_slice() {
                let gathered: Vec<i64> = data
                    .iter()
                    .zip(mask_bits)
                    .filter_map(|(&v, &m)| m.then_some(v))
                    .collect();
                return Ok(Self::from_i64_values_owned(gathered));
            }
            // Nullable typed gathers (mirror take_positions' variant-gated nullable
            // path): a nullable Int64/Float64 column declined the all-valid
            // as_i64/f64_slice gathers above and would otherwise clone a 32-byte
            // Scalar per selected row + rescan in Self::new. Gate on the VALUES
            // VARIANT — NOT as_*_slice_with_validity, which also matches an Eager
            // ColumnData::Float64 whose Scalar values legally hold Null(NaT)/Null(Null)
            // — so only the canonical-missing lazy backings take this path. Gather the
            // raw datum by mask and carry the (NaN-folded) validity into the typed
            // nullable constructor. Bit-identical to the Scalar-clone + Self::new path
            // (present ⇒ same datum Scalar; missing ⇒ Null(NaN)/Null(Null) ==
            // missing_for_dtype; Column::eq compares materialized values).
            let typed_f64: Option<&[f64]> = match &self.values {
                ScalarValues::LazyNullableFloat64 { data, .. } => Some(data.as_slice()),
                ScalarValues::LazyAllValidFloat64 { data, .. } => Some(data.as_ref()),
                _ => None,
            };
            if let Some(src) = typed_f64 {
                let count = mask_bits.iter().filter(|&&m| m).count();
                let mut gathered = Vec::with_capacity(count);
                let mut words = vec![0_u64; count.div_ceil(64)];
                let mut out_idx = 0usize;
                for (i, &m) in mask_bits.iter().enumerate() {
                    if m {
                        let x = src[i];
                        gathered.push(x);
                        if self.validity.get(i) && !x.is_nan() {
                            words[out_idx / 64] |= 1_u64 << (out_idx % 64);
                        }
                        out_idx += 1;
                    }
                }
                return Ok(Self::from_f64_values_with_validity(
                    gathered,
                    ValidityMask::from_words(words, count),
                ));
            }
            if let ScalarValues::LazyNullableInt64 { data, .. } = &self.values {
                let src = data.as_slice();
                let count = mask_bits.iter().filter(|&&m| m).count();
                let mut gathered = Vec::with_capacity(count);
                let mut words = vec![0_u64; count.div_ceil(64)];
                let mut out_idx = 0usize;
                for (i, &m) in mask_bits.iter().enumerate() {
                    if m {
                        gathered.push(src[i]);
                        if self.validity.get(i) {
                            words[out_idx / 64] |= 1_u64 << (out_idx % 64);
                        }
                        out_idx += 1;
                    }
                }
                return Ok(Self::from_i64_values_with_validity(
                    gathered,
                    ValidityMask::from_words(words, count),
                ));
            }
            // Nullable temporal / Bool siblings (mirror the take_positions gathers):
            // Datetime64/Timedelta64 store i64 ns (missing ⇒ Null(NaT)), Bool raw
            // bits (missing ⇒ Null(Null)). Variant-gated to the canonical lazy
            // backing; byte-identical to the Scalar-clone path (present ⇒ datum
            // Scalar; missing ⇒ the variant's invalid emission == missing_for_dtype).
            if let ScalarValues::LazyNullableDatetime64 { data, .. } = &self.values {
                let src = data.as_slice();
                let count = mask_bits.iter().filter(|&&m| m).count();
                let mut gathered = Vec::with_capacity(count);
                let mut words = vec![0_u64; count.div_ceil(64)];
                let mut out_idx = 0usize;
                for (i, &m) in mask_bits.iter().enumerate() {
                    if m {
                        gathered.push(src[i]);
                        if self.validity.get(i) {
                            words[out_idx / 64] |= 1_u64 << (out_idx % 64);
                        }
                        out_idx += 1;
                    }
                }
                return Ok(Self::from_datetime64_values_with_validity(
                    gathered,
                    ValidityMask::from_words(words, count),
                ));
            }
            if let ScalarValues::LazyNullableTimedelta64 { data, .. } = &self.values {
                let src = data.as_slice();
                let count = mask_bits.iter().filter(|&&m| m).count();
                let mut gathered = Vec::with_capacity(count);
                let mut words = vec![0_u64; count.div_ceil(64)];
                let mut out_idx = 0usize;
                for (i, &m) in mask_bits.iter().enumerate() {
                    if m {
                        gathered.push(src[i]);
                        if self.validity.get(i) {
                            words[out_idx / 64] |= 1_u64 << (out_idx % 64);
                        }
                        out_idx += 1;
                    }
                }
                return Ok(Self::from_timedelta64_values_with_validity(
                    gathered,
                    ValidityMask::from_words(words, count),
                ));
            }
            if let ScalarValues::LazyNullableBool { data, .. } = &self.values {
                let src = data.as_slice();
                let count = mask_bits.iter().filter(|&&m| m).count();
                let mut gathered = Vec::with_capacity(count);
                let mut words = vec![0_u64; count.div_ceil(64)];
                let mut out_idx = 0usize;
                for (i, &m) in mask_bits.iter().enumerate() {
                    if m {
                        gathered.push(src[i]);
                        if self.validity.get(i) {
                            words[out_idx / 64] |= 1_u64 << (out_idx % 64);
                        }
                        out_idx += 1;
                    }
                }
                return Ok(Self::from_bool_values_with_validity(
                    gathered,
                    ValidityMask::from_words(words, count),
                ));
            }
            let values = self
                .values
                .iter()
                .zip(mask_bits)
                .filter_map(|(val, &m)| m.then_some(val.clone()))
                .collect::<Vec<_>>();
            return Self::new(self.dtype, values);
        }

        if let Some(data) = self.as_f64_slice() {
            let gathered: Vec<f64> = data
                .iter()
                .zip(mask.values.iter())
                .filter_map(|(&v, m)| matches!(m, Scalar::Bool(true)).then_some(v))
                .collect();
            return Ok(Self::from_f64_values_owned(gathered));
        }
        if let Some(data) = self.as_i64_slice() {
            let gathered: Vec<i64> = data
                .iter()
                .zip(mask.values.iter())
                .filter_map(|(&v, m)| matches!(m, Scalar::Bool(true)).then_some(v))
                .collect();
            return Ok(Self::from_i64_values_owned(gathered));
        }
        // Nullable Int64 gather (mirror of the Bool-self path above): the all-valid
        // `as_i64_slice` arm bails on ANY missing, so a nullable Int64 column fell to the
        // generic per-element `Vec<Scalar>` gather. Compact the raw buffer at the mask-true
        // positions AND gather the validity bit into the output — no Scalar materialization.
        // Bit-identical to the generic clone: a kept present slot keeps its datum, a kept
        // missing slot stays missing (Int64 has no NaN, so present = the validity bit alone).
        // A missing/non-Bool mask slot is never kept (== the generic `matches!(m, Bool(true))`).
        // (Nullable Float64 stays on the generic path: its three-way NaN rep — a validity-clear
        // slot whose datum materializes as a PRESENT Float64(NaN) — is not reproducible by a
        // simple validity-bit gather; see filter_by_mask_nullable_typed_gather_matches_reference_cf.)
        if self.dtype == DType::Int64
            && let Some((data, validity)) = self.as_i64_slice_with_validity()
        {
            let count = mask
                .values
                .iter()
                .filter(|m| matches!(m, Scalar::Bool(true)))
                .count();
            let mut gathered = Vec::with_capacity(count);
            let mut words = vec![0_u64; count.div_ceil(64)];
            let mut out_idx = 0usize;
            for (i, m) in mask.values.iter().enumerate() {
                if matches!(m, Scalar::Bool(true)) {
                    gathered.push(data[i]);
                    if validity.get(i) {
                        words[out_idx / 64] |= 1_u64 << (out_idx % 64);
                    }
                    out_idx += 1;
                }
            }
            return Ok(Self::from_i64_values_with_validity(
                gathered,
                ValidityMask::from_words(words, count),
            ));
        }

        let values = self
            .values
            .iter()
            .zip(mask.values.iter())
            .filter_map(|(val, mask_val)| match mask_val {
                Scalar::Bool(true) => Some(val.clone()),
                _ => None,
            })
            .collect::<Vec<_>>();

        Self::new(self.dtype, values)
    }

    /// Fill missing values with a replacement scalar.
    ///
    /// Returns a new column where every missing position is replaced
    /// by `fill_value`. The fill value is cast to the column's dtype.
    pub fn fillna(&self, fill_value: &Scalar) -> Result<Self, ColumnError> {
        if self.dtype == DType::Null {
            let replacement_dtype = if fill_value.is_missing() {
                DType::Null
            } else {
                fill_value.dtype()
            };
            let values = self
                .values
                .iter()
                .map(|value| {
                    if value.is_missing() {
                        fill_value.clone()
                    } else {
                        value.clone()
                    }
                })
                .collect();
            return Self::new(replacement_dtype, values);
        }

        // NOTE (br-frankenpandas-fp-stricter-than-pandas-rejections-gtkz1):
        // pandas PROMOTES to object here for a numpy-backed dtype rather than
        // raising — `pd.Series([10.0, None, 12.0]).fillna("oops")` is
        // `[10.0, 'oops', 12.0]` dtype object — and raises only for a nullable
        // extension dtype (`Invalid value 'oops' for dtype Int64`). So this
        // rejection IS stricter than pandas. It is deliberately left in place:
        // FrankenPandas represents [int, null, int] as numpy-backed Int64 while
        // pandas promotes it to float64 at CONSTRUCTION, so a fillna promotion
        // alone still yields Int64 where pandas has float64 and cannot be made
        // green. Blocked on br-frankenpandas-9ooer (oracle dtype chooser) and
        // the int64->float64-on-null construction divergence.
        let cast_fill = cast_scalar(fill_value, self.dtype)?;

        // Typed Float64 fast path (br-frankenpandas-e8vzt): fill every missing
        // slot with the finite f64 fill into an all-valid typed buffer, skipping
        // the per-element Scalar clone, the Vec<Scalar>, and the Self::new
        // revalidation. Bit-identical: a present slot (validity set AND datum not
        // NaN — a valid-bit NaN is missing per Scalar::is_missing) keeps its f64;
        // a missing slot takes `fv`; every result is finite, so the column is
        // all-valid exactly as Self::new would derive from the Float64 scalars.
        if self.dtype == DType::Float64
            && let Scalar::Float64(fv) = &cast_fill
            && fv.is_finite()
            && let Some((data, validity)) = self.as_f64_slice_with_validity()
        {
            // Nothing-to-fill short-circuit: every slot present (validity set) AND
            // no NaN datum (a valid-bit NaN counts as missing per Scalar::is_missing)
            // ⇒ output == input, so share the backing in O(1) instead of rebuilding
            // a fresh n*8 buffer. Bit-identical (clone preserves values + dtype +
            // validity), and returns self's own representation rather than minting a
            // new variant. The NaN scan is a cheap sequential read vs the alloc+copy.
            if validity.all() && !data.iter().any(|d| d.is_nan()) {
                return Ok(self.clone());
            }
            // Iterate the PACKED validity words instead of `validity.get(i)` per
            // element (a ~4-branch, non-inlined call ×n): an all-invalid word fills
            // 64 slots with `fv` outright; an all-valid word copies its 64 data
            // slots (still NaN-checked — a valid-bit NaN counts as missing per
            // Scalar::is_missing, so it takes `fv`); a partial word tests only its
            // bits. Bit-identical to the `validity.get(i) && !d.is_nan()` select.
            let n = data.len();
            let words = validity.packed_words_for_scan();
            let mut out = Vec::with_capacity(n);
            for (w, &word) in words.iter().enumerate() {
                let base = w * 64;
                let upto = 64.min(n - base);
                if word == 0 {
                    out.extend(std::iter::repeat_n(*fv, upto));
                } else {
                    for b in 0..upto {
                        let d = data[base + b];
                        if (word >> b) & 1 == 1 && !d.is_nan() {
                            out.push(d);
                        } else {
                            out.push(*fv);
                        }
                    }
                }
            }
            // Output is all-valid and NaN-free (present non-NaN values or the
            // finite fill) → MOVE into the backing (no Arc::from realloc).
            return Ok(Self::from_f64_values_owned(out));
        }

        // Typed nullable Int64 fast path: fill each missing slot (validity bit
        // alone — no NaN sentinel for Int64) with the i64 fill into an all-valid
        // i64 buffer, skipping the per-element Scalar clone + Self::new revalidation.
        // Bit-identical to the loop below: present → data[i], missing → fv, output
        // all-valid Int64. Gated on a real Int64 fill (a missing fill keeps nulls,
        // so it falls through to the generic path).
        if self.dtype == DType::Int64
            && let Scalar::Int64(fv) = &cast_fill
            && let Some((data, validity)) = self.as_i64_slice_with_validity()
        {
            // Nothing-to-fill short-circuit: all slots present (Int64 missing is
            // validity-bit only, no NaN sentinel) ⇒ output == input, O(1) share.
            if validity.all() {
                return Ok(self.clone());
            }
            let mut out = Vec::with_capacity(data.len());
            for (i, &d) in data.iter().enumerate() {
                out.push(if validity.get(i) { d } else { *fv });
            }
            return Ok(Self::from_i64_values_owned(out));
        }

        // Typed Int64 fast path (br-frankenpandas-3llep): as_i64_slice returns
        // Some only for an all-valid Int64 backing, which has nothing to fill — so
        // fillna is a copy of the existing values. Re-ingest the contiguous i64
        // buffer typed, skipping the per-element Scalar clone + Self::new
        // revalidation the loop below would run on every all-valid Int64 column.
        // Bit-identical: every value is present (cast_fill is never applied) and
        // the output is the same all-valid Int64 column. cast_scalar above has
        // already validated/errored on the fill value.
        if self.dtype == DType::Int64 && self.as_i64_slice().is_some() {
            // `as_i64_slice` is Some only for an all-valid Int64 backing → nothing
            // to fill, output == input. Share in O(1) instead of `to_vec`-copying
            // the whole buffer.
            return Ok(self.clone());
        }

        // Typed nullable Bool fast path: `LazyNullableBool` materializes valid
        // slots as the raw bool and invalid slots as `Null(Null)`. A post-cast
        // Bool fill therefore makes every output slot valid, so select directly
        // from the packed Bool data + validity and skip the Vec<Scalar> rebuild.
        // Variant-gating preserves the generic path for eager Bool columns that
        // may carry distinct NullKind values; a missing fill also remains generic
        // because its post-cast scalar does not match `Scalar::Bool`.
        if let Scalar::Bool(fv) = &cast_fill
            && let ScalarValues::LazyNullableBool { data, validity, .. } = &self.values
        {
            let out = data
                .iter()
                .enumerate()
                .map(|(i, &value)| if validity.get(i) { value } else { *fv })
                .collect();
            return Ok(Self::from_bool_values(out));
        }

        // Typed nullable Utf8 fast path: a `LazyNullableUtf8` column (a string column
        // WITH missing rows — the common `df[col].fillna("x")` shape) with a Utf8 fill.
        // The generic loop below materializes a `Vec<Scalar::Utf8>` and clones a heap
        // `String` per PRESENT row plus the fill per MISSING row. Build the filled output
        // as ONE contiguous byte buffer from the raw spans (present) / fill bytes
        // (missing) — no per-row `String` alloc. Every output slot is filled, so the
        // result is all-valid contiguous Utf8. Bit-identical to the loop: present ⇒
        // `Scalar::Utf8(span)`, missing ⇒ `Scalar::Utf8(fill)`. No cold-cache gate — the
        // contiguous build beats the per-row `String` clones even on a warm column (like
        // take_positions / sort_values), not just materialization avoidance. A missing
        // fill keeps nulls, so its post-cast scalar is not `Scalar::Utf8` and it falls to
        // the generic path.
        if let Scalar::Utf8(fill) = &cast_fill
            && let ScalarValues::LazyNullableUtf8 {
                bytes,
                offsets,
                validity,
                ..
            } = &self.values
        {
            let fill_bytes = fill.as_bytes();
            let n = offsets.len().saturating_sub(1);
            let mut out_bytes: Vec<u8> = Vec::with_capacity(bytes.len() + fill_bytes.len() * n);
            let mut out_offsets: Vec<usize> = Vec::with_capacity(n + 1);
            out_offsets.push(0);
            for (i, w) in offsets.windows(2).enumerate() {
                if validity.get(i) {
                    out_bytes.extend_from_slice(&bytes[w[0]..w[1]]);
                } else {
                    out_bytes.extend_from_slice(fill_bytes);
                }
                out_offsets.push(out_bytes.len());
            }
            return Ok(Self::from_utf8_contiguous(out_bytes, out_offsets));
        }

        // Typed nullable temporal fillna: a `LazyNullableDatetime64` / `LazyNullableTimedelta64`
        // column (the common `df["date"].fillna(default)` shape — a temporal column WITH missing
        // rows) and a matching NON-NaT temporal fill. The generic loop below materializes a
        // `Vec<Scalar::Datetime64/Timedelta64>` (32 B/row) just to clone present values + the fill
        // for missing. Build the filled i64-ns buffer directly: a present slot (validity set AND
        // not the NaT sentinel — exactly the materialized `!is_missing`) keeps `data[i]`, a missing
        // slot takes the fill ns. Every slot is filled ⇒ all-valid output. Bit-identical to the
        // loop: present ⇒ the same value, missing ⇒ the fill, dtype unchanged. A NaT fill keeps
        // nulls (its post-cast scalar IS missing) so it falls to the generic path.
        if let (
            Scalar::Datetime64(fill),
            ScalarValues::LazyNullableDatetime64 { data, validity, .. },
        ) = (&cast_fill, &self.values)
            && *fill != Timestamp::NAT
        {
            let out: Vec<i64> = data
                .iter()
                .enumerate()
                .map(|(i, &v)| {
                    if validity.get(i) && v != Timestamp::NAT {
                        v
                    } else {
                        *fill
                    }
                })
                .collect();
            return Ok(Self::from_datetime64_values(out));
        }
        if let (
            Scalar::Timedelta64(fill),
            ScalarValues::LazyNullableTimedelta64 { data, validity, .. },
        ) = (&cast_fill, &self.values)
            && *fill != Timedelta::NAT
        {
            let n = data.len();
            let out: Vec<i64> = data
                .iter()
                .enumerate()
                .map(|(i, &v)| {
                    if validity.get(i) && v != Timedelta::NAT {
                        v
                    } else {
                        *fill
                    }
                })
                .collect();
            return Ok(Self::from_timedelta64_values_with_validity(
                out,
                ValidityMask::all_valid(n),
            ));
        }

        let values = self
            .values
            .iter()
            .map(|v| {
                if v.is_missing() {
                    cast_fill.clone()
                } else {
                    v.clone()
                }
            })
            .collect();

        Self::new(self.dtype, values)
    }

    /// Remove missing values, returning a shorter column.
    pub fn dropna(&self) -> Result<Self, ColumnError> {
        // Typed fast paths: compact the present values from the raw buffer +
        // validity, no per-element Scalar materialization. Bit-identical to the
        // Scalar filter: a present slot keeps its value in order; a Float64 valid
        // slot whose datum is NaN is dropped (Scalar::Float64(NaN).is_missing()),
        // and Int64/Bool missingness is the validity bit alone. Output is
        // all-valid. Bool is deliberately variant-gated: Scalar-backed Bool
        // columns may preserve mixed NullKind values and retain the generic path.
        if self.dtype == DType::Float64
            && let Some((data, validity)) = self.as_f64_slice_with_validity()
        {
            let mut out = Vec::with_capacity(data.len());
            for (i, &d) in data.iter().enumerate() {
                if validity.get(i) && !d.is_nan() {
                    out.push(d);
                }
            }
            return Ok(Self::from_f64_values_owned(out));
        }
        if self.dtype == DType::Int64
            && let Some((data, validity)) = self.as_i64_slice_with_validity()
        {
            let mut out = Vec::with_capacity(data.len());
            for (i, &d) in data.iter().enumerate() {
                if validity.get(i) {
                    out.push(d);
                }
            }
            return Ok(Self::from_i64_values_owned(out));
        }
        if self.dtype == DType::Bool
            && let ScalarValues::LazyNullableBool { data, validity, .. } = &self.values
        {
            let mut out = Vec::with_capacity(data.len());
            for (i, &d) in data.iter().enumerate() {
                if validity.get(i) {
                    out.push(d);
                }
            }
            return Ok(Self::from_bool_values(out));
        }
        let values = self
            .values
            .iter()
            .filter(|v| !v.is_missing())
            .cloned()
            .collect();

        Self::new(self.dtype, values)
    }

    /// Gather rows by integer position.
    ///
    /// Matches `pd.Series.take(indices)`. Each index must fall within
    /// `0..len()`; out-of-range positions return
    /// `ColumnError::LengthMismatch` (left=length, right=offending
    /// index).
    pub fn take(&self, indices: &[usize]) -> Result<Self, ColumnError> {
        let mut out = Vec::with_capacity(indices.len());
        for &i in indices {
            match self.values.get(i) {
                Some(v) => out.push(v.clone()),
                None => {
                    return Err(ColumnError::LengthMismatch {
                        left: self.values.len(),
                        right: i,
                    });
                }
            }
        }
        Self::new(self.dtype, out)
    }

    /// Replace elements at specified indices with given values.
    ///
    /// Matches np.put(). Returns a new column with values replaced at indices.
    pub fn put(&self, indices: &[usize], values: &[Scalar]) -> Result<Self, ColumnError> {
        if indices.len() != values.len() {
            return Err(ColumnError::LengthMismatch {
                left: indices.len(),
                right: values.len(),
            });
        }
        let mut out = self.values.to_vec();
        for (&i, v) in indices.iter().zip(values) {
            if i >= out.len() {
                return Err(ColumnError::LengthMismatch {
                    left: out.len(),
                    right: i,
                });
            }
            out[i] = v.clone();
        }
        Self::new(self.dtype, out)
    }

    /// Contiguous slice by positional range `start..start+len`.
    ///
    /// Out-of-range requests are clamped to the available tail so a
    /// start past `len()` yields an empty column with the same dtype,
    /// matching pandas' permissive slice semantics.
    pub fn slice(&self, start: usize, len: usize) -> Result<Self, ColumnError> {
        if start >= self.values.len() {
            return Self::new(self.dtype, Vec::new());
        }
        let end = start.saturating_add(len).min(self.values.len());
        Ok(self.take_contiguous_range(start, end - start))
    }

    /// Return the first `n` values.
    ///
    /// Matches pandas `head(n)` semantics on a 1-D array-like surface.
    /// Negative `n` returns all values except the last `-n`.
    pub fn head(&self, n: i64) -> Result<Self, ColumnError> {
        let take = normalize_head_take(n, self.len());
        self.slice(0, take)
    }

    /// Return the last `n` values.
    ///
    /// Matches pandas `tail(n)` semantics on a 1-D array-like surface.
    /// Negative `n` returns all values except the first `-n`.
    pub fn tail(&self, n: i64) -> Result<Self, ColumnError> {
        let (start, len) = normalize_tail_window(n, self.len());
        self.slice(start, len)
    }

    /// Split column into n equal-ish parts.
    ///
    /// Matches np.array_split(). Returns Vec of Columns.
    pub fn array_split(&self, n: usize) -> Result<Vec<Self>, ColumnError> {
        if n == 0 {
            return Ok(Vec::new());
        }
        let len = self.values.len();
        let base_size = len / n;
        let remainder = len % n;
        let mut result = Vec::with_capacity(n);
        let mut start = 0;
        for i in 0..n {
            let size = base_size + if i < remainder { 1 } else { 0 };
            let part = self.slice(start, size)?;
            result.push(part);
            start += size;
        }
        Ok(result)
    }

    /// Alias for array_split.
    pub fn split(&self, n: usize) -> Result<Vec<Self>, ColumnError> {
        self.array_split(n)
    }

    /// Concatenate `other` onto `self`, preserving dtype.
    ///
    /// Returns `ColumnError::DTypeMismatch` when `other.dtype()` differs
    /// from `self.dtype()`.
    pub fn concat(&self, other: &Self) -> Result<Self, ColumnError> {
        if self.dtype != other.dtype {
            return Err(ColumnError::DTypeMismatch {
                left: self.dtype,
                right: other.dtype,
            });
        }
        // perf: typed buffer concat for the ubiquitous all-valid Int64/Float64
        // case — extend the contiguous i64/f64 buffers directly instead of cloning
        // a 32 B Scalar per row through `self.values` + re-validating in `Self::new`.
        // as_i64_slice/as_f64_slice are Some only when BOTH columns are all-valid of
        // that dtype, so from_i64_values/from_f64_values are bit-identical to the
        // Scalar path (same dtype + no missing => same logical values).
        if let (Some((a, a_start)), Some((b, b_start))) = (
            self.as_i64_arc_view_source(),
            other.as_i64_arc_view_source(),
        ) {
            return Ok(Self::from_i64_all_valid_chunks(
                vec![(a, a_start, self.len()), (b, b_start, other.len())],
                self.len() + other.len(),
            ));
        }
        if let (Some(a), Some(b)) = (self.as_f64_slice(), other.as_f64_slice()) {
            let mut out = Vec::with_capacity(a.len() + b.len());
            out.extend_from_slice(a);
            out.extend_from_slice(b);
            return Ok(Self::from_f64_values(out));
        }
        let mut values = Vec::with_capacity(self.values.len() + other.values.len());
        values.extend_from_slice(&self.values);
        values.extend_from_slice(&other.values);
        Self::new(self.dtype, values)
    }

    /// Alias for concat, matching np.append.
    pub fn append(&self, other: &Self) -> Result<Self, ColumnError> {
        self.concat(other)
    }

    /// Insert values at given index.
    ///
    /// Matches np.insert(). Returns new column with values inserted.
    pub fn insert(&self, index: usize, values: &[Scalar]) -> Result<Self, ColumnError> {
        let idx = index.min(self.values.len());
        let mut out = Vec::with_capacity(self.values.len() + values.len());
        out.extend_from_slice(&self.values[..idx]);
        out.extend_from_slice(values);
        out.extend_from_slice(&self.values[idx..]);
        Self::new(self.dtype, out)
    }

    /// Delete values at given indices.
    ///
    /// Matches np.delete(). Returns new column with values removed.
    pub fn delete(&self, indices: &[usize]) -> Result<Self, ColumnError> {
        let mut to_delete: FxHashSet<usize> = FxHashSet::default();
        for &i in indices {
            to_delete.insert(i);
        }
        let out: Vec<Scalar> = self
            .values
            .iter()
            .enumerate()
            .filter(|(i, _)| !to_delete.contains(i))
            .map(|(_, v)| v.clone())
            .collect();
        Self::new(self.dtype, out)
    }

    /// Resize column to new size, padding or truncating as needed.
    ///
    /// Matches np.resize(). If new size is larger, values cycle from beginning.
    pub fn resize(&self, new_size: usize) -> Result<Self, ColumnError> {
        if new_size == 0 || self.values.is_empty() {
            return Self::new(self.dtype, Vec::new());
        }
        let mut out = Vec::with_capacity(new_size);
        let mut i = 0;
        while out.len() < new_size {
            out.push(self.values[i % self.values.len()].clone());
            i += 1;
        }
        Self::new(self.dtype, out)
    }

    /// Repeat each value `repeats` times contiguously.
    ///
    /// Matches `pd.Series.repeat(n)`. `repeats=0` yields an empty
    /// column; `repeats=1` is a clone.
    pub fn repeat(&self, repeats: usize) -> Result<Self, ColumnError> {
        if repeats == 0 {
            return Self::new(self.dtype, Vec::new());
        }
        if repeats == 1 {
            return Ok(self.clone());
        }
        let mut out = Vec::with_capacity(self.values.len() * repeats);
        for v in &self.values {
            for _ in 0..repeats {
                out.push(v.clone());
            }
        }
        Self::new(self.dtype, out)
    }

    /// Tile (repeat) the entire column n times.
    ///
    /// Matches `np.tile()`. Unlike repeat which duplicates each element,
    /// tile duplicates the entire array.
    pub fn tile(&self, reps: usize) -> Result<Self, ColumnError> {
        if reps == 0 {
            return Self::new(self.dtype, Vec::new());
        }
        if reps == 1 {
            return Ok(self.clone());
        }
        let mut out = Vec::with_capacity(self.values.len() * reps);
        for _ in 0..reps {
            out.extend_from_slice(&self.values);
        }
        Self::new(self.dtype, out)
    }

    /// Reverse the row order of the column.
    ///
    /// Matches `pd.Series[::-1]` / `iloc[::-1]`. Dtype is preserved.
    pub fn reverse(&self) -> Result<Self, ColumnError> {
        let mut values = self.values.to_vec();
        values.reverse();
        Self::new(self.dtype, values)
    }

    /// Alias for reverse, matching np.flip.
    pub fn flip(&self) -> Result<Self, ColumnError> {
        self.reverse()
    }

    /// Roll array elements along the axis.
    ///
    /// Matches np.roll(a, shift). Elements that roll beyond the last position
    /// are re-introduced at the first, and vice versa. Positive shift rolls
    /// elements to higher indices (right), negative to lower (left).
    pub fn roll(&self, shift: i64) -> Result<Self, ColumnError> {
        let len = self.len();
        if len == 0 {
            return Ok(self.clone());
        }
        let shift = ((shift % len as i64) + len as i64) as usize % len;
        if shift == 0 {
            return Ok(self.clone());
        }
        let mut out = Vec::with_capacity(len);
        let split = len - shift;
        out.extend_from_slice(&self.values[split..]);
        out.extend_from_slice(&self.values[..split]);
        Self::new(self.dtype, out)
    }

    /// Filter values based on a boolean condition column.
    ///
    /// Matches `np.compress()`. Returns only values where condition is True.
    pub fn compress(&self, condition: &Self) -> Result<Self, ColumnError> {
        if self.len() != condition.len() {
            return Err(ColumnError::LengthMismatch {
                left: self.len(),
                right: condition.len(),
            });
        }
        let mut out = Vec::new();
        for (v, c) in self.values.iter().zip(&condition.values) {
            match c {
                Scalar::Bool(true) => out.push(v.clone()),
                Scalar::Bool(false) => {}
                _ => {
                    return Err(ColumnError::Type(TypeError::NonNumericValue {
                        value: format!("{c:?}"),
                        dtype: condition.dtype,
                    }));
                }
            }
        }
        Self::new(self.dtype, out)
    }

    /// Cumulative sum, null-propagating per fp-types::nancumsum.
    ///
    /// Matches `pd.Series.cumsum()`. The resulting column is always
    /// Float64 (matching the numeric accumulator type used in
    /// nancumsum).
    pub fn cumsum(&self) -> Result<Self, ColumnError> {
        // Typed prefix scan: an all-valid Float64 column scans its contiguous
        // buffer, no Scalar materialization in or out. Bit-identical to
        // nancumsum's Float64 arm — the same `running += x` left-fold seeded at
        // 0.0 in the same order; an operation-produced NaN (inf - inf) is flagged
        // missing by from_f64_values, exactly as Self::new(Float64, ...) does.
        if let Some(data) = self.as_f64_slice() {
            let mut running = 0.0_f64;
            let out: Vec<f64> = data
                .iter()
                .map(|&x| {
                    running += x;
                    running
                })
                .collect();
            return Ok(Self::from_f64_values_owned(out));
        }
        // Typed all-valid Int64: fold as f64 (matching nancumsum's `to_f64`),
        // emit Float64 — bit-identical to the nancumsum path, no Scalar
        // materialization of the lazy i64 column.
        if let Some(data) = self.as_i64_slice() {
            let mut running = 0.0_f64;
            let out: Vec<f64> = data
                .iter()
                .map(|&x| {
                    running += x as f64;
                    running
                })
                .collect();
            return Ok(Self::from_f64_values_owned(out));
        }
        // Nullable Int64/Float64: the all-valid arms above bailed on the missing
        // bit, so these fell to nancumsum over the materialized Vec<Scalar>. Fold
        // the raw slice + validity typed (running seeded 0.0, present ⇒ += x, emit;
        // missing/NaN ⇒ Null(NaN), running unchanged). Bit-identical to nancumsum.
        if self.dtype == DType::Float64
            && let Some((data, validity)) = self.as_f64_slice_with_validity()
        {
            let (out, out_valid) = cum_accum_nullable_f64(data, validity, 0.0, false);
            return Ok(Self::from_f64_values_with_validity(out, out_valid));
        }
        if self.dtype == DType::Int64
            && let Some((data, validity)) = self.as_i64_slice_with_validity()
        {
            let (out, out_valid) = cum_accum_nullable_i64(data, validity, 0.0, false);
            return Ok(Self::from_f64_values_with_validity(out, out_valid));
        }
        let out = nancumsum(&self.values);
        Self::new(DType::Float64, out)
    }

    /// Cumulative product, null-propagating per fp-types::nancumprod.
    pub fn cumprod(&self) -> Result<Self, ColumnError> {
        // Typed prefix scan (see cumsum): nancumprod seeds `running` at 1.0.
        if let Some(data) = self.as_f64_slice() {
            let mut running = 1.0_f64;
            let out: Vec<f64> = data
                .iter()
                .map(|&x| {
                    running *= x;
                    running
                })
                .collect();
            return Ok(Self::from_f64_values_owned(out));
        }
        // NB: no typed i64 fast path — an i64 product can overflow the f64 to
        // ±inf→NaN, where from_f64_values (NaN→missing) diverges from nancumprod's
        // Scalar::Float64(NaN); kept on the exact nancumprod path for bit-identity.
        // Nullable Int64/Float64 (seed 1.0, product): typed fold, skipping the
        // Scalar materialization. Bit-identical to nancumprod.
        if self.dtype == DType::Float64
            && let Some((data, validity)) = self.as_f64_slice_with_validity()
        {
            let (out, out_valid) = cum_accum_nullable_f64(data, validity, 1.0, true);
            return Ok(Self::from_f64_values_with_validity(out, out_valid));
        }
        if self.dtype == DType::Int64
            && let Some((data, validity)) = self.as_i64_slice_with_validity()
        {
            let (out, out_valid) = cum_accum_nullable_i64(data, validity, 1.0, true);
            return Ok(Self::from_f64_values_with_validity(out, out_valid));
        }
        let out = nancumprod(&self.values);
        Self::new(DType::Float64, out)
    }

    /// Cumulative maximum, null-propagating per fp-types::nancummax.
    pub fn cummax(&self) -> Result<Self, ColumnError> {
        // Typed running maximum: nancummax takes the first non-missing value
        // then `prev.max(x)` (std f64::max semantics) — reproduced over the
        // contiguous buffer for an all-valid Float64 column.
        if let Some(data) = self.as_f64_slice() {
            if let Some((&first, rest)) = data.split_first() {
                let mut running = first;
                let mut out = Vec::with_capacity(data.len());
                out.push(running);
                for &x in rest {
                    running = running.max(x);
                    out.push(running);
                }
                return Ok(Self::from_f64_values_owned(out));
            }
            return Ok(Self::from_f64_values(Vec::new()));
        }
        if let Some(data) = self.as_i64_slice() {
            if let Some((&first, rest)) = data.split_first() {
                let mut running = first as f64;
                let mut out = Vec::with_capacity(data.len());
                out.push(running);
                for &x in rest {
                    running = running.max(x as f64);
                    out.push(running);
                }
                return Ok(Self::from_f64_values_owned(out));
            }
            return Ok(Self::from_f64_values(Vec::new()));
        }
        // Nullable Int64/Float64: the all-valid arms above bailed on the missing
        // bit, so these fell to nancummax over the materialized Vec<Scalar>. Fold
        // the raw slice + validity typed (present ⇒ running max, missing/NaN ⇒
        // Null(NaN)), skipping the input Scalar materialization AND the Scalar
        // output. Bit-identical to nancummax.
        if self.dtype == DType::Float64
            && let Some((data, validity)) = self.as_f64_slice_with_validity()
        {
            let (out, out_valid) = cum_extrema_nullable_f64(data, validity, true);
            return Ok(Self::from_f64_values_with_validity(out, out_valid));
        }
        if self.dtype == DType::Int64
            && let Some((data, validity)) = self.as_i64_slice_with_validity()
        {
            let (out, out_valid) = cum_extrema_nullable_i64(data, validity, true);
            return Ok(Self::from_f64_values_with_validity(out, out_valid));
        }
        let out = nancummax(&self.values);
        Self::new(DType::Float64, out)
    }

    /// Cumulative minimum, null-propagating per fp-types::nancummin.
    pub fn cummin(&self) -> Result<Self, ColumnError> {
        // Typed running minimum (see cummax).
        if let Some(data) = self.as_f64_slice() {
            if let Some((&first, rest)) = data.split_first() {
                let mut running = first;
                let mut out = Vec::with_capacity(data.len());
                out.push(running);
                for &x in rest {
                    running = running.min(x);
                    out.push(running);
                }
                return Ok(Self::from_f64_values_owned(out));
            }
            return Ok(Self::from_f64_values(Vec::new()));
        }
        if let Some(data) = self.as_i64_slice() {
            if let Some((&first, rest)) = data.split_first() {
                let mut running = first as f64;
                let mut out = Vec::with_capacity(data.len());
                out.push(running);
                for &x in rest {
                    running = running.min(x as f64);
                    out.push(running);
                }
                return Ok(Self::from_f64_values_owned(out));
            }
            return Ok(Self::from_f64_values(Vec::new()));
        }
        // Nullable Int64/Float64 (symmetric to cummax): typed running min over the
        // raw slice + validity, skipping the Scalar materialization.
        if self.dtype == DType::Float64
            && let Some((data, validity)) = self.as_f64_slice_with_validity()
        {
            let (out, out_valid) = cum_extrema_nullable_f64(data, validity, false);
            return Ok(Self::from_f64_values_with_validity(out, out_valid));
        }
        if self.dtype == DType::Int64
            && let Some((data, validity)) = self.as_i64_slice_with_validity()
        {
            let (out, out_valid) = cum_extrema_nullable_i64(data, validity, false);
            return Ok(Self::from_f64_values_with_validity(out, out_valid));
        }
        let out = nancummin(&self.values);
        Self::new(DType::Float64, out)
    }

    /// Sum of non-missing values.
    ///
    /// Sum an all-valid Float64 `concat(...)` output (`LazyAllValidFloat64Chunks`)
    /// by folding each chunk slice in place with ONE 0.0-seeded accumulator in
    /// 0..n order — BIT-IDENTICAL to `as_f64_slice().iter().sum()` over the
    /// materialized buffer (same values, same order, same sequential left-fold)
    /// — but WITHOUT allocating+filling the cold concatenated `Vec<f64>` (the
    /// [[f64-arc-copy-on-produce]] ~5.7 ms/1M page-fault cost). `None` for any
    /// non-chunked / nullable / non-Float64 column (caller keeps its normal path).
    #[must_use]
    pub fn all_valid_f64_chunk_sum(&self) -> Option<f64> {
        if self.dtype != DType::Float64 || !self.validity.all() {
            return None;
        }
        let chunks = self.values.float64_chunks_ref()?;
        // Per-chunk BLOCKED sum (br-frankenpandas-8s4mb technique). The old inner
        // `s += x` was a serial dependency chain LLVM cannot vectorize because f64
        // addition is non-associative; `blocked_sum_f64` breaks it into 8 lanes and
        // is already the summation used by the nullable reductions.
        //
        // NUMERICS: a chunk shorter than 8 flows entirely through that helper's
        // remainder fold, so it stays bit-identical there; longer chunks re-associate
        // WITHIN the chunk only. Chunk-to-chunk order is unchanged.
        let mut s = 0.0_f64;
        for chunk in chunks {
            s += blocked_sum_f64(chunk.as_slice());
        }
        Some(s)
    }

    /// Mean of an all-valid Float64 chunks column (see `all_valid_f64_chunk_sum`):
    /// `Σ / len` with the in-place chunk fold; `None` for empty or non-chunked.
    #[must_use]
    pub fn all_valid_f64_chunk_mean(&self) -> Option<f64> {
        if self.dtype != DType::Float64 || !self.validity.all() {
            return None;
        }
        let chunks = self.values.float64_chunks_ref()?;
        let mut s = 0.0_f64;
        let mut count = 0usize;
        for chunk in chunks {
            let slice = chunk.as_slice();
            // Same blocked sum as `all_valid_f64_chunk_sum`; see the note there.
            s += blocked_sum_f64(slice);
            count += slice.len();
        }
        if count == 0 {
            return None;
        }
        Some(s / count as f64)
    }

    /// Sum an all-valid Int64 `concat(...)` output by folding each chunk slice
    /// in place with `wrapping_add` (0-seeded, 0..n order) — BIT-IDENTICAL to the
    /// materialized `as_i64_slice` wrapping sum (wrapping_add is associative mod
    /// 2^64, so chunk grouping can't change the result) — without the cold Vec.
    #[must_use]
    pub fn all_valid_i64_chunk_sum(&self) -> Option<i64> {
        if self.dtype != DType::Int64 || !self.validity.all() {
            return None;
        }
        let chunks = self.values.int64_chunks_ref()?;
        let mut total: i64 = 0;
        for chunk in chunks {
            for &x in chunk.as_slice() {
                total = total.wrapping_add(x);
            }
        }
        Some(total)
    }

    /// Min/max of an all-valid Int64 concat output via in-place chunk fold
    /// (order-independent — `i64::min`/`max` is associative+commutative — so
    /// bit-identical to the materialized reduction). `None` if empty/non-chunked.
    #[must_use]
    pub fn all_valid_i64_chunk_extreme(&self, want_max: bool) -> Option<i64> {
        if self.dtype != DType::Int64 || !self.validity.all() {
            return None;
        }
        let chunks = self.values.int64_chunks_ref()?;
        // Blocked per chunk; integer min/max is associative so this is EXACTLY
        // bit-identical to the element-at-a-time fold, at every length.
        let mut best: Option<i64> = None;
        for chunk in chunks {
            let Some((lo, hi)) = blocked_min_max_i64(chunk.as_slice()) else {
                continue;
            };
            let candidate = if want_max { hi } else { lo };
            best = Some(match best {
                None => candidate,
                Some(b) => {
                    if want_max {
                        b.max(candidate)
                    } else {
                        b.min(candidate)
                    }
                }
            });
        }
        best
    }

    /// Min/max of an all-valid Float64 concat output via in-place chunk fold,
    /// replicating `Series::max`/`min`'s EXACT reduction — `if v > result`
    /// (seed −∞) / `if v < result` (seed +∞), NOT `f64::max`/`min` (which would
    /// flip ±0.0) — in 0..n order, so the ±0.0-first-seen tie is preserved
    /// bit-for-bit. Chunks are all-valid (no NaN), so no missing/NaN branch.
    /// `None` when empty/non-chunked (caller keeps its normal empty handling).
    #[must_use]
    pub fn all_valid_f64_chunk_extreme(&self, want_max: bool) -> Option<f64> {
        if self.dtype != DType::Float64 || !self.validity.all() {
            return None;
        }
        let chunks = self.values.float64_chunks_ref()?;
        let mut result = if want_max {
            f64::NEG_INFINITY
        } else {
            f64::INFINITY
        };
        let mut any = false;
        for chunk in chunks {
            let slice = chunk.as_slice();
            if slice.is_empty() {
                continue;
            }
            any = true;
            // Blocked 8-lane min/max per chunk (br-frankenpandas-8s4mb technique),
            // reusing the helper the nullable `ptp` path uses.
            //
            // ⚠️ THE ALL-NaN QUIRK OF THIS FUNCTION IS PRESERVED DELIBERATELY, not
            // fixed: `any` is set per non-empty CHUNK exactly as it was set per
            // ELEMENT, so an all-NaN input still returns `Some(+inf)` for min and
            // `Some(-inf)` for max rather than `None`. `blocked_min_max_f64` leaves
            // its sentinels untouched for such a chunk, and comparing those
            // sentinels against `result` is a no-op — the same no-op the old
            // per-element `if v > result` performed for every NaN.
            let (lo, hi) = blocked_min_max_f64(slice);
            if want_max {
                if hi > result {
                    result = hi;
                }
            } else if lo < result {
                result = lo;
            }
        }
        if any { Some(result) } else { None }
    }

    /// Σ(v−mean)² over an all-valid Float64 concat output, folding each chunk
    /// slice in place in 0..n order — bit-identical to the materialized
    /// `Σ(v−mean)²` second pass in `Series::var` (same values, order, 0.0 seed),
    /// without the cold materialization. Completes the concat→reduce vein (var/std).
    #[must_use]
    pub fn all_valid_f64_chunk_sq_dev_sum(&self, mean: f64) -> Option<f64> {
        if self.dtype != DType::Float64 || !self.validity.all() {
            return None;
        }
        let chunks = self.values.float64_chunks_ref()?;
        // `blocked_sum_sq_f64` is the same Sigma (x - mean)^2 the nullable sem/var
        // path uses, so the two agree by construction rather than by coincidence.
        let mut s = 0.0_f64;
        for chunk in chunks {
            s += blocked_sum_sq_f64(chunk.as_slice(), mean);
        }
        Some(s)
    }

    /// Int64 sibling of `all_valid_f64_chunk_sq_dev_sum` (`(v as f64 − mean)²`).
    #[must_use]
    pub fn all_valid_i64_chunk_sq_dev_sum(&self, mean: f64) -> Option<f64> {
        if self.dtype != DType::Int64 || !self.validity.all() {
            return None;
        }
        let chunks = self.values.int64_chunks_ref()?;
        // Int64 sibling of the blocked f64 path above; `blocked_sum_sq_i64` widens
        // with `as f64` in exactly the same place the scalar fold did.
        let mut s = 0.0_f64;
        for chunk in chunks {
            s += blocked_sum_sq_i64(chunk.as_slice(), mean);
        }
        Some(s)
    }

    /// Product of an all-valid Float64 concat output, folding each chunk slice
    /// in place with a 1.0-seeded `*` in 0..n order — bit-identical to
    /// `as_f64_slice().iter().product()` (also a 1.0-seeded sequential left-fold)
    /// — without materializing the cold concat buffer.
    #[must_use]
    pub fn all_valid_f64_chunk_product(&self) -> Option<f64> {
        if self.dtype != DType::Float64 || !self.validity.all() {
            return None;
        }
        let chunks = self.values.float64_chunks_ref()?;
        let mut p = 1.0_f64;
        for chunk in chunks {
            for &v in chunk.as_slice() {
                p *= v;
            }
        }
        Some(p)
    }

    /// Int64 product sibling (`wrapping_mul`, associative mod 2^64 ⇒ grouping-
    /// invariant, bit-identical to the materialized `fold(1, wrapping_mul)`).
    #[must_use]
    pub fn all_valid_i64_chunk_product(&self) -> Option<i64> {
        if self.dtype != DType::Int64 || !self.validity.all() {
            return None;
        }
        let chunks = self.values.int64_chunks_ref()?;
        // Blocked per chunk; exact for the same reason the doc above gives for
        // chunk grouping — wrapping_mul is associative mod 2^64.
        let mut p = 1_i64;
        for chunk in chunks {
            p = p.wrapping_mul(blocked_product_i64(chunk.as_slice()));
        }
        Some(p)
    }

    /// Argmax/argmin (first-occurrence index) over an all-valid Float64 concat
    /// output, folding chunks in place. BIT-IDENTICAL to running
    /// `f64_argmax_first_index`/`_min` on the materialized buffer: that routine
    /// keeps an 8-lane running extreme where `lane = position % 8`, so iterating
    /// the chunks in 0..n order and updating `lane[pos % 8]` reproduces the exact
    /// same per-lane state, and the identical cross-lane reduction (max value,
    /// smallest index on ties = first occurrence) yields the same index — without
    /// materializing the cold buffer. `None` for empty/non-chunked.
    #[must_use]
    pub fn all_valid_f64_chunk_argextreme(&self, want_max: bool) -> Option<usize> {
        if self.dtype != DType::Float64 || !self.validity.all() {
            return None;
        }
        let chunks = self.values.float64_chunks_ref()?;
        let seed = if want_max {
            f64::NEG_INFINITY
        } else {
            f64::INFINITY
        };
        let mut lane_values = [seed; 8];
        let mut lane_indices = [0_usize; 8];
        let mut pos = 0_usize;
        for chunk in chunks {
            for &v in chunk.as_slice() {
                let lane = pos & 7;
                let better = if want_max {
                    v > lane_values[lane]
                } else {
                    v < lane_values[lane]
                };
                if better {
                    lane_values[lane] = v;
                    lane_indices[lane] = pos;
                }
                pos += 1;
            }
        }
        if pos == 0 {
            return None;
        }
        let mut best_value = lane_values[0];
        let mut best_index = lane_indices[0];
        for lane in 1..8 {
            let value = lane_values[lane];
            let index = lane_indices[lane];
            let better = if want_max {
                value > best_value
            } else {
                value < best_value
            };
            if better || (value == best_value && index < best_index) {
                best_value = value;
                best_index = index;
            }
        }
        Some(best_index)
    }

    /// Matches `pd.Series.sum()` in skipna=True mode via fp-types::nansum.
    /// Empty column returns 0.0 (matching pandas).
    #[must_use]
    pub fn sum(&self) -> Scalar {
        // Typed reduction: an all-valid Float64 column sums straight over its
        // contiguous buffer instead of materializing/iterating a Vec<Scalar>.
        // Bit-identical to nansum's Float64 arm: a sequential left-fold seeded
        // at 0.0 over the same values in the same order (no Timedelta/missing
        // branch applies to an all-valid Float64 column).
        // Chunk fast path: a `concat(...)` output is a lazy
        // `LazyAllValidFloat64Chunks`; fold each chunk slice in place (see
        // `all_valid_f64_chunk_sum`) instead of materializing the cold 40MB
        // concat buffer, so `concat(...).sum()` beats pandas' copy-then-sum.
        if let Some(s) = self.all_valid_f64_chunk_sum() {
            return Scalar::Float64(s);
        }
        if let Some(data) = self.as_f64_slice() {
            let mut s = 0.0_f64;
            for &x in data {
                s += x;
            }
            return Scalar::Float64(s);
        }
        // Timedelta64 (i64-ns): an all-valid, non-empty, no-NAT column sums exactly
        // in i128 over the raw &[i64] and clamps to i64 — the same accumulation and
        // clamp as nansum's `collect_timedelta_ns` arm, without materializing the
        // `Scalar` Vec. Empty / NAT / nullable falls to `nansum` (whose empty arm
        // returns `Float64(0.0)` and whose fold skips missing).
        if self.validity.all()
            && let Some(data) = self.as_timedelta64_slice()
            && !data.is_empty()
            && !data.contains(&i64::MIN)
        {
            let sum: i128 = data.iter().map(|&v| i128::from(v)).sum();
            let clamped = sum.clamp(i128::from(i64::MIN), i128::from(i64::MAX));
            return Scalar::Timedelta64(clamped as i64);
        }
        // Typed Bool reduction: sum of an all-valid Bool column is the count of
        // trues, over the raw &[bool] (a branchless count LLVM autovectorizes)
        // instead of materializing a Vec<Scalar> and per-Scalar `to_f64`.
        // Bit-identical to nansum's Bool arm: `Bool.to_f64()` is exactly 1.0/0.0,
        // so nansum returns `Float64(Σ)`; a sequential f64 fold of 0.0/1.0 values
        // is EXACT (each partial sum is an integer < 2^53), so `Σ == count`, and
        // `count as f64` is that same exact value.
        if let Some(data) = self.as_bool_slice() {
            let trues = data.iter().filter(|&&b| b).count();
            return Scalar::Float64(trues as f64);
        }
        // Typed Int64 sum: fold `v as f64` over the raw &[i64] (all-valid), matching
        // nansum's per-Scalar `to_f64` + f64 fold in the SAME order — bit-identical
        // (both lose precision above 2^53 identically) — without materializing the
        // Scalar Vec. Empty ⇒ 0.0, exactly nansum's empty arm.
        if let Some(data) = self.as_i64_slice() {
            let mut s = 0.0_f64;
            for &x in data {
                s += x as f64;
            }
            return Scalar::Float64(s);
        }
        // Nullable Float64 sum: fold PRESENT values (validity-set AND non-NaN, the
        // `Ok(x) if ...` / skip-missing behaviour of nansum). Bit-identical.
        if self.dtype == DType::Float64
            && let Some((data, validity)) = self.as_f64_slice_with_validity()
        {
            let mut s = 0.0_f64;
            for (i, &x) in data.iter().enumerate() {
                if validity.get(i) && !x.is_nan() {
                    s += x;
                }
            }
            return Scalar::Float64(s);
        }
        // Nullable Int64 sum: fold present `v as f64` (Int64 missingness is the
        // validity bit alone).
        if self.dtype == DType::Int64
            && let Some((data, validity)) = self.as_i64_slice_with_validity()
        {
            let mut s = 0.0_f64;
            for (i, &x) in data.iter().enumerate() {
                if validity.get(i) {
                    s += x as f64;
                }
            }
            return Scalar::Float64(s);
        }
        nansum(&self.values)
    }

    /// Arithmetic mean of non-missing values.
    ///
    /// Matches `pd.Series.mean()` via fp-types::nanmean. Empty column
    /// returns Null(NaN).
    #[must_use]
    pub fn mean(&self) -> Scalar {
        // Typed reduction (see `sum`): for an all-valid Float64 column nanmean
        // is `Σ / count` with count == len; an empty column stays Null(NaN).
        // Chunk fast path (see `all_valid_f64_chunk_mean`): fold the concat
        // chunks in place instead of materializing the cold buffer.
        if let Some(m) = self.all_valid_f64_chunk_mean() {
            return Scalar::Float64(m);
        }
        if let Some(data) = self.as_f64_slice() {
            if data.is_empty() {
                return Scalar::Null(NullKind::NaN);
            }
            let mut s = 0.0_f64;
            for &x in data {
                s += x;
            }
            return Scalar::Float64(s / data.len() as f64);
        }
        // Timedelta64 (see `sum`): all-valid, non-empty, no-NAT -> i128 `sum / len`
        // (count == len), clamped, dtype-preserved. Bit-identical to nanmean's
        // `collect_timedelta_ns` arm; empty / NAT / nullable falls to `nanmean`.
        if self.validity.all()
            && let Some(data) = self.as_timedelta64_slice()
            && !data.is_empty()
            && !data.contains(&i64::MIN)
        {
            let sum: i128 = data.iter().map(|&v| i128::from(v)).sum();
            let mean = sum / data.len() as i128;
            let clamped = mean.clamp(i128::from(i64::MIN), i128::from(i64::MAX));
            return Scalar::Timedelta64(clamped as i64);
        }
        // Typed Int64 mean: Σ(v as f64)/len (all-valid, count == len), matching
        // nanmean; empty ⇒ Null(NaN). No Scalar materialization of the lazy column.
        if let Some(data) = self.as_i64_slice() {
            if data.is_empty() {
                return Scalar::Null(NullKind::NaN);
            }
            let mut s = 0.0_f64;
            for &x in data {
                s += x as f64;
            }
            return Scalar::Float64(s / data.len() as f64);
        }
        // Nullable Float64/Int64 mean: Σ present / count present (present = validity
        // -set AND non-NaN for Float64; validity-set for Int64), matching nanmean's
        // sum+count of finite values. count 0 ⇒ Null(NaN).
        if self.dtype == DType::Float64
            && let Some((data, validity)) = self.as_f64_slice_with_validity()
        {
            let mut s = 0.0_f64;
            let mut count = 0usize;
            for (i, &x) in data.iter().enumerate() {
                if validity.get(i) && !x.is_nan() {
                    s += x;
                    count += 1;
                }
            }
            return if count == 0 {
                Scalar::Null(NullKind::NaN)
            } else {
                Scalar::Float64(s / count as f64)
            };
        }
        if self.dtype == DType::Int64
            && let Some((data, validity)) = self.as_i64_slice_with_validity()
        {
            let mut s = 0.0_f64;
            let mut count = 0usize;
            for (i, &x) in data.iter().enumerate() {
                if validity.get(i) {
                    s += x as f64;
                    count += 1;
                }
            }
            return if count == 0 {
                Scalar::Null(NullKind::NaN)
            } else {
                Scalar::Float64(s / count as f64)
            };
        }
        nanmean(&self.values)
    }

    /// Weighted average of non-missing values.
    ///
    /// Matches np.average(a, weights=w). Returns NaN if weights sum to zero.
    #[must_use]
    pub fn weighted_mean(&self, weights: &Self) -> Scalar {
        if self.len() != weights.len() {
            return Scalar::Null(NullKind::NaN);
        }
        // Typed pairwise fast path (sibling of cov/corr): when BOTH columns are
        // Float64/Int64 (all-valid or nullable) fold straight off the raw slices via
        // get_present, skipping the Vec<Scalar> materialization of BOTH columns +
        // per-Scalar is_missing/to_f64. Bit-identical: get_present == the reference's
        // `!v.is_missing() && v.to_f64().is_ok()` gate (validity-set AND non-NaN for
        // Float64, KEEPING ±inf; validity-set for Int64), so the same pairwise-present
        // (v,w) pairs accumulate sum += vf*wf / weight_sum += wf in the same 0..n
        // order, and the `weight_sum == 0.0 ⇒ Null(NaN)` guard is unchanged.
        if let (Some(sv), Some(sw)) = (self.typed_numeric_values(), weights.typed_numeric_values())
        {
            let n = sv.len().min(sw.len());
            let mut sum = 0.0_f64;
            let mut weight_sum = 0.0_f64;
            for i in 0..n {
                if let (Some(vf), Some(wf)) = (sv.get_present(i), sw.get_present(i)) {
                    sum += vf * wf;
                    weight_sum += wf;
                }
            }
            if weight_sum == 0.0 {
                return Scalar::Null(NullKind::NaN);
            }
            return Scalar::Float64(sum / weight_sum);
        }
        let mut sum = 0.0;
        let mut weight_sum = 0.0;
        for (v, w) in self.values.iter().zip(weights.values()) {
            if v.is_missing() || w.is_missing() {
                continue;
            }
            let vf = match v.to_f64() {
                Ok(x) => x,
                Err(_) => continue,
            };
            let wf = match w.to_f64() {
                Ok(x) => x,
                Err(_) => continue,
            };
            sum += vf * wf;
            weight_sum += wf;
        }
        if weight_sum == 0.0 {
            return Scalar::Null(NullKind::NaN);
        }
        Scalar::Float64(sum / weight_sum)
    }

    /// Alias for weighted_mean, matching np.average naming.
    #[must_use]
    pub fn average(&self, weights: &Self) -> Scalar {
        self.weighted_mean(weights)
    }

    /// Minimum non-missing value.
    ///
    /// Matches `pd.Series.min()` via fp-types::nanmin. Preserves dtype
    /// for homogeneous inputs.
    #[must_use]
    pub fn min(&self) -> Scalar {
        // Typed reduction: an all-valid numeric column folds the minimum straight
        // over its contiguous buffer (an associative reduction the compiler can
        // vectorize), skipping the Vec<Scalar> materialization. Bit-identical to
        // nanmin: it keeps the first element on a tie via strict `<` (so -0.0 vs
        // 0.0 ordering is preserved), and returns it dtype-preserved.
        if let Some(data) = self.as_f64_slice()
            && let Some((&first, rest)) = data.split_first()
        {
            let mut m = first;
            for &x in rest {
                if x < m {
                    m = x;
                }
            }
            return Scalar::Float64(m);
        }
        if let Some(data) = self.as_i64_slice()
            && let Some((&first, rest)) = data.split_first()
        {
            let mut m = first;
            for &x in rest {
                if x < m {
                    m = x;
                }
            }
            return Scalar::Int64(m);
        }
        // Datetime64 / Timedelta64 (i64-ns) reduce like Int64. Gate on all-valid +
        // no NAT (`i64::MIN`): `nanmin` SKIPS missing, so a NAT-bearing column must
        // stay on the `nanmin` path. For all-valid, no-NAT input the strict-`<` fold
        // (keeps the first on a tie, exactly like `nanmin`) returns the same min,
        // dtype-preserved — bit-identical, without materializing the `Scalar` Vec.
        if self.validity.all() {
            if let Some(data) = self.as_datetime64_slice()
                && let Some((&first, rest)) = data.split_first()
                && !data.contains(&i64::MIN)
            {
                let mut m = first;
                for &x in rest {
                    if x < m {
                        m = x;
                    }
                }
                return Scalar::Datetime64(m);
            }
            if let Some(data) = self.as_timedelta64_slice()
                && let Some((&first, rest)) = data.split_first()
                && !data.contains(&i64::MIN)
            {
                let mut m = first;
                for &x in rest {
                    if x < m {
                        m = x;
                    }
                }
                return Scalar::Timedelta64(m);
            }
        }
        // Contiguous-Utf8 fast path (byte-span sibling of unique/value_counts):
        // a Utf8 column's min otherwise falls to `nanmin`, which materializes a
        // `Vec<Scalar::Utf8>` (one heap `String` per row) then folds the
        // lexicographic minimum. Track the min byte span directly over the
        // contiguous buffer instead. Bit-identical to `nanmin`'s Utf8 arm: `&[u8]`
        // ordering equals `&str`/`String` ordering for valid UTF-8, and strict `<`
        // keeps the FIRST occurrence on a tie exactly as `nanmin` does.
        // `as_utf8_contiguous` matches only an all-valid backing (no missing to
        // skip); an empty column has no spans, so it falls through to `nanmin`
        // (→ `Null(NaN)`, unchanged).
        if let Some((bytes, offsets)) = self.as_utf8_contiguous() {
            let mut spans = offsets.windows(2);
            if let Some(first) = spans.next() {
                let mut best = &bytes[first[0]..first[1]];
                for w in spans {
                    let span = &bytes[w[0]..w[1]];
                    if span < best {
                        best = span;
                    }
                }
                let s = std::str::from_utf8(best).expect("contiguous-Utf8 spans are valid UTF-8");
                return Scalar::Utf8(s.to_owned());
            }
        }
        // Nullable Float64/Int64 (sibling of nullable `median`/`quantile`): fold the
        // minimum over the PRESENT values straight off the raw slice + validity,
        // skipping `nanmin`'s Scalar-Vec materialization + per-Scalar is_missing/
        // enum-match. Bit-identical to nanmin's numeric arms: present == not-missing
        // (validity-set AND non-NaN for Float64 — nanmin's is_missing treats a
        // valid-bit-set NaN as missing; validity bit for Int64), strict `<` keeps the
        // FIRST occurrence on a tie (so -0.0/0.0 order matches), all-missing/empty ⇒
        // Null(NaN). The dtype gates leave nanmin's Timedelta64/Datetime64 arms
        // (nullable temporal) untouched.
        if self.dtype == DType::Float64
            && let Some((data, validity)) = self.as_f64_slice_with_validity()
        {
            let mut m: Option<f64> = None;
            for (i, &x) in data.iter().enumerate() {
                if validity.get(i) && !x.is_nan() && m.is_none_or(|cur| x < cur) {
                    m = Some(x);
                }
            }
            return m.map_or(Scalar::Null(NullKind::NaN), Scalar::Float64);
        }
        if self.dtype == DType::Int64
            && let Some((data, validity)) = self.as_i64_slice_with_validity()
        {
            let mut m: Option<i64> = None;
            for (i, &x) in data.iter().enumerate() {
                if validity.get(i) && m.is_none_or(|cur| x < cur) {
                    m = Some(x);
                }
            }
            return m.map_or(Scalar::Null(NullKind::NaN), Scalar::Int64);
        }
        nanmin(&self.values)
    }

    /// Maximum non-missing value.
    ///
    /// Matches `pd.Series.max()` via fp-types::nanmax.
    #[must_use]
    pub fn max(&self) -> Scalar {
        // Typed reduction (see `min`); nanmax keeps the first element on a tie
        // via strict `>`, dtype-preserved.
        if let Some(data) = self.as_f64_slice()
            && let Some((&first, rest)) = data.split_first()
        {
            let mut m = first;
            for &x in rest {
                if x > m {
                    m = x;
                }
            }
            return Scalar::Float64(m);
        }
        if let Some(data) = self.as_i64_slice()
            && let Some((&first, rest)) = data.split_first()
        {
            let mut m = first;
            for &x in rest {
                if x > m {
                    m = x;
                }
            }
            return Scalar::Int64(m);
        }
        // Datetime64 / Timedelta64 (i64-ns) reduce like Int64; see `min`. Gate on
        // all-valid + no NAT so `nanmax`'s skip-missing behavior is preserved;
        // strict-`>` keeps the first on a tie exactly like `nanmax`. Bit-identical,
        // dtype-preserved, no `Scalar` materialization.
        if self.validity.all() {
            if let Some(data) = self.as_datetime64_slice()
                && let Some((&first, rest)) = data.split_first()
                && !data.contains(&i64::MIN)
            {
                let mut m = first;
                for &x in rest {
                    if x > m {
                        m = x;
                    }
                }
                return Scalar::Datetime64(m);
            }
            if let Some(data) = self.as_timedelta64_slice()
                && let Some((&first, rest)) = data.split_first()
                && !data.contains(&i64::MIN)
            {
                let mut m = first;
                for &x in rest {
                    if x > m {
                        m = x;
                    }
                }
                return Scalar::Timedelta64(m);
            }
        }
        // Contiguous-Utf8 fast path (symmetric to `min`): track the max byte span
        // directly over the contiguous buffer via strict `>` (keeps the FIRST on a
        // tie exactly like `nanmax`; `&[u8]` order == `&str` order for valid UTF-8)
        // instead of materializing a `Vec<Scalar::Utf8>`. All-valid only; empty
        // falls through to `nanmax` (→ `Null(NaN)`, unchanged).
        if let Some((bytes, offsets)) = self.as_utf8_contiguous() {
            let mut spans = offsets.windows(2);
            if let Some(first) = spans.next() {
                let mut best = &bytes[first[0]..first[1]];
                for w in spans {
                    let span = &bytes[w[0]..w[1]];
                    if span > best {
                        best = span;
                    }
                }
                let s = std::str::from_utf8(best).expect("contiguous-Utf8 spans are valid UTF-8");
                return Scalar::Utf8(s.to_owned());
            }
        }
        // Nullable Float64/Int64 (symmetric to `min`): fold the maximum over the
        // PRESENT values straight off the raw slice + validity, skipping nanmax's
        // Scalar-Vec materialization + per-Scalar is_missing/enum-match. Bit-identical
        // to nanmax's numeric arms: present == not-missing (validity-set AND non-NaN
        // for Float64; validity bit for Int64), strict `>` keeps the FIRST occurrence
        // on a tie, all-missing/empty ⇒ Null(NaN). dtype gates leave nanmax's
        // temporal arms untouched.
        if self.dtype == DType::Float64
            && let Some((data, validity)) = self.as_f64_slice_with_validity()
        {
            let mut m: Option<f64> = None;
            for (i, &x) in data.iter().enumerate() {
                if validity.get(i) && !x.is_nan() && m.is_none_or(|cur| x > cur) {
                    m = Some(x);
                }
            }
            return m.map_or(Scalar::Null(NullKind::NaN), Scalar::Float64);
        }
        if self.dtype == DType::Int64
            && let Some((data, validity)) = self.as_i64_slice_with_validity()
        {
            let mut m: Option<i64> = None;
            for (i, &x) in data.iter().enumerate() {
                if validity.get(i) && m.is_none_or(|cur| x > cur) {
                    m = Some(x);
                }
            }
            return m.map_or(Scalar::Null(NullKind::NaN), Scalar::Int64);
        }
        nanmax(&self.values)
    }

    /// Median of non-missing values.
    ///
    /// Matches `pd.Series.median()` via fp-types::nanmedian.
    /// Median over an all-valid `f64` buffer already extracted from the column:
    /// empty ⇒ `Null(NaN)`, else O(n) `select_nth_unstable_by(mid, partial_cmp)`
    /// then an odd/even midpoint (for even `n` the lower-middle is the MAX of the left
    /// partition). Shared by the Float64 and Int64 typed fast paths so both run
    /// the SAME computation `nanmedian`'s numeric arm performs after
    /// `collect_finite`; `select_nth_unstable_by` is deterministic, so identical
    /// input yields the identical `nums[mid-1]`/`nums[mid]`.
    fn median_from_f64_vec(mut nums: Vec<f64>) -> Scalar {
        if nums.is_empty() {
            return Scalar::Null(NullKind::NaN);
        }
        let n = nums.len();
        let mid = n / 2;
        let cmp = |a: &f64, b: &f64| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal);
        let (left, mid_ref, _right) = nums.select_nth_unstable_by(mid, cmp);
        let mid_val = *mid_ref;
        if n.is_multiple_of(2) {
            let lower = left.iter().copied().fold(f64::NEG_INFINITY, f64::max);
            Scalar::Float64((lower + mid_val) / 2.0)
        } else {
            Scalar::Float64(mid_val)
        }
    }

    #[must_use]
    pub fn median(&self) -> Scalar {
        // Typed Float64 fast path: order statistics straight over the contiguous
        // f64 buffer instead of materializing `Vec<Scalar>` then `collect_finite`'s
        // per-Scalar `to_f64`. `as_f64_slice` yields an all-valid buffer, so
        // `collect_finite` (which drops only MISSING, keeping every `to_f64`-able
        // value including NaN/inf) copies exactly these values in this order —
        // `data.to_vec()`.
        if let Some(data) = self.as_f64_slice() {
            return Self::median_from_f64_vec(data.to_vec());
        }
        // Typed Int64 fast path: `nanmedian`'s numeric arm maps each Scalar::Int64
        // through `collect_finite`'s `to_f64` (`v as f64`, exact for |v| < 2^53 and
        // identically lossy above it) then runs the SAME select_nth. An all-valid
        // i64 buffer converted the same way is bit-identical — no missing to drop,
        // no NaN introduced. Datetime64/Timedelta64 are excluded (`as_i64_slice`
        // gates dtype==Int64) so Timedelta64's dtype-preserving median is untouched.
        if let Some(data) = self.as_i64_slice() {
            return Self::median_from_f64_vec(data.iter().map(|&v| v as f64).collect());
        }
        // Nullable Float64/Int64: collect the PRESENT values (validity-set AND
        // non-NaN for Float64 — exactly collect_finite's drop-missing; validity bit
        // for Int64) into an f64 Vec and run the SAME median_from_f64_vec, skipping
        // nanmedian's Vec<Scalar> materialization + per-Scalar to_f64. Bit-identical:
        // the median is order-independent (select_nth), so the present multiset alone
        // determines it; empty present ⇒ median_from_f64_vec's empty ⇒ Null(NaN),
        // matching nanmedian.
        if self.dtype == DType::Float64
            && let Some((data, validity)) = self.as_f64_slice_with_validity()
        {
            let present: Vec<f64> = data
                .iter()
                .enumerate()
                .filter_map(|(i, &x)| (validity.get(i) && !x.is_nan()).then_some(x))
                .collect();
            return Self::median_from_f64_vec(present);
        }
        if self.dtype == DType::Int64
            && let Some((data, validity)) = self.as_i64_slice_with_validity()
        {
            let present: Vec<f64> = data
                .iter()
                .enumerate()
                .filter_map(|(i, &v)| validity.get(i).then_some(v as f64))
                .collect();
            return Self::median_from_f64_vec(present);
        }
        nanmedian(&self.values)
    }

    /// Product of non-missing values.
    ///
    /// Matches `pd.Series.prod()` via fp-types::nanprod. Empty column
    /// returns 1.0 (matching pandas).
    #[must_use]
    pub fn prod(&self) -> Scalar {
        // Typed reduction (mirror of `sum`): an all-valid Float64 column
        // multiplies straight over its contiguous buffer instead of iterating a
        // Vec<Scalar>. Bit-identical to nanprod's Float64 arm: a sequential
        // left-fold seeded at 1.0 over the same values in the same order. all-
        // valid ⇒ nothing is filtered and the all-missing→Null branch can't fire,
        // so empty folds to Float64(1.0) exactly as nanprod returns for empty.
        if let Some(data) = self.as_f64_slice() {
            let mut p = 1.0_f64;
            for &x in data {
                p *= x;
            }
            return Scalar::Float64(p);
        }
        // Typed Int64 product: Π(v as f64) seeded 1.0 (all-valid), matching nanprod;
        // empty ⇒ Float64(1.0). No Scalar materialization.
        if let Some(data) = self.as_i64_slice() {
            let mut p = 1.0_f64;
            for &x in data {
                p *= x as f64;
            }
            return Scalar::Float64(p);
        }
        // Nullable Float64/Int64 product: Π PRESENT values (validity-set AND non-NaN
        // for Float64 — a valid-bit NaN is missing, exactly nanprod's skip; validity
        // bit alone for Int64). All-missing ⇒ the 1.0 seed unchanged ⇒ Float64(1.0),
        // exactly nanprod's empty behaviour.
        if self.dtype == DType::Float64
            && let Some((data, validity)) = self.as_f64_slice_with_validity()
        {
            let mut p = 1.0_f64;
            for (i, &x) in data.iter().enumerate() {
                if validity.get(i) && !x.is_nan() {
                    p *= x;
                }
            }
            return Scalar::Float64(p);
        }
        if self.dtype == DType::Int64
            && let Some((data, validity)) = self.as_i64_slice_with_validity()
        {
            let mut p = 1.0_f64;
            for (i, &x) in data.iter().enumerate() {
                if validity.get(i) {
                    p *= x as f64;
                }
            }
            return Scalar::Float64(p);
        }
        nanprod(&self.values)
    }

