    /// Matches `pd.Series.sum(skipna=...)`.
    #[must_use]
    pub fn sum_skipna(&self, skipna: bool) -> Scalar {
        self.skipna_false_missing_result(skipna)
            .unwrap_or_else(|| self.sum())
    }

