    #[test]
    fn validity_mask_all_valid_sentinel_matches_explicit_words() {
        for len in [1, 2, 63, 64, 65, 127, 128, 129] {
            let sentinel = ValidityMask::all_valid(len);
            let explicit =
                ValidityMask::from_words(ValidityMask::materialized_all_valid_words(len), len);

            assert_eq!(sentinel, explicit, "len {len}");
            assert_eq!(
                sentinel.bits().collect::<Vec<_>>(),
                explicit.bits().collect::<Vec<_>>(),
                "len {len}"
            );
            assert!(sentinel.all(), "len {len}");
            assert_eq!(sentinel.count_invalid(), 0, "len {len}");
        }
    }

    #[test]
    fn validity_mask_all_valid_sentinel_materializes_on_clear() {
        let mut mask = ValidityMask::all_valid(130);
        mask.set(64, true);
        assert!(
            mask.words.is_empty(),
            "setting a valid bit preserves the sentinel"
        );

        mask.set(64, false);
        assert!(!mask.words.is_empty(), "clearing a bit materializes words");
        assert_eq!(mask.len(), 130);
        assert_eq!(mask.count_valid(), 129);
        assert!(!mask.get(64));
        assert!(mask.get(63));
        assert!(mask.get(65));
        assert_eq!(mask.bits().filter(|valid| *valid).count(), 129);

        mask.set(64, true);
        assert!(mask.all(), "restored packed words must report all-valid");
    }

    #[test]
    fn validity_mask_sparse_invalid_ranges_match_explicit_bitmap() {
        let sparse = ValidityMask::from_invalid_ranges(Arc::from(vec![(2, 3), (9, 2)]), 12);
        let mut explicit = ValidityMask::all_valid(12);
        for idx in [2, 3, 4, 9, 10] {
            explicit.set(idx, false);
        }

        assert!(sparse.words.is_empty());
        assert!(sparse.invalid_ranges.is_some());
        assert_eq!(sparse, explicit);
        assert_eq!(sparse.count_valid(), 7);
        assert_eq!(sparse.count_invalid(), 5);
        assert!(!sparse.all());
        assert!(sparse.get(1));
        assert!(!sparse.get(3));
        assert!(sparse.get(8));
        assert!(!sparse.get(10));
        assert_eq!(sparse.slice(1, 6), explicit.slice(1, 6));
        assert_eq!(sparse.not_mask(), explicit.not_mask());

        let mut mutated = sparse.clone();
        mutated.set(2, true);
        explicit.set(2, true);
        assert_eq!(mutated, explicit);
        assert!(mutated.invalid_ranges.is_none());
    }

