    #[test]
    fn apply_f64_slices_matches_fn_pointer_per_element_f64simd() {
        // The monomorphized slice op must be bit-for-bit identical to the
        // per-element fn pointer across every op and tricky operand
        // (NaN/inf/-0.0/zero divisor/negative base). Compared via raw bits so
        // NaN payloads must also match.
        let vals = [
            0.0_f64,
            -0.0,
            1.0,
            -1.0,
            2.5,
            -3.0,
            4.0,
            0.5,
            f64::NAN,
            f64::INFINITY,
            f64::NEG_INFINITY,
            1e300,
            -1e-300,
        ];
        let a: Vec<f64> = vals.to_vec();
        for op in [
            ArithmeticOp::Add,
            ArithmeticOp::Sub,
            ArithmeticOp::Mul,
            ArithmeticOp::Div,
            ArithmeticOp::Mod,
            ArithmeticOp::Pow,
            ArithmeticOp::FloorDiv,
        ] {
            for shift in 0..vals.len() {
                let b: Vec<f64> = (0..vals.len())
                    .map(|i| vals[(i + shift) % vals.len()])
                    .collect();
                let got = super::apply_f64_slices_nan_tracked(op, &a, &b).0;
                let apply = super::binary_f64_apply(op);
                let expected: Vec<f64> = a.iter().zip(&b).map(|(x, y)| apply(*x, *y)).collect();
                for i in 0..a.len() {
                    assert_eq!(
                        got[i].to_bits(),
                        expected[i].to_bits(),
                        "op={op:?} a={} b={}",
                        a[i],
                        b[i]
                    );
                }
            }
        }
    }

    #[test]
    fn apply_f64_slices_parallel_matches_serial_nan_tracking() {
        let n = (1usize << 20) + 17;
        let mut a: Vec<f64> = (0..n).map(|i| i as f64 * 0.25 + 1.0).collect();
        let mut b: Vec<f64> = (0..n).map(|i| i as f64 * 0.125 - 7.0).collect();
        a[1024] = f64::NAN;
        a[n - 3] = f64::INFINITY;
        b[n - 3] = f64::INFINITY;

        let (got, got_input_nan, got_output_nan) =
            super::apply_f64_slices_nan_tracked(ArithmeticOp::Sub, &a, &b);
        let mut expected = vec![0.0_f64; n];
        let (expected_input_nan, expected_output_nan) =
            super::apply_f64_slices_nan_tracked_into(ArithmeticOp::Sub, &a, &b, &mut expected);

        assert_eq!(got_input_nan, expected_input_nan);
        assert_eq!(got_output_nan, expected_output_nan);
        for i in 0..n {
            assert_eq!(got[i].to_bits(), expected[i].to_bits(), "i={i}");
        }
    }

