        #[test]
        fn cummax_cummin_nullable_typed_matches_nancum_reference() {
            // The nullable Int64/Float64 cummax/cummin typed paths must be
            // BYTE-IDENTICAL to the generic nancummax/nancummin (running extremum
            // over present values, Null(NaN) at missing). Null-missing only (no
            // present-NaN) so the Scalars compare structurally. Typed backings via
            // from_*_with_validity ⇒ the typed arm fires. Deterministic LCG.
            fn reference(vals: &[Scalar], is_max: bool) -> Vec<Scalar> {
                let mut running: Option<f64> = None;
                vals.iter()
                    .map(|v| {
                        if v.is_missing() {
                            return Scalar::Null(fp_types::NullKind::NaN);
                        }
                        match v.to_f64() {
                            Ok(x) if !x.is_nan() => {
                                let nv = match running {
                                    Some(p) => {
                                        if is_max {
                                            p.max(x)
                                        } else {
                                            p.min(x)
                                        }
                                    }
                                    None => x,
                                };
                                running = Some(nv);
                                Scalar::Float64(nv)
                            }
                            _ => Scalar::Null(fp_types::NullKind::NaN),
                        }
                    })
                    .collect()
            }
            let mut state: u64 = 0xCADE_1357_2468_ABCD;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            for trial in 0..150 {
                let n = (next() % 300) as usize + 1;
                let mut vi = crate::ValidityMask::all_valid(n);
                let mut vf = crate::ValidityMask::all_valid(n);
                let idata: Vec<i64> = (0..n)
                    .map(|i| {
                        let r = next();
                        if r % 4 == 0 {
                            vi.set(i, false);
                        }
                        (r % 41) as i64 - 20
                    })
                    .collect();
                let fdata: Vec<f64> = (0..n)
                    .map(|i| {
                        let r = next();
                        if r % 4 == 0 {
                            vf.set(i, false);
                            0.0
                        } else {
                            ((r % 41) as f64 - 20.0) / 3.0
                        }
                    })
                    .collect();
                let icol = Column::from_i64_values_with_validity(idata, vi);
                let fcol = Column::from_f64_values_with_validity(fdata, vf);
                for (col, tag) in [(&icol, "i64"), (&fcol, "f64")] {
                    let vals = col.values().to_vec();
                    assert_eq!(
                        col.cummax().expect("cummax").values(),
                        reference(&vals, true).as_slice(),
                        "{tag} cummax trial {trial}"
                    );
                    assert_eq!(
                        col.cummin().expect("cummin").values(),
                        reference(&vals, false).as_slice(),
                        "{tag} cummin trial {trial}"
                    );
                }
            }
        }

        #[test]
        fn cumsum_cumprod_nullable_typed_matches_nancum_reference() {
            // Nullable Int64/Float64 cumsum/cumprod typed paths must be BYTE-
            // IDENTICAL to nancumsum/nancumprod (running seeded 0.0/1.0, folded over
            // present values, Null(NaN) at missing). Null-missing only. Product uses
            // a NARROW value range near ±1 so the running product stays finite (no
            // inf → NaN divergence between paths). Deterministic LCG.
            fn reference(vals: &[Scalar], seed: f64, is_prod: bool) -> Vec<Scalar> {
                let mut running = seed;
                vals.iter()
                    .map(|v| {
                        if v.is_missing() {
                            return Scalar::Null(fp_types::NullKind::NaN);
                        }
                        match v.to_f64() {
                            Ok(x) if !x.is_nan() => {
                                if is_prod {
                                    running *= x;
                                } else {
                                    running += x;
                                }
                                Scalar::Float64(running)
                            }
                            _ => Scalar::Null(fp_types::NullKind::NaN),
                        }
                    })
                    .collect()
            }
            let mut state: u64 = 0x5023_9ABC_1234_DEF0;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            for trial in 0..150 {
                let n = (next() % 300) as usize + 1;
                let mut vi = crate::ValidityMask::all_valid(n);
                let mut vf = crate::ValidityMask::all_valid(n);
                // Small integer magnitudes so cumsum stays exact and cumprod finite.
                let idata: Vec<i64> = (0..n)
                    .map(|i| {
                        let r = next();
                        if r % 4 == 0 {
                            vi.set(i, false);
                        }
                        (r % 3) as i64 - 1 // {-1, 0, 1}
                    })
                    .collect();
                let fdata: Vec<f64> = (0..n)
                    .map(|i| {
                        let r = next();
                        if r % 4 == 0 {
                            vf.set(i, false);
                            0.0
                        } else {
                            0.5 + (r % 3) as f64 * 0.5 // {0.5, 1.0, 1.5}
                        }
                    })
                    .collect();
                let icol = Column::from_i64_values_with_validity(idata, vi);
                let fcol = Column::from_f64_values_with_validity(fdata, vf);
                for (col, tag) in [(&icol, "i64"), (&fcol, "f64")] {
                    let vals = col.values().to_vec();
                    assert_eq!(
                        col.cumsum().expect("cumsum").values(),
                        reference(&vals, 0.0, false).as_slice(),
                        "{tag} cumsum trial {trial}"
                    );
                    assert_eq!(
                        col.cumprod().expect("cumprod").values(),
                        reference(&vals, 1.0, true).as_slice(),
                        "{tag} cumprod trial {trial}"
                    );
                }
            }
        }

        #[test]
        fn unique_preserves_first_seen_order() {
            let col = Column::from_values(vec![
                Scalar::Int64(3),
                Scalar::Int64(1),
                Scalar::Int64(3),
                Scalar::Int64(2),
                Scalar::Int64(1),
            ])
            .expect("col");
            let u = col.unique().expect("unique");
            assert_eq!(u.len(), 3);
            assert_eq!(u.values()[0], Scalar::Int64(3));
            assert_eq!(u.values()[1], Scalar::Int64(1));
            assert_eq!(u.values()[2], Scalar::Int64(2));
        }

        #[test]
        fn unique_f64_open_addressing_matches_reference_and_signed_zero() {
            // Float64 wide path keys on NORMALIZED bits (−0.0 == +0.0) but keeps
            // the first-seen original — so -0.0-first stays -0.0.
            let col = Column::from_f64_values(vec![-0.0, 1.5, 0.0, 1.5, f64::INFINITY, -0.0]);
            let u = col.unique().expect("unique");
            let got: Vec<f64> = u
                .values()
                .iter()
                .map(|v| match v {
                    Scalar::Float64(x) => *x,
                    o => panic!("not f64: {o:?}"),
                })
                .collect();
            assert_eq!(got.len(), 3);
            assert!(
                got[0] == 0.0 && got[0].is_sign_negative(),
                "first unique is -0.0"
            );
            assert_eq!(got[1], 1.5);
            assert_eq!(got[2], f64::INFINITY);

            // Differential vs a first-seen HashSet<u64 normalized-bits> reference.
            use std::collections::HashSet;
            let mut state: u64 = 0x0F1E_2D3C_4B5A_6978;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            for _ in 0..120 {
                let n = (next() % 400) as usize + 1;
                let data: Vec<f64> = (0..n)
                    .map(|_| {
                        // mix of a few repeated buckets to force duplicates
                        let pick = next() % 7;
                        match pick {
                            0 => -0.0,
                            1 => 0.0,
                            2 => 1.0,
                            3 => -2.5,
                            4 => f64::INFINITY,
                            5 => (next() % 50) as f64,
                            _ => (next() >> 11) as f64 / (1u64 << 53) as f64,
                        }
                    })
                    .collect();
                let mut seen = HashSet::new();
                let expected: Vec<u64> = data
                    .iter()
                    .filter_map(|&f| {
                        let kb = (if f == 0.0 { 0.0 } else { f }).to_bits();
                        seen.insert(kb).then_some(f.to_bits())
                    })
                    .collect();
                let col = Column::from_f64_values(data);
                let got: Vec<u64> = col
                    .unique()
                    .expect("unique")
                    .values()
                    .iter()
                    .map(|v| match v {
                        Scalar::Float64(x) => x.to_bits(),
                        o => panic!("not f64: {o:?}"),
                    })
                    .collect();
                assert_eq!(got, expected);
            }
        }

        #[test]
        fn unique_wide_growable_fibonacci_rehash_matches_first_seen_reference() {
            // Regression for the unique_{f64,i64}_wide fix: many distinct WIDE /
            // high-bit-varying keys (> 1024 ⇒ multiple growable-table rehashes) — the
            // case the old low-bit `& mask` hash clustered — must keep BYTE-IDENTICAL
            // first-seen dedup order vs a HashSet reference. i64 also mixes i64::MIN.
            use std::collections::HashSet;
            let mut state: u64 = 0x2468_ACE0_1357_9BDF;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            for trial in 0..40 {
                let distinct = 2000 + (next() % 800) as i64;
                let n = 12_000usize;
                // i64: high-bit-only variation (k << 34), plus i64::MIN sentinel.
                let idata: Vec<i64> = (0..n)
                    .map(|i| {
                        if i % 500 == 0 {
                            i64::MIN
                        } else {
                            (((next() % distinct as u64) as i64) - distinct / 2) << 34
                        }
                    })
                    .collect();
                // f64: float-of-integer (variation in the HIGH to_bits() bits).
                let fdata: Vec<f64> = (0..n).map(|_| (next() % distinct as u64) as f64).collect();
                assert!(crate::i64_direct_address_range(&idata).is_none());

                let mut iseen: HashSet<i64> = HashSet::new();
                let iexp: Vec<i64> = idata
                    .iter()
                    .filter_map(|&v| iseen.insert(v).then_some(v))
                    .collect();
                let mut fseen: HashSet<u64> = HashSet::new();
                let fexp: Vec<u64> = fdata
                    .iter()
                    .filter_map(|&f| {
                        let kb = (if f == 0.0 { 0.0 } else { f }).to_bits();
                        fseen.insert(kb).then_some(f.to_bits())
                    })
                    .collect();

                let igot: Vec<i64> = Column::from_i64_values_owned(idata)
                    .unique()
                    .expect("unique")
                    .values()
                    .iter()
                    .map(|v| match v {
                        Scalar::Int64(x) => *x,
                        o => panic!("not i64: {o:?}"),
                    })
                    .collect();
                let fgot: Vec<u64> = Column::from_f64_values(fdata)
                    .unique()
                    .expect("unique")
                    .values()
                    .iter()
                    .map(|v| match v {
                        Scalar::Float64(x) => x.to_bits(),
                        o => panic!("not f64: {o:?}"),
                    })
                    .collect();
                assert_eq!(igot, iexp, "i64 trial {trial}");
                assert_eq!(fgot, fexp, "f64 trial {trial}");
            }
        }

        #[test]
        fn unique_datetime64_open_addressing_and_nat_fallthrough() {
            // All-valid, no-NaT Datetime64 takes the open-addressing ns path;
            // first-seen distinct timestamps, re-wrapped as Datetime64.
            let ns = vec![
                946_684_800_000_000_000i64,
                946_684_800_000_000_000,
                946_684_837_000_000_000,
                100,
                946_684_837_000_000_000,
                100,
            ];
            let col = Column::from_datetime64_values(ns);
            let u = col.unique().expect("unique");
            let got: Vec<i64> = u
                .values()
                .iter()
                .map(|v| match v {
                    Scalar::Datetime64(x) => *x,
                    other => panic!("expected Datetime64, got {other:?}"),
                })
                .collect();
            assert_eq!(
                got,
                vec![946_684_800_000_000_000, 946_684_837_000_000_000, 100]
            );

            // A NaT datum (i64::MIN) must fall through to the generic path, which
            // DROPS NaT — so the open-addressing shortcut must NOT emit it.
            let with_nat = Column::from_datetime64_values(vec![
                i64::MIN, // NaT sentinel
                5,
                5,
                i64::MIN,
                7,
            ]);
            let u2 = with_nat.unique().expect("unique nat");
            let got2: Vec<i64> = u2
                .values()
                .iter()
                .filter_map(|v| match v {
                    Scalar::Datetime64(x) => Some(*x),
                    _ => None,
                })
                .collect();
            assert_eq!(got2, vec![5, 7], "NaT must be dropped, not emitted");
        }

        #[test]
        fn unique_wide_i64_open_addressing_matches_reference() {
            // Wide/sparse all-valid Int64 uses unique_i64_wide (open-addressing
            // set). First-seen distinct must equal an insertion-ordered reference
            // across full-range data incl. the i64::MIN empty-sentinel.
            use std::collections::HashSet;
            let pool: [i64; 6] = [
                i64::MIN,
                i64::MAX,
                7_000_000_000_000_000_000,
                -7_000_000_000_000_000_000,
                42,
                -42,
            ];
            let mut state: u64 = 0xC0FF_EE00_1122_3344;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            for trial in 0..120 {
                let n = (next() % 400) as usize + 2;
                let mut data: Vec<i64> = (0..n)
                    .map(|_| pool[(next() as usize) % pool.len()])
                    .collect();
                data[0] = i64::MIN;
                data[1] = i64::MAX;
                assert!(
                    crate::i64_direct_address_range(&data).is_none(),
                    "trial {trial}: expected wide data"
                );
                // First-seen reference.
                let mut seen = HashSet::new();
                let mut expected: Vec<i64> = Vec::new();
                for &v in &data {
                    if seen.insert(v) {
                        expected.push(v);
                    }
                }
                let col = Column::from_i64_values_owned(data);
                let got: Vec<i64> = col
                    .unique()
                    .expect("unique")
                    .values()
                    .iter()
                    .filter_map(|v| match v {
                        Scalar::Int64(x) => Some(*x),
                        _ => None,
                    })
                    .collect();
                assert_eq!(got, expected, "trial {trial}");
            }
        }

