        #[test]
        fn nullable_float64_sort_na_last_radix_matches_scalar_reference_cf() {
            // Nullable / NaN-bearing Float64 na-last radix permutation must be
            // BIT-IDENTICAL to the stable compare_scalars_na_last comparator, both
            // orders. A slot is na-last iff missing OR present-NaN (both is_missing).
            // Mixes Null-missing (from_f64_values_with_validity) and present-NaN
            // (raw NaN in the buffer), plus ±inf, -0.0/+0.0 ties, and value ties.
            let mut state: u64 = 0x2468_ACE0_1357_9BDF;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            for trial in 0..200 {
                let n = (next() % 300) as usize + 1;
                let mut validity = ValidityMask::all_valid(n);
                let data: Vec<f64> = (0..n)
                    .map(|i| {
                        let r = next();
                        match r % 13 {
                            0 => {
                                validity.set(i, false);
                                0.0 // Null-missing slot (sentinel)
                            }
                            1 => f64::NAN, // present-NaN ⇒ na-last too
                            2 => f64::INFINITY,
                            3 => f64::NEG_INFINITY,
                            4 => -0.0,
                            _ => ((r % 11) as f64 - 5.0) / 2.0, // ties + negatives
                        }
                    })
                    .collect();
                let col = Column::from_f64_values_with_validity(data, validity);
                let vals = col.values();
                for ascending in [true, false] {
                    let mut want: Vec<usize> = (0..vals.len()).collect();
                    want.sort_by(|&a, &b| {
                        crate::compare_scalars_na_last(&vals[a], &vals[b], ascending)
                    });
                    assert_eq!(
                        col.argsort_with(ascending),
                        want,
                        "trial {trial} asc={ascending}"
                    );
                }
            }
        }

        #[test]
        fn nullable_temporal_sort_na_last_radix_matches_scalar_reference_cf() {
            // Nullable / NaT-bearing Datetime64 & Timedelta64 na-last radix
            // permutation must be BIT-IDENTICAL to the stable compare_scalars_na_last
            // comparator, both orders. na-last iff validity-clear OR datum == i64::MIN
            // (NaT sentinel). Mixes Null-missing (validity false) and present-NaT
            // (i64::MIN at a valid slot) plus ns ties.
            let mut state: u64 = 0x0F1E_2D3C_4B5A_6978;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            for trial in 0..200 {
                let n = (next() % 300) as usize + 1;
                let mut validity = ValidityMask::all_valid(n);
                let data: Vec<i64> = (0..n)
                    .map(|i| {
                        let r = next();
                        match r % 11 {
                            0 => {
                                validity.set(i, false);
                                12_345 // Null-missing (validity false)
                            }
                            1 => i64::MIN, // present-NaT (validity true, sentinel)
                            _ => 1_600_000_000_000i64 + ((r % 17) as i64) * 1_000,
                        }
                    })
                    .collect();
                for dt64 in [true, false] {
                    let col = if dt64 {
                        Column::from_datetime64_values_with_validity(data.clone(), validity.clone())
                    } else {
                        Column::from_timedelta64_values_with_validity(
                            data.clone(),
                            validity.clone(),
                        )
                    };
                    let vals = col.values();
                    for ascending in [true, false] {
                        let mut want: Vec<usize> = (0..vals.len()).collect();
                        want.sort_by(|&a, &b| {
                            crate::compare_scalars_na_last(&vals[a], &vals[b], ascending)
                        });
                        assert_eq!(
                            col.argsort_with(ascending),
                            want,
                            "dt64={dt64} trial {trial} asc={ascending}"
                        );
                    }
                }
            }
        }

        #[test]
        fn contiguous_utf8_argsort_matches_scalar_reference() {
            let raw = ["bee", "alpha", "bee", "alphabet", "", "zulu"];
            let scalars: Vec<Scalar> = raw
                .iter()
                .map(|value| Scalar::Utf8((*value).to_owned()))
                .collect();
            let scalar_col = Column::from_values(scalars.clone()).expect("scalar col");
            let mut bytes = Vec::new();
            let mut offsets = Vec::with_capacity(raw.len() + 1);
            offsets.push(0);
            for value in raw {
                bytes.extend_from_slice(value.as_bytes());
                offsets.push(bytes.len());
            }
            let contiguous_col = Column::from_utf8_contiguous(bytes, offsets);

            assert_eq!(contiguous_col.argsort_with(true), vec![4, 1, 3, 0, 2, 5]);
            assert_eq!(contiguous_col.argsort_with(false), vec![5, 0, 2, 3, 1, 4]);
            for ascending in [true, false] {
                let got = contiguous_col
                    .sort_values(ascending)
                    .expect("contiguous sort")
                    .values()
                    .to_vec();
                let want = scalar_col
                    .sort_values(ascending)
                    .expect("scalar sort")
                    .values()
                    .to_vec();
                assert_eq!(got, want, "ascending={ascending}");
            }
        }

        #[test]
        fn parallel_msd_radix_matches_serial_reference_qdrp7() {
            // n above PAR_MIN (1<<15) exercises the parallel fan-out path.
            // Common "key_" prefix forces serial descent before the fan-out
            // (the bench shape). Compare to a stable byte-lexicographic sort.
            let n = 40_000usize;
            let strings: Vec<String> = (0..n)
                .map(|i| {
                    let mixed = (i as u64)
                        .wrapping_mul(0x9E37_79B9_7F4A_7C15)
                        .rotate_left(17)
                        ^ (i as u64).wrapping_mul(0xBF58_476D_1CE4_E5B9);
                    format!("key_{mixed:016x}_{:04}", i % 97)
                })
                .collect();
            let spans: Vec<&[u8]> = strings.iter().map(|s| s.as_bytes()).collect();
            for ascending in [true, false] {
                let got = crate::utf8_msd_argsort_bytes(&spans, ascending);
                let mut want: Vec<usize> = (0..n).collect();
                want.sort_by(|&a, &b| {
                    let ord = spans[a].cmp(spans[b]);
                    if ascending { ord } else { ord.reverse() }
                });
                assert_eq!(
                    got, want,
                    "parallel radix != stable byte sort (asc={ascending})"
                );
            }
        }

        #[test]
        fn parallel_numeric_radix_matches_stable_reference_j5841() {
            // Exercise the parallel helper directly at a test-sized N. The
            // high 16 bits span many non-trivial prefixes (parallel work), while
            // the narrow low-bit domain forces exact-key ties (stability).
            let n = 50_000usize;
            let mut state = 0xA076_1D64_78BD_642F_u64;
            let keys: Vec<u64> = (0..n)
                .map(|i| {
                    state = state.wrapping_add(0x9E37_79B9_7F4A_7C15);
                    let mut z = state;
                    z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
                    z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
                    z ^= z >> 31;
                    (((i % 257) as u64) << 48) | (z % 4_096)
                })
                .collect();

            let got = crate::parallel_radix_argsort_u64(&keys, 4).expect("diverse prefix fan-out");
            let mut want: Vec<usize> = (0..n).collect();
            want.sort_by_key(|&position| keys[position]);
            assert_eq!(got, want);

            assert!(
                crate::parallel_radix_argsort_u64(&vec![7; n], 4).is_none(),
                "one non-trivial prefix must retain the serial fallback"
            );
        }

        #[test]
        fn parallel_multi_numeric_radix_matches_stable_reference() {
            // Exercise the shared-nothing multi-key helper directly below its
            // production size gate. Primary prefixes provide parallel ranges;
            // narrow low-bit domains create ties that pin stable row order.
            let n = 50_000usize;
            let mut state = 0xD1B5_4A32_D192_ED03_u64;
            let mut primary = Vec::with_capacity(n);
            let mut secondary = Vec::with_capacity(n);
            let mut tertiary = Vec::with_capacity(n);
            for row in 0..n {
                state = state.wrapping_add(0x9E37_79B9_7F4A_7C15);
                let mut z = state;
                z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
                z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
                z ^= z >> 31;
                primary.push((((row % 257) as u64) << 48) | (z % 1_024));
                secondary.push(z.rotate_left(19) % 127);
                tertiary.push(z.rotate_right(11) % 17);
            }
            let keys = vec![primary, secondary, tertiary];

            let got = crate::parallel_radix_argsort_multi_u64(&keys, 8)
                .expect("diverse primary prefixes expose independent buckets");
            let mut want: Vec<usize> = (0..n).collect();
            want.sort_by(|&left, &right| {
                keys.iter()
                    .map(|column| column[left].cmp(&column[right]))
                    .find(|order| *order != std::cmp::Ordering::Equal)
                    .unwrap_or(std::cmp::Ordering::Equal)
            });
            assert_eq!(got, want);

            let one_prefix = vec![vec![7; n], keys[1].clone()];
            assert!(
                crate::parallel_radix_argsort_multi_u64(&one_prefix, 8).is_none(),
                "one primary prefix must retain the serial fallback"
            );
        }

        #[test]
        fn contiguous_utf8_strict_witness_matches_byte_order_483i5() {
            fn contiguous(values: &[&str]) -> Column {
                let mut bytes = Vec::new();
                let mut offsets = Vec::with_capacity(values.len() + 1);
                offsets.push(0);
                for value in values {
                    bytes.extend_from_slice(value.as_bytes());
                    offsets.push(bytes.len());
                }
                Column::from_utf8_contiguous(bytes, offsets)
            }

            assert!(
                contiguous(&["a", "b", "c"])
                    .as_strictly_increasing_utf8_contiguous()
                    .is_some()
            );
            assert!(
                contiguous(&[])
                    .as_strictly_increasing_utf8_contiguous()
                    .is_some()
            );
            assert!(
                contiguous(&["only"])
                    .as_strictly_increasing_utf8_contiguous()
                    .is_some()
            );
            assert!(
                contiguous(&["a", "a"])
                    .as_strictly_increasing_utf8_contiguous()
                    .is_none()
            );
            assert!(
                contiguous(&["b", "a"])
                    .as_strictly_increasing_utf8_contiguous()
                    .is_none()
            );

            let scalar_backed = Column::from_values(vec![
                Scalar::Utf8("a".to_owned()),
                Scalar::Utf8("b".to_owned()),
            ])
            .expect("scalar-backed utf8");
            assert!(
                scalar_backed
                    .as_strictly_increasing_utf8_contiguous()
                    .is_none()
            );
        }

        #[test]
        fn contiguous_utf8_lower_hex_sequence_certificate_jbyuc111111() {
            fn contiguous(values: &[&str]) -> Column {
                let mut bytes = Vec::new();
                let mut offsets = Vec::with_capacity(values.len() + 1);
                offsets.push(0);
                for value in values {
                    bytes.extend_from_slice(value.as_bytes());
                    offsets.push(bytes.len());
                }
                Column::from_utf8_contiguous(bytes, offsets)
            }

            let certified = contiguous(&["id_0000000a", "id_0000000b", "id_0000000c"]);
            let (_, _, certificate) = certified
                .as_lower_hex_sequence_utf8_contiguous()
                .expect("lower-hex sequence certificate");
            assert_eq!(certificate.prefix_len(), 3);
            assert_eq!(certificate.hex_width(), 8);
            assert_eq!(certificate.width(), 11);
            assert_eq!(certificate.start(), 10);
            assert_eq!(certificate.value_at(2), Some(12));

            assert!(
                contiguous(&["id_0000000a", "id_0000000c"])
                    .as_lower_hex_sequence_utf8_contiguous()
                    .is_none(),
                "gapped sequences are not certified"
            );
            assert!(
                contiguous(&["id_0000000a", "id_0000000B"])
                    .as_lower_hex_sequence_utf8_contiguous()
                    .is_none(),
                "uppercase hex is not certified by the lowercase witness"
            );
            assert!(
                contiguous(&["0000000a", "0000000b"])
                    .as_lower_hex_sequence_utf8_contiguous()
                    .is_none(),
                "a prefix is required so arbitrary all-hex strings fall back"
            );
        }

        #[test]
        fn lower_hex_sequence_constructor_matches_contiguous_utf8_3wo1d() {
            let seeded =
                Column::from_lower_hex_sequence_utf8(b"id_", 0x0a, 3, 8).expect("seeded column");
            let manual = {
                let values = ["id_0000000a", "id_0000000b", "id_0000000c"];
                let mut bytes = Vec::new();
                let mut offsets = Vec::with_capacity(values.len() + 1);
                offsets.push(0);
                for value in values {
                    bytes.extend_from_slice(value.as_bytes());
                    offsets.push(bytes.len());
                }
                Column::from_utf8_contiguous(bytes, offsets)
            };

            assert_eq!(seeded.values(), manual.values());
            let (_, _, certificate) = seeded
                .as_lower_hex_sequence_utf8_contiguous()
                .expect("seeded certificate");
            assert_eq!(certificate.prefix_len(), 3);
            assert_eq!(certificate.hex_width(), 8);
            assert_eq!(certificate.width(), 11);
            assert_eq!(certificate.start(), 10);
            assert_eq!(certificate.value_at(2), Some(12));

            let empty =
                Column::from_lower_hex_sequence_utf8(b"id_", 0x0a, 0, 8).expect("empty column");
            assert!(empty.values().is_empty());
            assert!(empty.as_lower_hex_sequence_utf8_contiguous().is_none());
            let (empty_prefix, empty_certificate, empty_len) = empty
                .as_lower_hex_sequence_utf8()
                .expect("empty direct witness");
            assert_eq!(empty_prefix, b"id_");
            assert_eq!(empty_certificate.start(), 10);
            assert_eq!(empty_len, 0);

            assert!(Column::from_lower_hex_sequence_utf8(b"id_", 0x0e, 3, 1).is_none());
            assert!(Column::from_lower_hex_sequence_utf8(b"", 0x0a, 3, 8).is_none());
        }

        #[test]
        fn lower_hex_sequence_witness_stays_lazy_uza0447() {
            let column =
                Column::from_lower_hex_sequence_utf8(b"id_", 0x0a, 3, 8).expect("seeded column");
            assert!(matches!(
                &column.values,
                ScalarValues::LazyLowerHexSequenceUtf8 { .. }
            ));
            let ScalarValues::LazyLowerHexSequenceUtf8 { buffers, .. } = &column.values else {
                return;
            };
            assert!(buffers.get().is_none());

            let (prefix, certificate, len) =
                column.as_lower_hex_sequence_utf8().expect("direct witness");
            assert_eq!(prefix, b"id_");
            assert_eq!(certificate.prefix_len(), 3);
            assert_eq!(certificate.hex_width(), 8);
            assert_eq!(certificate.start(), 10);
            assert_eq!(len, 3);
            assert!(
                buffers.get().is_none(),
                "direct witness must not materialize bytes"
            );

            let (_, _, contiguous_certificate) = column
                .as_lower_hex_sequence_utf8_contiguous()
                .expect("contiguous materialization");
            assert_eq!(contiguous_certificate, certificate);
            assert!(
                buffers.get().is_some(),
                "contiguous accessor materializes exact old byte layout"
            );
        }

