        #[test]
        fn quantile_nullable_typed_match_nan_reference() {
            // Typed nullable Int64/Float64 quantile (collect present ⇒ quantile_from_
            // f64_vec) must be BIT-EXACT to nanquantile across q values. Float64 also
            // carries valid-bit-set NaN (dropped by the `!x.is_nan()` filter, exactly
            // collect_finite's is_missing-drops-NaN). all-missing/empty ⇒ Null(NaN);
            // out-of-range q ⇒ Null(NaN). Interpolation exercised via non-boundary q.
            let mut state: u64 = 0x5EED_9A1C_0FF1_3357;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            let bit_eq = |a: &Scalar, b: &Scalar| -> bool {
                match (a, b) {
                    (Scalar::Float64(x), Scalar::Float64(y)) => x.to_bits() == y.to_bits(),
                    (Scalar::Null(_), Scalar::Null(_)) => true,
                    _ => false,
                }
            };
            let qs = [0.0, 0.1, 0.25, 0.5, 0.75, 0.9, 1.0, 0.333, -0.1, 1.5];
            for trial in 0..250 {
                let n = (next() % 250) as usize;
                let mut vi = crate::ValidityMask::all_valid(n);
                let mut vf = crate::ValidityMask::all_valid(n);
                let idata: Vec<i64> = (0..n)
                    .map(|i| {
                        let r = next();
                        if r % 4 == 0 {
                            vi.set(i, false);
                        }
                        (r % 500) as i64 - 250
                    })
                    .collect();
                let fdata: Vec<f64> = (0..n)
                    .map(|i| {
                        let r = next();
                        if r % 5 == 0 {
                            vf.set(i, false);
                            0.0
                        } else if r % 5 == 1 {
                            // valid-bit-set NaN: present per validity, dropped as
                            // non-finite by both collect_finite and the typed filter.
                            f64::NAN
                        } else {
                            (r % 500) as f64 - 250.0
                        }
                    })
                    .collect();
                let i_all = Column::from_i64_values_owned(idata.clone());
                let i_null = Column::from_i64_values_with_validity(idata, vi);
                let f_null = Column::from_f64_values_with_validity(fdata, vf);
                for col in [&i_all, &i_null, &f_null] {
                    let vals = col.values().to_vec();
                    for &q in &qs {
                        assert!(
                            bit_eq(&col.quantile(q), &fp_types::nanquantile(&vals, q)),
                            "quantile trial {trial} q {q}"
                        );
                    }
                }
            }
        }

        #[test]
        fn logical_not_numeric_nullable_typed_match_scalar_reference() {
            // The typed Int64/Float64 arms for logical_not (Bool output) must be
            // BIT-EXACT to the Scalar loop: present ⇒ Bool(v == 0); missing / valid-bit
            // -set NaN ⇒ Null(Null). Covers 0, ±inf (⇒ Bool(false)), negatives, gaps.
            let mut state: u64 = 0x106_C0DE_1234_9E37;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            let bit_eq = |a: &Scalar, b: &Scalar| -> bool {
                match (a, b) {
                    (Scalar::Bool(x), Scalar::Bool(y)) => x == y,
                    (Scalar::Null(_), Scalar::Null(_)) => true,
                    _ => false,
                }
            };
            fn ref_lognot(vals: &[Scalar]) -> Column {
                let out: Vec<Scalar> = vals
                    .iter()
                    .map(|v| {
                        if v.is_missing() {
                            Scalar::Null(NullKind::Null)
                        } else {
                            let bv = match v {
                                Scalar::Bool(x) => *x,
                                _ => v.to_f64().map(|x| x != 0.0).unwrap_or(false),
                            };
                            Scalar::Bool(!bv)
                        }
                    })
                    .collect();
                Column::new(DType::Bool, out).unwrap()
            }
            for trial in 0..300 {
                let n = (next() % 250) as usize;
                let mut vf = crate::ValidityMask::all_valid(n);
                let mut vi = crate::ValidityMask::all_valid(n);
                let fdata: Vec<f64> = (0..n)
                    .map(|i| {
                        let r = next();
                        match r % 7 {
                            0 => {
                                vf.set(i, false);
                                0.0
                            }
                            1 => f64::NAN,
                            2 => f64::INFINITY,
                            3 => 0.0, // ⇒ Bool(true)
                            _ => ((r % 400) as f64 - 200.0) * 0.5,
                        }
                    })
                    .collect();
                let idata: Vec<i64> = (0..n)
                    .map(|i| {
                        let r = next();
                        if r % 5 == 0 {
                            vi.set(i, false);
                        }
                        (r % 5) as i64 - 2 // -2..2 incl 0
                    })
                    .collect();
                let f_null = Column::from_f64_values_with_validity(fdata, vf);
                let i_null = Column::from_i64_values_with_validity(idata, vi);
                let i_all =
                    Column::from_i64_values_owned((0..n).map(|i| (i % 3) as i64 - 1).collect());
                for col in [&f_null, &i_null, &i_all] {
                    let vals = col.values().to_vec();
                    let got = col.logical_not().unwrap();
                    let want = ref_lognot(&vals);
                    let gv = got.values();
                    let wv = want.values();
                    assert_eq!(gv.len(), wv.len(), "lognot len trial {trial}");
                    for (k, (g, w)) in gv.iter().zip(wv.iter()).enumerate() {
                        assert!(bit_eq(g, w), "lognot trial {trial} idx {k}: {g:?} != {w:?}");
                    }
                }
            }
        }

        #[test]
        fn logical_binop_bool_nullable_typed_match_scalar_reference() {
            // The typed_bool_binary_nullable arm for logical_and/or/xor must be
            // BIT-EXACT to the Scalar loop over nullable Bool operands: present∧present
            // ⇒ Bool(op); either missing ⇒ Null(Null). Covers nullable×nullable,
            // all-valid×nullable, nullable×all-valid, and all-valid×all-valid (which
            // takes the earlier typed_bool_binary path). AND/OR/XOR each checked.
            let mut state: u64 = 0xB001_C0DE_1234_9E37;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            let bit_eq = |a: &Scalar, b: &Scalar| -> bool {
                match (a, b) {
                    (Scalar::Bool(x), Scalar::Bool(y)) => x == y,
                    (Scalar::Null(_), Scalar::Null(_)) => true,
                    _ => false,
                }
            };
            fn ref_binop(a: &[Scalar], b: &[Scalar], op: fn(bool, bool) -> bool) -> Column {
                let out: Vec<Scalar> = a
                    .iter()
                    .zip(b)
                    .map(|(x, y)| {
                        if x.is_missing() || y.is_missing() {
                            Scalar::Null(NullKind::Null)
                        } else {
                            let xv = match x {
                                Scalar::Bool(v) => *v,
                                _ => x.to_f64().map(|v| v != 0.0).unwrap_or(false),
                            };
                            let yv = match y {
                                Scalar::Bool(v) => *v,
                                _ => y.to_f64().map(|v| v != 0.0).unwrap_or(false),
                            };
                            Scalar::Bool(op(xv, yv))
                        }
                    })
                    .collect();
                Column::new(DType::Bool, out).unwrap()
            }
            // Build a Bool column: `nullable`=false ⇒ all-valid (from_bool_values via
            // the folding constructor); true ⇒ some slots masked out.
            let build = |n: usize, nullable: bool, next: &mut dyn FnMut() -> u64| -> Column {
                let mut validity = crate::ValidityMask::all_valid(n);
                let data: Vec<bool> = (0..n)
                    .map(|i| {
                        let r = next();
                        if nullable && r.is_multiple_of(4) {
                            validity.set(i, false);
                        }
                        (r >> 19) & 1 == 1
                    })
                    .collect();
                Column::from_bool_values_with_validity(data, validity)
            };
            type BoolScalarOp = fn(bool, bool) -> bool;
            type BoolColumnOp = fn(&Column, &Column) -> Result<Column, ColumnError>;
            let ops: [(BoolScalarOp, BoolColumnOp); 3] = [
                (|a, b| a && b, |a, b| a.logical_and(b)),
                (|a, b| a || b, |a, b| a.logical_or(b)),
                (|a, b| a ^ b, |a, b| a.logical_xor(b)),
            ];
            for trial in 0..250 {
                let n = (next() % 200) as usize;
                for (ln, rn) in [(true, true), (false, true), (true, false), (false, false)] {
                    let a = build(n, ln, &mut next);
                    let b = build(n, rn, &mut next);
                    let av = a.values().to_vec();
                    let bv = b.values().to_vec();
                    for (ref_op, col_op) in ops.iter() {
                        let got = col_op(&a, &b).unwrap();
                        let want = ref_binop(&av, &bv, *ref_op);
                        let gv = got.values();
                        let wv = want.values();
                        assert_eq!(gv.len(), wv.len(), "binop len trial {trial}");
                        for (k, (g, w)) in gv.iter().zip(wv.iter()).enumerate() {
                            assert!(
                                bit_eq(g, w),
                                "binop trial {trial} ln={ln} rn={rn} idx {k}: {g:?} != {w:?}"
                            );
                        }
                    }
                }
            }
        }

        #[test]
        fn floor_ceil_trunc_nullable_typed_match_scalar_reference() {
            // The new nullable Float64/Int64 arms in typed_float_unary_finite_preserving
            // must make floor/ceil/trunc BIT-EXACT to their Scalar path on nullable
            // input (missing/valid-bit-set-NaN ⇒ NaN⇒missing; present ⇒ f). Covers
            // fractional values, negatives, ±inf, x==0.5/-0.5 (ties differ per op).
            let mut state: u64 = 0xF100_C0DE_1234_9E37;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            let bit_eq = |a: &Scalar, b: &Scalar| -> bool {
                match (a, b) {
                    (Scalar::Float64(x), Scalar::Float64(y)) => x.to_bits() == y.to_bits(),
                    (Scalar::Null(_), Scalar::Null(_)) => true,
                    _ => false,
                }
            };
            // Replica of floor/ceil/trunc's Scalar path (always Float64 output).
            fn ref_op(vals: &[Scalar], f: impl Fn(f64) -> f64) -> Column {
                let out: Vec<Scalar> = vals
                    .iter()
                    .map(|v| {
                        if v.is_missing() {
                            Scalar::Float64(f64::NAN)
                        } else {
                            match v {
                                Scalar::Int64(x) => Scalar::Float64(*x as f64),
                                Scalar::Float64(x) => Scalar::Float64(f(*x)),
                                _ => unreachable!(),
                            }
                        }
                    })
                    .collect();
                Column::new(DType::Float64, out).unwrap()
            }
            for trial in 0..300 {
                let n = (next() % 200) as usize;
                let mut vf = crate::ValidityMask::all_valid(n);
                let mut vi = crate::ValidityMask::all_valid(n);
                let fdata: Vec<f64> = (0..n)
                    .map(|i| {
                        let r = next();
                        match r % 8 {
                            0 => {
                                vf.set(i, false);
                                0.0
                            }
                            1 => f64::NAN,
                            2 => f64::INFINITY,
                            3 => f64::NEG_INFINITY,
                            _ => ((r % 4000) as f64 - 2000.0) * 0.013, // fractional, +/-
                        }
                    })
                    .collect();
                let idata: Vec<i64> = (0..n)
                    .map(|i| {
                        let r = next();
                        if r % 5 == 0 {
                            vi.set(i, false);
                        }
                        (r % 400) as i64 - 200
                    })
                    .collect();
                let f_null = Column::from_f64_values_with_validity(fdata, vf);
                let i_null = Column::from_i64_values_with_validity(idata, vi);
                for col in [&f_null, &i_null] {
                    let vals = col.values().to_vec();
                    for (name, got, want) in [
                        ("floor", col.floor().unwrap(), ref_op(&vals, f64::floor)),
                        ("ceil", col.ceil().unwrap(), ref_op(&vals, f64::ceil)),
                        ("trunc", col.trunc().unwrap(), ref_op(&vals, f64::trunc)),
                    ] {
                        let gv = got.values();
                        let wv = want.values();
                        assert_eq!(gv.len(), wv.len(), "{name} len trial {trial}");
                        for (k, (g, w)) in gv.iter().zip(wv.iter()).enumerate() {
                            assert!(bit_eq(g, w), "{name} trial {trial} idx {k}: {g:?} != {w:?}");
                        }
                    }
                }
            }
        }

        #[test]
        fn bitwise_not_int64_typed_match_scalar_reference() {
            // The typed Int64 arms (all-valid + nullable) for bitwise_not must be
            // BIT-EXACT to the Scalar loop: present ⇒ Int64(!x); missing ⇒ Null(Null).
            // Covers negatives, i64::MIN/MAX, gaps.
            let mut state: u64 = 0xB17_C0DE_1234_9E37;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            let bit_eq = |a: &Scalar, b: &Scalar| -> bool {
                match (a, b) {
                    (Scalar::Int64(x), Scalar::Int64(y)) => x == y,
                    (Scalar::Null(_), Scalar::Null(_)) => true,
                    _ => false,
                }
            };
            fn ref_not(vals: &[Scalar]) -> Column {
                let out: Vec<Scalar> = vals
                    .iter()
                    .map(|v| {
                        if v.is_missing() {
                            Scalar::Null(NullKind::Null)
                        } else {
                            match v {
                                Scalar::Int64(x) => Scalar::Int64(!x),
                                _ => unreachable!(),
                            }
                        }
                    })
                    .collect();
                Column::new(DType::Int64, out).unwrap()
            }
            for trial in 0..300 {
                let n = (next() % 250) as usize;
                let mut vi = crate::ValidityMask::all_valid(n);
                let idata: Vec<i64> = (0..n)
                    .map(|i| {
                        let r = next();
                        if r % 4 == 0 {
                            vi.set(i, false);
                        }
                        match r % 11 {
                            0 => i64::MIN,
                            1 => i64::MAX,
                            2 => 0,
                            _ => (r as i64).wrapping_sub(i64::MAX / 2),
                        }
                    })
                    .collect();
                let i_all = Column::from_i64_values_owned(idata.clone());
                let i_null = Column::from_i64_values_with_validity(idata, vi);
                for col in [&i_all, &i_null] {
                    let vals = col.values().to_vec();
                    let got = col.bitwise_not().unwrap();
                    let want = ref_not(&vals);
                    let gv = got.values();
                    let wv = want.values();
                    assert_eq!(gv.len(), wv.len(), "not len trial {trial}");
                    for (k, (g, w)) in gv.iter().zip(wv.iter()).enumerate() {
                        assert!(bit_eq(g, w), "not trial {trial} idx {k}: {g:?} != {w:?}");
                    }
                }
            }
        }

        #[test]
        fn mask_nullable_int64_self_typed_match_scalar_reference() {
            // The typed nullable-Int64-self arm for mask (all-valid Bool cond) must be
            // BIT-EXACT to the generic Scalar loop: cond[i] ? other : self[i] (inverse
            // of where_cond). self missing at cond-false ⇒ Null(Null); cond-true ⇒ other.
            let mut state: u64 = 0x11A5_C0DE_1234_9E37;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            let bit_eq = |a: &Scalar, b: &Scalar| -> bool {
                match (a, b) {
                    (Scalar::Int64(x), Scalar::Int64(y)) => x == y,
                    (Scalar::Null(_), Scalar::Null(_)) => true,
                    _ => false,
                }
            };
            fn ref_mask(vals: &[Scalar], cb: &[bool], other: &Scalar) -> Column {
                let out: Vec<Scalar> = vals
                    .iter()
                    .zip(cb.iter())
                    .map(|(v, &c)| if c { other.clone() } else { v.clone() })
                    .collect();
                Column::new(DType::Int64, out).unwrap()
            }
            let other = Scalar::Int64(-99);
            for trial in 0..300 {
                let n = (next() % 200) as usize;
                let cb: Vec<bool> = (0..n).map(|_| next() % 2 == 0).collect();
                let cond = Column::from_bool_values(cb.clone());
                let mut vi = crate::ValidityMask::all_valid(n);
                let data: Vec<i64> = (0..n)
                    .map(|i| {
                        let r = next();
                        if r % 4 == 0 {
                            vi.set(i, false);
                        }
                        (r % 400) as i64 - 200
                    })
                    .collect();
                let col = Column::from_i64_values_with_validity(data, vi);
                let vals = col.values().to_vec();
                let got = col.mask(&cond, &other).unwrap();
                let want = ref_mask(&vals, &cb, &other);
                let gv = got.values();
                let wv = want.values();
                assert_eq!(gv.len(), wv.len(), "mask len trial {trial}");
                for (k, (g, w)) in gv.iter().zip(wv.iter()).enumerate() {
                    assert!(bit_eq(g, w), "mask trial {trial} idx {k}: {g:?} != {w:?}");
                }
            }
        }

        #[test]
        fn where_cond_nullable_self_typed_match_scalar_reference() {
            // The typed nullable-self arms for where_cond (all-valid Bool cond) must be
            // BIT-EXACT to the generic Scalar loop: cond[i] ? self[i] : other. Covers
            // Float64 self (with valid-bit-set NaN + ±inf) and Int64 self, self missing
            // at cond-true (⇒ dtype-correct null) and cond-false, gaps.
            let mut state: u64 = 0x3E4E_C0DE_1234_9E37;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            let bit_eq = |a: &Scalar, b: &Scalar| -> bool {
                match (a, b) {
                    (Scalar::Float64(x), Scalar::Float64(y)) => x.to_bits() == y.to_bits(),
                    (Scalar::Int64(x), Scalar::Int64(y)) => x == y,
                    (Scalar::Null(_), Scalar::Null(_)) => true,
                    _ => false,
                }
            };
            // Replica of the generic loop for an ALL-VALID cond (no cond-missing branch).
            fn ref_where(vals: &[Scalar], cb: &[bool], other: &Scalar, dtype: DType) -> Column {
                let out: Vec<Scalar> = vals
                    .iter()
                    .zip(cb.iter())
                    .map(|(v, &c)| if c { v.clone() } else { other.clone() })
                    .collect();
                Column::new(dtype, out).unwrap()
            }
            for trial in 0..300 {
                let n = (next() % 200) as usize;
                let cb: Vec<bool> = (0..n).map(|_| next() % 2 == 0).collect();
                let cond = Column::from_bool_values(cb.clone());
                let is_f64 = trial % 2 == 0;
                let (col, other) = if is_f64 {
                    let mut vf = crate::ValidityMask::all_valid(n);
                    let data: Vec<f64> = (0..n)
                        .map(|i| {
                            let r = next();
                            match r % 7 {
                                0 => {
                                    vf.set(i, false);
                                    0.0
                                }
                                1 => f64::NAN,
                                2 => f64::INFINITY,
                                _ => ((r % 400) as f64 - 200.0) * 0.25,
                            }
                        })
                        .collect();
                    (
                        Column::from_f64_values_with_validity(data, vf),
                        Scalar::Float64(-7.5),
                    )
                } else {
                    let mut vi = crate::ValidityMask::all_valid(n);
                    let data: Vec<i64> = (0..n)
                        .map(|i| {
                            let r = next();
                            if r % 4 == 0 {
                                vi.set(i, false);
                            }
                            (r % 400) as i64 - 200
                        })
                        .collect();
                    (
                        Column::from_i64_values_with_validity(data, vi),
                        Scalar::Int64(-99),
                    )
                };
                let vals = col.values().to_vec();
                let got = col.where_cond(&cond, &other).unwrap();
                let dt = if is_f64 { DType::Float64 } else { DType::Int64 };
                let want = ref_where(&vals, &cb, &other, dt);
                let gv = got.values();
                let wv = want.values();
                assert_eq!(gv.len(), wv.len(), "where len trial {trial}");
                for (k, (g, w)) in gv.iter().zip(wv.iter()).enumerate() {
                    assert!(bit_eq(g, w), "where trial {trial} idx {k}: {g:?} != {w:?}");
                }
            }
        }

        #[test]
        fn isclose_nullable_typed_match_scalar_reference() {
            // The typed pairwise isclose arm must be BIT-EXACT to the generic Scalar
            // loop (either-missing ⇒ Bool(false); else (af-bf).abs() <= atol+rtol*|bf|).
            // Reference off the MATERIALIZED values(). MIXED dtypes, nullable at
            // DIFFERENT positions, ±inf (kept ⇒ inf comparisons ⇒ false), valid-bit-set
            // NaN (⇒ missing ⇒ false), across several (rtol, atol).
            let mut state: u64 = 0xC105_E1DE_1234_9E37;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            let bit_eq = |a: &Scalar, b: &Scalar| -> bool {
                match (a, b) {
                    (Scalar::Bool(x), Scalar::Bool(y)) => x == y,
                    _ => false,
                }
            };
            fn ref_isclose(a: &[Scalar], b: &[Scalar], rtol: f64, atol: f64) -> Column {
                let out: Vec<Scalar> = a
                    .iter()
                    .zip(b.iter())
                    .map(|(x, y)| {
                        if x.is_missing() || y.is_missing() {
                            Scalar::Bool(false)
                        } else {
                            let af = x.to_f64().unwrap();
                            let bf = y.to_f64().unwrap();
                            Scalar::Bool((af - bf).abs() <= atol + rtol * bf.abs())
                        }
                    })
                    .collect();
                Column::new(DType::Bool, out).unwrap()
            }
            let mk_f64 = |n: usize, next: &mut dyn FnMut() -> u64| -> Column {
                let mut vf = crate::ValidityMask::all_valid(n);
                let data: Vec<f64> = (0..n)
                    .map(|i| {
                        let r = next();
                        match r % 8 {
                            0 => {
                                vf.set(i, false);
                                0.0
                            }
                            1 => f64::NAN,
                            2 => f64::INFINITY,
                            3 => f64::NEG_INFINITY,
                            _ => ((r % 400) as f64 - 200.0) * 0.25,
                        }
                    })
                    .collect();
                Column::from_f64_values_with_validity(data, vf)
            };
            let mk_i64 = |n: usize, next: &mut dyn FnMut() -> u64| -> Column {
                let mut vi = crate::ValidityMask::all_valid(n);
                let data: Vec<i64> = (0..n)
                    .map(|i| {
                        let r = next();
                        if r.is_multiple_of(5) {
                            vi.set(i, false);
                        }
                        (r % 400) as i64 - 200
                    })
                    .collect();
                Column::from_i64_values_with_validity(data, vi)
            };
            let tols = [(1e-5f64, 1e-8f64), (0.0, 0.0), (1e9, 1e9), (0.1, 1.0)];
            for trial in 0..300 {
                let n = (next() % 200) as usize;
                let (a, b) = match trial % 4 {
                    0 => (mk_i64(n, &mut next), mk_f64(n, &mut next)),
                    1 => (mk_f64(n, &mut next), mk_i64(n, &mut next)),
                    2 => (mk_f64(n, &mut next), mk_f64(n, &mut next)),
                    _ => (mk_i64(n, &mut next), mk_i64(n, &mut next)),
                };
                let av = a.values().to_vec();
                let bv = b.values().to_vec();
                let (rtol, atol) = tols[trial % tols.len()];
                let got = a.isclose(&b, rtol, atol).unwrap();
                let want = ref_isclose(&av, &bv, rtol, atol);
                let gv = got.values();
                let wv = want.values();
                assert_eq!(gv.len(), wv.len(), "isclose len trial {trial}");
                for (k, (g, w)) in gv.iter().zip(wv.iter()).enumerate() {
                    assert!(
                        bit_eq(g, w),
                        "isclose trial {trial} idx {k}: {g:?} != {w:?}"
                    );
                }
            }
        }

        #[test]
        fn heaviside_ldexp_nullable_typed_match_scalar_reference() {
            // heaviside(h0)/ldexp(exp) now route through typed_float_unary. Must be
            // BIT-EXACT to their generic Scalar loop (missing/NaN ⇒ NaN⇒missing; present
            // ⇒ kernel). Covers x==0 (⇒ h0), ±inf, valid-bit-set NaN, negatives, gaps,
            // and h0==NaN (heaviside(0) ⇒ NaN⇒missing).
            let mut state: u64 = 0x4EA0_51DE_1234_9E37;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            let bit_eq = |a: &Scalar, b: &Scalar| -> bool {
                match (a, b) {
                    (Scalar::Float64(x), Scalar::Float64(y)) => x.to_bits() == y.to_bits(),
                    (Scalar::Null(_), Scalar::Null(_)) => true,
                    _ => false,
                }
            };
            fn ref_heaviside(vals: &[Scalar], h0: f64) -> Column {
                let out: Vec<Scalar> = vals
                    .iter()
                    .map(|v| {
                        if v.is_missing() {
                            return Scalar::Float64(f64::NAN);
                        }
                        match v {
                            Scalar::Int64(x) => Scalar::Float64(if *x < 0 {
                                0.0
                            } else if *x > 0 {
                                1.0
                            } else {
                                h0
                            }),
                            Scalar::Float64(x) => Scalar::Float64(if x.is_nan() {
                                f64::NAN
                            } else if *x < 0.0 {
                                0.0
                            } else if *x > 0.0 {
                                1.0
                            } else {
                                h0
                            }),
                            _ => unreachable!(),
                        }
                    })
                    .collect();
                Column::new(DType::Float64, out).unwrap()
            }
            fn ref_ldexp(vals: &[Scalar], exp: i32) -> Column {
                let m = 2.0_f64.powi(exp);
                let out: Vec<Scalar> = vals
                    .iter()
                    .map(|v| {
                        if v.is_missing() {
                            return Scalar::Float64(f64::NAN);
                        }
                        match v {
                            Scalar::Int64(x) => Scalar::Float64(*x as f64 * m),
                            Scalar::Float64(x) => Scalar::Float64(x * m),
                            _ => unreachable!(),
                        }
                    })
                    .collect();
                Column::new(DType::Float64, out).unwrap()
            }
            let mk_f64 = |n: usize, next: &mut dyn FnMut() -> u64| -> Column {
                let mut vf = crate::ValidityMask::all_valid(n);
                let data: Vec<f64> = (0..n)
                    .map(|i| {
                        let r = next();
                        match r % 8 {
                            0 => {
                                vf.set(i, false);
                                0.0
                            }
                            1 => f64::NAN,
                            2 => f64::INFINITY,
                            3 => f64::NEG_INFINITY,
                            4 => 0.0, // heaviside ⇒ h0
                            _ => ((r % 400) as f64 - 200.0) * 0.25,
                        }
                    })
                    .collect();
                Column::from_f64_values_with_validity(data, vf)
            };
            let mk_i64 = |n: usize, next: &mut dyn FnMut() -> u64| -> Column {
                let mut vi = crate::ValidityMask::all_valid(n);
                let data: Vec<i64> = (0..n)
                    .map(|i| {
                        let r = next();
                        if r.is_multiple_of(4) {
                            vi.set(i, false);
                        }
                        (r % 5) as i64 - 2 // -2..2 incl 0
                    })
                    .collect();
                Column::from_i64_values_with_validity(data, vi)
            };
            let h0s = [0.5f64, 0.0, 1.0, f64::NAN];
            let exps = [0i32, 3, -2, 10];
            for trial in 0..300 {
                let n = (next() % 200) as usize;
                let col = if trial % 2 == 0 {
                    mk_f64(n, &mut next)
                } else {
                    mk_i64(n, &mut next)
                };
                let vals = col.values().to_vec();
                let h0 = h0s[trial % h0s.len()];
                let exp = exps[trial % exps.len()];
                let hv = col.heaviside(h0).unwrap();
                let want_h = ref_heaviside(&vals, h0);
                let lv = col.ldexp(exp).unwrap();
                let want_l = ref_ldexp(&vals, exp);
                for (name, got, want) in [("heaviside", &hv, &want_h), ("ldexp", &lv, &want_l)] {
                    let gv = got.values();
                    let wv = want.values();
                    assert_eq!(gv.len(), wv.len(), "{name} len trial {trial}");
                    for (k, (g, w)) in gv.iter().zip(wv.iter()).enumerate() {
                        assert!(bit_eq(g, w), "{name} trial {trial} idx {k}: {g:?} != {w:?}");
                    }
                }
            }
        }

        #[test]
        fn shift_i64_both_present_nullable_match_scalar_reference() {
            // left_shift/right_shift now route Int64 input through
            // typed_i64_both_present_binary. Must be BIT-EXACT to the generic Scalar
            // loop (both-present ⇒ Int64(x <</>> clamp(y,0,63)), else Null(Null)).
            // Covers shift counts >63 and <0 (clamped), negative x (arithmetic >>), gaps.
            let mut state: u64 = 0x5417_C0DE_1234_9E37;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            let bit_eq = |a: &Scalar, b: &Scalar| -> bool {
                match (a, b) {
                    (Scalar::Int64(x), Scalar::Int64(y)) => x == y,
                    (Scalar::Null(_), Scalar::Null(_)) => true,
                    _ => false,
                }
            };
            fn ref_binop(a: &[Scalar], b: &[Scalar], f: fn(i64, i64) -> i64) -> Column {
                let out: Vec<Scalar> = a
                    .iter()
                    .zip(b.iter())
                    .map(|(x, y)| {
                        if x.is_missing() || y.is_missing() {
                            Scalar::Null(NullKind::Null)
                        } else {
                            match (x, y) {
                                (Scalar::Int64(xi), Scalar::Int64(yi)) => {
                                    Scalar::Int64(f(*xi, *yi))
                                }
                                _ => unreachable!(),
                            }
                        }
                    })
                    .collect();
                Column::new(DType::Int64, out).unwrap()
            }
            // Values column: full-range i64 incl negatives. Shift-count column: incl
            // out-of-range (>63) and negative (clamp to 0).
            let mk_vals = |n: usize, next: &mut dyn FnMut() -> u64| -> Column {
                let mut vi = crate::ValidityMask::all_valid(n);
                let data: Vec<i64> = (0..n)
                    .map(|i| {
                        let r = next();
                        if r.is_multiple_of(4) {
                            vi.set(i, false);
                        }
                        r as i64
                    })
                    .collect();
                Column::from_i64_values_with_validity(data, vi)
            };
            let mk_shifts = |n: usize, next: &mut dyn FnMut() -> u64| -> Column {
                let mut vi = crate::ValidityMask::all_valid(n);
                let data: Vec<i64> = (0..n)
                    .map(|i| {
                        let r = next();
                        if r.is_multiple_of(5) {
                            vi.set(i, false);
                        }
                        (r % 140) as i64 - 10 // range [-10, 129] ⇒ exercises clamp both ends
                    })
                    .collect();
                Column::from_i64_values_with_validity(data, vi)
            };
            for trial in 0..300 {
                let n = (next() % 200) as usize;
                let a = mk_vals(n, &mut next);
                let b = mk_shifts(n, &mut next);
                let av = a.values().to_vec();
                let bv = b.values().to_vec();
                let cases: [(&str, Column, Column); 2] = [
                    (
                        "shl",
                        a.left_shift(&b).unwrap(),
                        ref_binop(&av, &bv, |x, y| x.wrapping_shl(y.clamp(0, 63) as u32)),
                    ),
                    (
                        "shr",
                        a.right_shift(&b).unwrap(),
                        ref_binop(&av, &bv, |x, y| x.wrapping_shr(y.clamp(0, 63) as u32)),
                    ),
                ];
                for (name, got, want) in cases {
                    let gv = got.values();
                    let wv = want.values();
                    assert_eq!(gv.len(), wv.len(), "{name} len trial {trial}");
                    for (k, (g, w)) in gv.iter().zip(wv.iter()).enumerate() {
                        assert!(bit_eq(g, w), "{name} trial {trial} idx {k}: {g:?} != {w:?}");
                    }
                }
            }
        }

