        #[test]
        fn mode_f64_open_addressing_matches_reference() {
            use std::collections::HashMap;
            // Signed-zero: -0.0 first → mode keeps -0.0 representation.
            let col = Column::from_f64_values(vec![-0.0, 1.0, 0.0, 1.0, 0.0]);
            let m = col.mode().expect("mode");
            let got: Vec<f64> = m
                .values()
                .iter()
                .map(|v| match v {
                    Scalar::Float64(x) => *x,
                    o => panic!("{o:?}"),
                })
                .collect();
            // 0-class count 3 (>1's count 2) → single winner, the first-seen -0.0.
            assert_eq!(got.len(), 1);
            assert!(got[0] == 0.0 && got[0].is_sign_negative());

            let mut state: u64 = 0x7777_3333_CCCC_1111;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            for _ in 0..150 {
                let n = (next() % 400) as usize + 1;
                let data: Vec<f64> = (0..n)
                    .map(|_| match next() % 6 {
                        0 => -0.0,
                        1 => 0.0,
                        2 => 2.0,
                        3 => -3.5,
                        4 => f64::INFINITY,
                        _ => (next() % 30) as f64,
                    })
                    .collect();
                let mut counts: HashMap<u64, (u64, f64)> = HashMap::new();
                for &f in &data {
                    let kb = (if f == 0.0 { 0.0 } else { f }).to_bits();
                    counts.entry(kb).and_modify(|e| e.0 += 1).or_insert((1, f));
                }
                let max_c = counts.values().map(|(c, _)| *c).max().unwrap();
                let mut expected: Vec<f64> = counts
                    .values()
                    .filter_map(|&(c, f)| (c == max_c).then_some(f))
                    .collect();
                expected.sort_by(|a, b| a.total_cmp(b));
                let col = Column::from_f64_values(data);
                let got: Vec<f64> = col
                    .mode()
                    .expect("mode")
                    .values()
                    .iter()
                    .map(|v| match v {
                        Scalar::Float64(x) => *x,
                        o => panic!("{o:?}"),
                    })
                    .collect();
                assert_eq!(
                    got.iter().map(|x| x.to_bits()).collect::<Vec<_>>(),
                    expected.iter().map(|x| x.to_bits()).collect::<Vec<_>>()
                );
            }
        }

        #[test]
        fn mode_f64_growable_fibonacci_float_of_integer_matches_reference() {
            // Regression for the mode_f64_wide fix: float-of-integer keys span many
            // exponents (their variation is in the HIGH to_bits() bits), which the
            // old low-bit `& mask` hash collapsed into per-exponent buckets (probe
            // chains), and n large enough (> 1024 distinct) forces the growable
            // table to rehash. Winners must stay bit-identical to a HashMap
            // reference. Engineered ties: every value duplicated, one boosted.
            use std::collections::HashMap;
            let mut state: u64 = 0x0F1E_2D3C_4B5A_6978;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            for trial in 0..40 {
                // ~2500 distinct integer values as f64 (exponents 2^0..2^11), each
                // appearing several times, over ~12k rows ⇒ multiple table grows.
                let distinct = 2000 + (next() % 800) as i64;
                let n = 12_000usize;
                let boosted = (next() % distinct as u64) as i64;
                let data: Vec<f64> = (0..n)
                    .map(|i| {
                        // Bias toward `boosted` so there is a clear unique winner.
                        let v = if i % 9 == 0 {
                            boosted
                        } else {
                            (next() % distinct as u64) as i64
                        };
                        v as f64
                    })
                    .collect();
                let mut counts: HashMap<u64, (u64, f64)> = HashMap::new();
                for &f in &data {
                    let kb = (if f == 0.0 { 0.0 } else { f }).to_bits();
                    counts.entry(kb).and_modify(|e| e.0 += 1).or_insert((1, f));
                }
                let max_c = counts.values().map(|(c, _)| *c).max().unwrap();
                let mut expected: Vec<f64> = counts
                    .values()
                    .filter_map(|&(c, f)| (c == max_c).then_some(f))
                    .collect();
                expected.sort_by(|a, b| a.total_cmp(b));
                let col = Column::from_f64_values(data);
                let got: Vec<f64> = col
                    .mode()
                    .expect("mode")
                    .values()
                    .iter()
                    .map(|v| match v {
                        Scalar::Float64(x) => *x,
                        o => panic!("not float: {o:?}"),
                    })
                    .collect();
                assert_eq!(
                    got.iter().map(|x| x.to_bits()).collect::<Vec<_>>(),
                    expected.iter().map(|x| x.to_bits()).collect::<Vec<_>>(),
                    "trial {trial}"
                );
            }
        }

        #[test]
        fn mode_wide_i64_open_addressing_matches_reference() {
            // Wide/sparse all-valid Int64 uses mode_i64_wide (open-addressing
            // tally). Winners (max-count values, ascending) must equal a HashMap
            // reference across full-range data incl. i64::MIN, with engineered ties.
            use std::collections::HashMap;
            let pool: [i64; 6] = [
                i64::MIN,
                i64::MAX,
                4_000_000_000_000_000_000,
                -4_000_000_000_000_000_000,
                11,
                -11,
            ];
            let mut state: u64 = 0x9988_7766_5544_3322;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            for trial in 0..150 {
                let n = (next() % 400) as usize + 2;
                let mut data: Vec<i64> = (0..n)
                    .map(|_| pool[(next() as usize) % pool.len()])
                    .collect();
                data[0] = i64::MIN;
                data[1] = i64::MAX;
                assert!(
                    crate::i64_direct_address_range(&data).is_none(),
                    "trial {trial}: expected wide data"
                );
                let mut counts: HashMap<i64, u64> = HashMap::new();
                for &v in &data {
                    *counts.entry(v).or_insert(0) += 1;
                }
                let max_c = counts.values().copied().max().unwrap();
                let mut expected: Vec<i64> = counts
                    .iter()
                    .filter_map(|(&k, &c)| (c == max_c).then_some(k))
                    .collect();
                expected.sort_unstable();
                let col = Column::from_i64_values_owned(data);
                let got: Vec<i64> = col
                    .mode()
                    .expect("mode")
                    .values()
                    .iter()
                    .map(|v| match v {
                        Scalar::Int64(x) => *x,
                        o => panic!("not int: {o:?}"),
                    })
                    .collect();
                assert_eq!(got, expected, "trial {trial}");
            }
        }

        #[test]
        fn mode_wide_i64_growable_fibonacci_rehash_matches_reference() {
            // Regression for the mode_i64_wide fix: many distinct WIDE values
            // (> 1024 ⇒ multiple growable-table rehashes) that vary only in HIGH
            // bits (k << 34, the case the old low-bit `& mask` hash clustered),
            // plus the i64::MIN sentinel, with engineered ties. Winners must stay
            // bit-identical to a HashMap reference.
            use std::collections::HashMap;
            let mut state: u64 = 0x1234_5678_9ABC_DEF0;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            for trial in 0..40 {
                let distinct = 2000 + (next() % 800) as i64;
                let n = 12_000usize;
                let boosted = ((next() % distinct as u64) as i64) << 34;
                let data: Vec<i64> = (0..n)
                    .map(|i| {
                        if i % 400 == 0 {
                            i64::MIN // sentinel path
                        } else if i % 9 == 0 {
                            boosted // clear unique-winner bias
                        } else {
                            (((next() % distinct as u64) as i64) - distinct / 2) << 34
                        }
                    })
                    .collect();
                assert!(
                    crate::i64_direct_address_range(&data).is_none(),
                    "trial {trial}: expected wide data"
                );
                let mut counts: HashMap<i64, u64> = HashMap::new();
                for &v in &data {
                    *counts.entry(v).or_insert(0) += 1;
                }
                let max_c = counts.values().copied().max().unwrap();
                let mut expected: Vec<i64> = counts
                    .iter()
                    .filter_map(|(&k, &c)| (c == max_c).then_some(k))
                    .collect();
                expected.sort_unstable();
                let col = Column::from_i64_values_owned(data);
                let got: Vec<i64> = col
                    .mode()
                    .expect("mode")
                    .values()
                    .iter()
                    .map(|v| match v {
                        Scalar::Int64(x) => *x,
                        o => panic!("not int: {o:?}"),
                    })
                    .collect();
                assert_eq!(got, expected, "trial {trial}");
            }
        }

        #[test]
        fn mode_nullable_i64_f64_matches_present_reference() {
            // mode on a nullable Int64/Float64 column now tallies the PRESENT subset
            // via the dense/wide typed helpers instead of the generic Scalar+Key
            // HashMap. Winners (max-count present values, ascending) must equal a
            // HashMap reference over the present values. Narrow ranges force ties;
            // ~25% missing; no -0.0 so normalized bits == value (first-seen moot).
            use std::collections::HashMap;
            let mut state: u64 = 0xB0DE_1234_ABCD_9AB0;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            for trial in 0..200 {
                let len = (next() % 300) as usize + 1;
                let mut vi = crate::ValidityMask::all_valid(len);
                let mut vf = crate::ValidityMask::all_valid(len);
                let idata: Vec<i64> = (0..len)
                    .map(|i| {
                        let r = next();
                        if r % 4 == 0 {
                            vi.set(i, false);
                        }
                        (r % 7) as i64 - 3
                    })
                    .collect();
                let fdata: Vec<f64> = (0..len)
                    .map(|i| {
                        let r = next();
                        if r % 4 == 0 {
                            vf.set(i, false);
                            0.0
                        } else {
                            (r % 7) as f64 - 3.0
                        }
                    })
                    .collect();
                // Int64 reference over present.
                let mut ic: HashMap<i64, u64> = HashMap::new();
                for (i, &v) in idata.iter().enumerate() {
                    if vi.get(i) {
                        *ic.entry(v).or_insert(0) += 1;
                    }
                }
                let mut iwant: Vec<i64> = if ic.is_empty() {
                    Vec::new()
                } else {
                    let m = ic.values().copied().max().unwrap();
                    ic.iter()
                        .filter_map(|(&k, &c)| (c == m).then_some(k))
                        .collect()
                };
                iwant.sort_unstable();
                // Float64 reference over present (by bits; no -0.0 in data).
                let mut fc: HashMap<u64, u64> = HashMap::new();
                for (i, &f) in fdata.iter().enumerate() {
                    if vf.get(i) && !f.is_nan() {
                        *fc.entry(f.to_bits()).or_insert(0) += 1;
                    }
                }
                let mut fwant: Vec<f64> = if fc.is_empty() {
                    Vec::new()
                } else {
                    let m = fc.values().copied().max().unwrap();
                    fc.iter()
                        .filter_map(|(&k, &c)| (c == m).then_some(f64::from_bits(k)))
                        .collect()
                };
                fwant.sort_by(|a, b| a.partial_cmp(b).unwrap());

                let icol = Column::from_i64_values_with_validity(idata, vi);
                let fcol = Column::from_f64_values_with_validity(fdata, vf);
                let igot: Vec<i64> = icol
                    .mode()
                    .expect("mode")
                    .values()
                    .iter()
                    .map(|v| match v {
                        Scalar::Int64(x) => *x,
                        o => panic!("not int: {o:?}"),
                    })
                    .collect();
                let fgot: Vec<f64> = fcol
                    .mode()
                    .expect("mode")
                    .values()
                    .iter()
                    .map(|v| match v {
                        Scalar::Float64(x) => *x,
                        o => panic!("not float: {o:?}"),
                    })
                    .collect();
                assert_eq!(igot, iwant, "i64 trial {trial}");
                assert_eq!(fgot, fwant, "f64 trial {trial}");
            }
        }

