        #[test]
        fn interpolate_typed_f64_backing_matches_expected() {
            // Drives the typed path explicitly (from_f64_values_with_validity →
            // LazyNullableFloat64, which as_f64_slice_with_validity recognizes).
            // Leading null stays null; interior gap linearly filled; trailing
            // forward-fills the last valid value.
            let mut vmask = ValidityMask::all_valid(7);
            for j in [0usize, 2, 3, 6] {
                vmask.set(j, false);
            }
            // values: [_, 10, _, _, 40, 50, _]  (underscores invalid)
            let data = vec![0.0, 10.0, 0.0, 0.0, 40.0, 50.0, 0.0];
            let col = Column::from_f64_values_with_validity(data, vmask);
            let r = col.interpolate_linear().expect("interp");
            let v = r.values();
            assert!(v[0].is_missing(), "leading null stays null: {:?}", v[0]);
            assert_eq!(v[1], Scalar::Float64(10.0));
            // gap between 10 (idx1) and 40 (idx4): span=3 → 20, 30
            assert_eq!(v[2], Scalar::Float64(20.0));
            assert_eq!(v[3], Scalar::Float64(30.0));
            assert_eq!(v[4], Scalar::Float64(40.0));
            assert_eq!(v[5], Scalar::Float64(50.0));
            // trailing forward-fill of last valid (50)
            assert_eq!(v[6], Scalar::Float64(50.0));
        }

        #[test]
        fn interpolate_fills_interior_gaps() {
            let col = Column::from_values(vec![
                Scalar::Float64(1.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(4.0),
            ])
            .expect("col");
            let r = col.interpolate_linear().expect("interpolate");
            assert_eq!(r.values()[0], Scalar::Float64(1.0));
            assert!(
                matches!(&r.values()[1], Scalar::Float64(v) if (*v - 2.0).abs() < 1e-9),
                "expected Float64, got {:?}",
                r.values()[1]
            );
            assert!(
                matches!(&r.values()[2], Scalar::Float64(v) if (*v - 3.0).abs() < 1e-9),
                "expected Float64, got {:?}",
                r.values()[2]
            );
            assert_eq!(r.values()[3], Scalar::Float64(4.0));
        }

        #[test]
        fn interpolate_leading_null_stays_null_trailing_forward_fills() {
            // pandas Series.interpolate(method='linear') default
            // limit_direction='forward': leading NaN stays NaN, interior is
            // interpolated, trailing NaN is forward-filled with the last valid
            // value (NOT extrapolated). [nan,2,nan,4,nan] -> [nan,2,3,4,4].
            // (br-frankenpandas-8ic7c)
            let col = Column::from_values(vec![
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(2.0),
                Scalar::Null(NullKind::NaN),
                Scalar::Float64(4.0),
                Scalar::Null(NullKind::NaN),
            ])
            .expect("col");
            let r = col.interpolate_linear().expect("interpolate");
            assert!(r.values()[0].is_missing());
            assert_eq!(r.values()[1], Scalar::Float64(2.0));
            assert!(
                matches!(&r.values()[2], Scalar::Float64(v) if (*v - 3.0).abs() < 1e-9),
                "expected Float64, got {:?}",
                r.values()[2]
            );
            assert_eq!(r.values()[3], Scalar::Float64(4.0));
            // Trailing NaN forward-filled with the last valid value (4.0).
            assert_eq!(r.values()[4], Scalar::Float64(4.0));
        }

