        #[test]
        fn nunique_wide_i64_open_addressing_matches_reference() {
            // The wide/sparse all-valid Int64 path uses count_distinct_i64_wide
            // (open-addressing set). Must equal a HashSet reference across random
            // wide data AND the i64::MIN empty-sentinel edge.
            use std::collections::HashSet;
            // Deterministic LCG, sparse full-range values + forced duplicates +
            // both i64::MIN and i64::MAX present.
            let mut state: u64 = 0xDEAD_BEEF_1234_5678;
            let mut data: Vec<i64> = Vec::with_capacity(20_000);
            for _ in 0..10_000 {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                let v = (state >> 1) as i64;
                data.push(v);
                data.push(v); // duplicate every value
            }
            data.push(i64::MIN);
            data.push(i64::MIN); // sentinel value, duplicated
            data.push(i64::MAX);
            let expected = data.iter().copied().collect::<HashSet<i64>>().len() as i64;
            let col = Column::from_i64_values_owned(data);
            assert!(
                col.as_i64_slice().is_some(),
                "from_i64_values must expose a typed slice so the wide path runs"
            );
            assert_eq!(col.nunique(), Scalar::Int64(expected));
            assert_eq!(col.nunique_with_dropna(false), Scalar::Int64(expected));
        }

        #[test]
        fn count_distinct_radix_high_bit_shifted_keys_matches_reference() {
            // Regression for the count_distinct_i64_radix per-partition hash fix:
            // HIGH-bit-only-varying keys (k << 34) whose hashv has ZERO low bits —
            // the old `hashv & mask` collapsed each partition to one bucket. The
            // radix count must equal a HashSet reference AND the single-table count,
            // across shifts that (do/don't) zero the low bits, plus i64::MIN.
            use std::collections::HashSet;
            let mut state: u64 = 0xF00D_CAFE_1357_2468;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            for &sh in &[34u32, 40, 20, 0] {
                for trial in 0..15 {
                    let n = 6000 + (next() % 4000) as usize;
                    let distinct = 800 + (next() % 3000) as i64;
                    let mut data: Vec<i64> = (0..n)
                        .map(|i| {
                            if i % 700 == 0 {
                                i64::MIN
                            } else {
                                (((next() % distinct as u64) as i64) - distinct / 2) << sh
                            }
                        })
                        .collect();
                    data.push(i64::MIN);
                    let want = data.iter().copied().collect::<HashSet<i64>>().len() as i64;
                    assert_eq!(
                        crate::count_distinct_i64_radix(&data),
                        want,
                        "radix sh={sh} trial {trial}"
                    );
                    assert_eq!(
                        crate::count_distinct_i64_singletable(&data),
                        want,
                        "singletable sh={sh} trial {trial}"
                    );
                }
            }
        }

