        #[test]
        fn nunique_nullable_bool_typed_matches_scalar_oracle() {
            let mut state = 0xB001_5EED_1234_5678_u64;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            for trial in 0..200 {
                let n = (next() % 400) as usize;
                let null_mode = next() % 3;
                let mut data = Vec::with_capacity(n);
                let mut validity = ValidityMask::all_valid(n);
                let mut scalar_oracle = Vec::with_capacity(n);
                for i in 0..n {
                    let value = next() & 1 == 1;
                    let missing = match null_mode {
                        0 => false,
                        2 => true,
                        _ => next().is_multiple_of(4),
                    };
                    data.push(value);
                    if missing {
                        validity.set(i, false);
                        scalar_oracle.push(Scalar::Null(NullKind::Null));
                    } else {
                        scalar_oracle.push(Scalar::Bool(value));
                    }
                }
                let column = Column::from_bool_values_with_validity(data, validity);
                for dropna in [true, false] {
                    let mut expected = match fp_types::nannunique(&scalar_oracle) {
                        Scalar::Int64(count) => count,
                        _ => unreachable!("nannunique count must be Int64"),
                    };
                    if !dropna && scalar_oracle.iter().any(Scalar::is_missing) {
                        expected += 1;
                    }
                    assert_eq!(
                        column.nunique_with_dropna(dropna),
                        Scalar::Int64(expected),
                        "trial={trial} null_mode={null_mode} dropna={dropna}"
                    );
                }
            }
        }

        #[test]
        fn nunique_nullable_utf8_typed_matches_generic() {
            // The typed nullable-Utf8 nunique arm (cold cache) must be BIT-EXACT to the
            // generic nannunique path for BOTH dropna values. A/B on identical
            // LazyNullableUtf8 data: `col_cold` (fresh, cold cache) exercises the typed
            // arm; `col_warm` has its Scalar cache pre-materialized so the cold-cache gate
            // defers it to the generic path. Seeded short strings over {a,b,c,d} + ~25%
            // nulls; some trials fully-null (distinct present = 0), some no-null.
            let mut state: u64 = 0x4E17_C0DE_1234_9E37;
            let mut next = || {
                state = state
                    .wrapping_mul(6364136223846793005)
                    .wrapping_add(1442695040888963407);
                state
            };
            for trial in 0..120 {
                let n = (next() % 300) as usize;
                // Vary null density per trial: 0 (none), 1 (~25%), 2 (all-null).
                let null_mode = next() % 3;
                let mut validity = crate::ValidityMask::all_valid(n);
                let mut bytes: Vec<u8> = Vec::new();
                let mut offsets: Vec<usize> = vec![0];
                for i in 0..n {
                    let is_null = match null_mode {
                        0 => false,
                        2 => true,
                        _ => next() % 4 == 0,
                    };
                    if is_null {
                        validity.set(i, false);
                    } else {
                        let len = (next() % 5) as usize;
                        let s: String = (0..len)
                            .map(|_| (b'a' + (next() % 4) as u8) as char)
                            .collect();
                        bytes.extend_from_slice(s.as_bytes());
                    }
                    offsets.push(bytes.len());
                }
                let col_cold = Column::from_utf8_values_with_validity(
                    bytes.clone(),
                    offsets.clone(),
                    validity.clone(),
                );
                let col_warm = Column::from_utf8_values_with_validity(bytes, offsets, validity);
                let _ = col_warm.values(); // warm cache ⇒ generic path (oracle)
                for dropna in [true, false] {
                    assert_eq!(
                        col_cold.nunique_with_dropna(dropna),
                        col_warm.nunique_with_dropna(dropna),
                        "trial {trial} null_mode={null_mode} dropna={dropna}"
                    );
                }
            }
        }

