/// Provenanced A/B for the `LazyAllValidFloat64TransposeRow` arm of
/// [`Column::as_f64_slice`] (cc_fp).
///
/// Isolated at the `Column` level so the transpose frame's `String` + `BTreeMap`
/// construction cannot dominate the signal: each rep rebuilds the transposed row
/// columns from scratch (their `OnceLock`s start cold), then walks them once.
///
/// ORIG = `values()` -> `plan.materialize_row` + `Vec<Scalar>` boxing (32 B/elem).
/// CAND = `as_f64_slice()` -> `plan.materialize_row` only, returning the cached
/// typed `Vec<f64>` (8 B/elem) that `values()` was about to box.
///
/// Both arms alternate INSIDE one measured routine, in ONE `rch exec` invocation,
/// with `black_box` on inputs and results. Emits binary sha256, worker hostname and
/// per-arm cv_pct so the ledger row is provenanced.
///
/// Run: `RCH_REQUIRE_REMOTE=1 env -u CARGO_TARGET_DIR rch exec -- \
///        cargo test -p fp-columnar --release --lib -- --ignored --nocapture ab_transpose_row_typed`
#[cfg(test)]
mod ab_transpose_row_typed_ccfp {
    use std::{process::Command, sync::Arc, time::Instant};

    use fp_types::Scalar;

    use super::{Column, Float64TransposeInput, Float64TransposeRows, Float64TransposeRowsPlan};

    fn binary_sha256() -> String {
        let exe = std::env::current_exe().expect("current test binary");
        let out = Command::new("sha256sum")
            .arg(&exe)
            .output()
            .expect("sha256sum on worker");
        String::from_utf8(out.stdout)
            .expect("utf8")
            .split_whitespace()
            .next()
            .expect("digest")
            .to_owned()
    }

    fn worker_hostname() -> String {
        Command::new("hostname")
            .output()
            .ok()
            .and_then(|o| String::from_utf8(o.stdout).ok())
            .map_or_else(|| "unknown".to_owned(), |s| s.trim().to_owned())
    }

    /// `rows` source rows x `cols` source columns; each transposed row column has
    /// length `cols`, and there are `rows` of them -- the shape `df.transpose()` emits.
    fn plan_for(rows: usize, cols: usize) -> Float64TransposeRows {
        let inputs: Vec<Float64TransposeInput> = (0..cols)
            .map(|c| {
                let data: Arc<[f64]> = (0..rows)
                    .map(|r| (r * cols + c) as f64)
                    .collect::<Vec<_>>()
                    .into();
                Float64TransposeInput::new(data, 0, rows)
            })
            .collect();
        Float64TransposeRows {
            plan: Arc::new(Float64TransposeRowsPlan::new(inputs.into(), rows)),
        }
    }

    fn min_of(xs: &[f64]) -> f64 {
        xs.iter().copied().fold(f64::INFINITY, f64::min)
    }

    fn median_of(xs: &[f64]) -> f64 {
        let mut v = xs.to_vec();
        v.sort_by(|a, b| a.partial_cmp(b).expect("finite"));
        let n = v.len();
        if n % 2 == 1 {
            v[n / 2]
        } else {
            0.5 * (v[n / 2 - 1] + v[n / 2])
        }
    }

    fn spread_of(xs: &[f64]) -> (f64, f64) {
        let mut lo = f64::INFINITY;
        let mut hi = f64::NEG_INFINITY;
        for &x in xs {
            lo = lo.min(x);
            hi = hi.max(x);
        }
        (lo, hi)
    }

    fn cv_of(xs: &[f64]) -> f64 {
        let mean = xs.iter().sum::<f64>() / xs.len() as f64;
        let var = xs.iter().map(|x| (x - mean).powi(2)).sum::<f64>() / xs.len() as f64;
        100.0 * var.sqrt() / mean
    }

    /// Prices the ONLY pair-shrink lever available inside fp-columnar (cc_fp): the
    /// 93.6%-of-construction cost is owning + re-homing n 312-byte `(String, Column)`
    /// pairs, and `Column` is 288 B of that. Both of the obvious representation fixes
    /// -- borrowed/interned keys, or one columnar block instead of per-row Columns --
    /// change `DataFrame` (cod_fp's `fp-frame` lane; the block IS the lazy view).
    /// The one shrink that lives HERE is boxing the `Column` out of the pair, taking
    /// it 312 B -> 32 B of move-traffic at the cost of ONE heap alloc per row.
    ///
    /// This ablation answers, decidably, whether that trade wins: does moving 32-byte
    /// pairs (plus n allocs) beat moving 312-byte pairs? If yes, shrinking `Column`
    /// (box its wide `ScalarValues` variants) is worth a conformance-gated attempt;
    /// if no, the alloc eats the move and the only real lever is cod_fp's block view.
    /// Per-arm ADJACENT A/A null floor; decide on medians vs spread, not cv.
    /// Times a heavily-autovectorizable f64 sum (xmm 2-wide under SSE2, ymm 4-wide
    /// under AVX2) so the SAME source, built two ways, shows the ISA gap's cost.
    /// Prints the compiled-in avx2 flag + sha256 + worker so a baseline-vs-v3 pair
    /// pinned to ONE worker is a valid ratio. blocks x reps, min-of-block, spread.
    #[test]
    #[ignore = "diagnostic; run with --ignored --nocapture"]
    fn isa_sum_kernel_ccfp() {
        use std::process::Command;
        const N: usize = 20_000_000;
        const BLOCKS: usize = 11;
        const REPS: usize = 5;
        let data: Vec<f64> = (0..N).map(|i| (i as f64).mul_add(1.0000001, 0.5)).collect();

        let mut ms = Vec::with_capacity(BLOCKS);
        let mut nullr = Vec::with_capacity(BLOCKS);
        for _ in 0..BLOCKS {
            let (mut a, mut b) = (f64::INFINITY, f64::INFINITY);
            for _ in 0..REPS {
                let d = std::hint::black_box(&data[..]);
                let t0 = std::time::Instant::now();
                let s: f64 = d.iter().copied().sum();
                std::hint::black_box(s);
                a = a.min(t0.elapsed().as_secs_f64() * 1e3);
                let d = std::hint::black_box(&data[..]);
                let t0 = std::time::Instant::now();
                let s: f64 = d.iter().copied().sum();
                std::hint::black_box(s);
                b = b.min(t0.elapsed().as_secs_f64() * 1e3);
            }
            ms.push(a.min(b));
            nullr.push(a / b);
        }
        let med = median_of(&ms);
        let (lo, hi) = spread_of(&nullr);
        let sha = Command::new("sha256sum")
            .arg(std::env::current_exe().expect("exe"))
            .output()
            .ok()
            .and_then(|o| String::from_utf8(o.stdout).ok())
            .and_then(|s| s.split_whitespace().next().map(str::to_owned))
            .unwrap_or_default();
        let host = Command::new("hostname")
            .output()
            .ok()
            .and_then(|o| String::from_utf8(o.stdout).ok())
            .map_or_else(|| "?".to_owned(), |s| s.trim().to_owned());
        println!("=== ISA SUM KERNEL ===");
        println!(
            "  compiled avx2 = {}  fma = {}",
            cfg!(target_feature = "avx2"),
            cfg!(target_feature = "fma")
        );
        println!("  binary_sha256 = {sha}");
        println!("  worker        = {host}");
        println!(
            "  N={N} sum(f64) median={med:.4} ms  cv={:.2}%  A/A null spread=[{lo:.4}x,{hi:.4}x]",
            cv_of(&ms)
        );
        println!("  throughput = {:.2} Gelem/s", N as f64 / (med / 1e3) / 1e9);
    }

    /// Same-binary, worker-invariant measurement of the Column-shrink benefit (cc_fp).
    /// The cross-binary pair-shrink ratio is worker-confounded (memory bandwidth
    /// differs per worker), so instead compare moving a struct of the CURRENT Column
    /// size vs the PRE-SHRINK size (288 B) through the exact `Vec` push + `BTreeMap`
    /// collect the transpose finalize uses, BOTH arms in ONE binary on ONE worker.
    /// Isolates the size effect. Per-arm ADJACENT A/A null floor; gate on median.
    #[test]
    #[ignore = "perf ablation; run with --ignored --nocapture"]
    fn ab_column_size_move_ccfp() {
        use std::collections::BTreeMap;
        const N: usize = 200_000;
        const BLOCKS: usize = 11;
        const REPS: usize = 5;
        // Current Column size vs the pre-boxing size (288 B), as opaque blocks so the
        // move cost is purely the byte count the BTreeMap re-homes.
        const CUR: usize = std::mem::size_of::<Column>();
        #[derive(Clone)]
        struct Blk<const B: usize>([u8; B]);
        let keys: Vec<String> = {
            let mut v: Vec<usize> = (0..N).collect();
            v.sort_by_key(|r| r.to_string());
            v.into_iter().map(|r| r.to_string()).collect()
        };
        // arm parameterized by block size; returns elapsed ms
        macro_rules! run {
            ($B:expr) => {{
                let mut v: Vec<(String, Blk<$B>)> = Vec::with_capacity(N);
                for k in &keys {
                    v.push((k.clone(), Blk::<$B>([0u8; $B])));
                }
                let m: BTreeMap<String, Blk<$B>> = v.into_iter().collect();
                std::hint::black_box(&m);
            }};
        }
        // Compile-time guard: the OLD(288) arm must stay >= the current Column.
        const _: () = assert!(CUR <= 288, "Column grew past the pre-shrink 288 B size");
        for _ in 0..2 {
            run!(232);
            run!(288);
        }
        let (mut cur, mut old, mut ncur) = (Vec::new(), Vec::new(), Vec::new());
        for _ in 0..BLOCKS {
            let (mut bc, mut bo) = (f64::INFINITY, f64::INFINITY);
            for _ in 0..REPS {
                // adjacent A/A for CUR(232): two back-to-back timings -> ratio = floor
                let t0 = Instant::now();
                run!(232);
                let a = t0.elapsed().as_secs_f64() * 1e3;
                let t0 = Instant::now();
                run!(232);
                let b = t0.elapsed().as_secs_f64() * 1e3;
                bc = bc.min(a.min(b));
                ncur.push(a / b);
                // OLD(288)
                let t0 = Instant::now();
                run!(288);
                let c = t0.elapsed().as_secs_f64() * 1e3;
                let t0 = Instant::now();
                run!(288);
                let d = t0.elapsed().as_secs_f64() * 1e3;
                bo = bo.min(c.min(d));
            }
            cur.push(bc);
            old.push(bo);
        }
        let (c, o) = (min_of(&cur), min_of(&old));
        let (nlo, nhi) = spread_of(&ncur);
        let floor = 100.0 * (nhi - 1.0).abs().max((nlo - 1.0).abs());
        println!("AB Column-size move (ONE binary, ONE invocation, blocks x reps)");
        println!("  binary_sha256 = {}", {
            use std::process::Command;
            Command::new("sha256sum")
                .arg(std::env::current_exe().unwrap())
                .output()
                .ok()
                .and_then(|o| String::from_utf8(o.stdout).ok())
                .and_then(|s| s.split_whitespace().next().map(str::to_owned))
                .unwrap_or_default()
        });
        println!("  worker={}  CUR sizeof Column={CUR} B", {
            use std::process::Command;
            Command::new("hostname")
                .output()
                .ok()
                .and_then(|o| String::from_utf8(o.stdout).ok())
                .map_or_else(|| "?".into(), |s| s.trim().to_owned())
        });
        println!("  CUR(232 B) median={c:.3} ms  cv={:.2}%", cv_of(&cur));
        println!("  OLD(288 B) median={o:.3} ms  cv={:.2}%", cv_of(&old));
        println!("  A/A null floor (CUR arm) median-spread=[{nlo:.4},{nhi:.4}]  |dev|={floor:.2}%");
        println!(
            "  shrink effect (OLD/CUR) = {:.4}x  ({:+.1}%)  DECIDABLE={}",
            o / c,
            100.0 * (o / c - 1.0),
            100.0 * (o / c - 1.0).abs() > floor
        );
    }

    /// Size breakdown of the widest ScalarValues variant (cc_fp): finds the single
    /// biggest field so a surgical box of ONE cold cache can shrink the 288-byte
    /// Column without the whole 47-variant epic.
    #[test]
    #[ignore = "diagnostic; run with --ignored --nocapture"]
    fn scalarvalues_size_breakdown_ccfp() {
        use std::sync::OnceLock;
        macro_rules! sz {
            ($t:ty) => {
                println!("  {:>4} B  {}", std::mem::size_of::<$t>(), stringify!($t));
            };
        }
        println!("=== ScalarValues size breakdown ===");
        sz!(super::ScalarValues);
        sz!(Column);
        println!("--- LazyContiguousUtf8 fields (the widest variant) ---");
        sz!(std::sync::Arc<[u8]>);
        sz!(OnceLock<bool>);
        sz!(OnceLock<Option<usize>>);
        sz!(OnceLock<Option<super::Utf8LowerHexSequence>>);
        sz!(super::Utf8FactorizeDefaultWitness);
        sz!(OnceLock<super::Utf8FactorizeDefaultWitness>);
        sz!(OnceLock<Box<super::Utf8FactorizeDefaultWitness>>);
        sz!(OnceLock<Vec<fp_types::Scalar>>);
        println!("--- sum if factorize_default were boxed ---");
        let cur = std::mem::size_of::<OnceLock<super::Utf8FactorizeDefaultWitness>>();
        let boxed = std::mem::size_of::<OnceLock<Box<super::Utf8FactorizeDefaultWitness>>>();
        println!(
            "  factorize_default field: {cur} B -> {boxed} B  (saves {} B)",
            cur - boxed
        );
        use fp_types::Scalar as Sc;
        println!("--- widest-variant field tuples (find the current enum max) ---");
        macro_rules! vt {
            ($n:literal, $t:ty) => {
                println!("  {:>4} B  {}", std::mem::size_of::<$t>(), $n);
            };
        }
        vt!(
            "LazyContiguousUtf8",
            (
                std::sync::Arc<[u8]>,
                std::sync::Arc<[usize]>,
                OnceLock<bool>,
                OnceLock<Option<usize>>,
                OnceLock<Option<Box<super::Utf8LowerHexSequence>>>,
                OnceLock<Box<super::Utf8FactorizeDefaultWitness>>,
                OnceLock<Vec<Sc>>,
            )
        );
        vt!(
            "LazyShiftedBool",
            (
                std::sync::Arc<[bool]>,
                i64,
                bool,
                usize,
                OnceLock<Vec<bool>>,
                OnceLock<Option<super::BoolAffineSelectionWitness>>,
                OnceLock<Vec<Sc>>,
            )
        );
        vt!(
            "LazyAllValidInt64Chunks",
            (
                std::sync::Arc<[u8]>,
                usize,
                OnceLock<Vec<i64>>,
                OnceLock<Option<super::Int64DenseCycleWitness>>,
                OnceLock<Vec<Sc>>,
            )
        );
        vt!(
            "OL<Option<BoolAffineSelectionWitness>>",
            OnceLock<Option<super::BoolAffineSelectionWitness>>
        );
        vt!(
            "OL<Option<Box<BoolAffineSelectionWitness>>>",
            OnceLock<Option<Box<super::BoolAffineSelectionWitness>>>
        );
        vt!(
            "OL<Option<Int64DenseCycleWitness>>",
            OnceLock<Option<super::Int64DenseCycleWitness>>
        );
        // The join dense-cycle lanes carry TWO INLINE 24 B witnesses (not OnceLock
        // caches -- always-present join data), so they tie the enum max at ~144 B.
        // This is the plateau: shrinking one variant is a no-op while these remain.
        vt!(
            "LazyLeftJoinDenseCycleLeftInt64",
            (
                std::sync::Arc<[i64]>,
                super::Int64DenseCycleWitness,
                super::Int64DenseCycleWitness,
                usize,
                OnceLock<Vec<i64>>,
                OnceLock<Vec<Sc>>,
            )
        );
    }

    /// ISA-baseline probe (cc_fp): prints what the CURRENT BINARY was COMPILED for
    /// (`cfg!(target_feature=...)`) vs what the RUNTIME worker CPU actually supports
    /// (`is_x86_feature_detected!`). A gap (compiled SSE2, worker AVX2) means a whole
    /// class of hot loops is leaving 256-bit width on the table. Both macros are safe.
    #[test]
    #[ignore = "diagnostic; run with --ignored --nocapture"]
    fn isa_baseline_probe_ccfp() {
        macro_rules! ct {
            ($f:literal) => {
                (cfg!(target_feature = $f), $f)
            };
        }
        let compiled = [
            ct!("sse2"),
            ct!("sse4.1"),
            ct!("avx"),
            ct!("avx2"),
            ct!("fma"),
            ct!("avx512f"),
        ];
        println!("=== ISA BASELINE PROBE ===");
        println!("arch = {}", std::env::consts::ARCH);
        println!("--- COMPILED (this binary's target-feature) ---");
        for (on, name) in compiled {
            println!("  {name:8} compiled_in={on}");
        }
        #[cfg(target_arch = "x86_64")]
        {
            println!("--- RUNTIME (worker CPU) ---");
            for name in ["sse2", "sse4.1", "avx", "avx2", "fma", "avx512f"] {
                let has = match name {
                    "sse2" => is_x86_feature_detected!("sse2"),
                    "sse4.1" => is_x86_feature_detected!("sse4.1"),
                    "avx" => is_x86_feature_detected!("avx"),
                    "avx2" => is_x86_feature_detected!("avx2"),
                    "fma" => is_x86_feature_detected!("fma"),
                    "avx512f" => is_x86_feature_detected!("avx512f"),
                    _ => false,
                };
                println!("  {name:8} runtime_has={has}");
            }
            let gap = !cfg!(target_feature = "avx2") && is_x86_feature_detected!("avx2");
            println!("--- VERDICT ---");
            println!("  AVX2 ISA GAP (compiled SSE2 baseline, worker has AVX2) = {gap}");
        }
    }

    #[test]
    #[ignore = "perf ablation; run with --ignored --nocapture"]
    fn ab_transpose_pair_shrink_ceiling() {
        use std::collections::BTreeMap;

        const ROWS: usize = 200_000;
        const COLS: usize = 10;
        const BLOCKS: usize = 9;
        const REPS: usize = 3;

        let handle = plan_for(ROWS, COLS);
        let mut order: Vec<usize> = (0..ROWS).collect();
        order.sort_by_key(|r| r.to_string());
        let order = order;

        // REAL: Vec<(String, Column)> -> BTreeMap<String, Column>  (312-byte pair)
        let arm_real = |ord: &[usize], h: &Float64TransposeRows| {
            let mut v: Vec<(String, Column)> = Vec::with_capacity(ord.len());
            for &r in ord {
                v.push((r.to_string(), Column::from_f64_transpose_row(h, r)));
            }
            let m: BTreeMap<String, Column> = v.into_iter().collect();
            std::hint::black_box(m);
        };
        // BOXED: Vec<(String, Box<Column>)> -> BTreeMap<String, Box<Column>>  (32-byte
        // pair + one heap alloc per row). Proxy for a 32-B-Column representation.
        let arm_boxed = |ord: &[usize], h: &Float64TransposeRows| {
            let mut v: Vec<(String, Box<Column>)> = Vec::with_capacity(ord.len());
            for &r in ord {
                v.push((
                    r.to_string(),
                    Box::new(Column::from_f64_transpose_row(h, r)),
                ));
            }
            let m: BTreeMap<String, Box<Column>> = v.into_iter().collect();
            std::hint::black_box(m);
        };

        for _ in 0..2 {
            let (o, h) = (std::hint::black_box(&order), std::hint::black_box(&handle));
            arm_real(o, h);
            arm_boxed(o, h);
        }

        let mut real = Vec::with_capacity(BLOCKS);
        let mut boxed = Vec::with_capacity(BLOCKS);
        let mut null_real = Vec::with_capacity(BLOCKS);
        let mut null_boxed = Vec::with_capacity(BLOCKS);
        for _ in 0..BLOCKS {
            let (mut br, mut bb) = (f64::INFINITY, f64::INFINITY);
            let (mut ra, mut rb, mut ba, mut bb2) =
                (f64::INFINITY, f64::INFINITY, f64::INFINITY, f64::INFINITY);
            for _ in 0..REPS {
                let (o, h) = (std::hint::black_box(&order), std::hint::black_box(&handle));

                // adjacent A/A for REAL
                let t0 = Instant::now();
                arm_real(o, h);
                let a = t0.elapsed().as_secs_f64() * 1e3;
                let t0 = Instant::now();
                arm_real(o, h);
                let b = t0.elapsed().as_secs_f64() * 1e3;
                ra = ra.min(a);
                rb = rb.min(b);
                br = br.min(a.min(b));

                // adjacent A/A for BOXED
                let t0 = Instant::now();
                arm_boxed(o, h);
                let a = t0.elapsed().as_secs_f64() * 1e3;
                let t0 = Instant::now();
                arm_boxed(o, h);
                let b = t0.elapsed().as_secs_f64() * 1e3;
                ba = ba.min(a);
                bb2 = bb2.min(b);
                bb = bb.min(a.min(b));
            }
            real.push(br);
            boxed.push(bb);
            null_real.push(ra / rb);
            null_boxed.push(ba / bb2);
        }

        let (rm, bm) = (median_of(&real), median_of(&boxed));
        let (nr, nb) = (median_of(&null_real), median_of(&null_boxed));
        let (rlo, rhi) = spread_of(&null_real);
        let (blo, bhi) = spread_of(&null_boxed);
        let floor_real = 100.0 * (rhi - 1.0).abs().max((rlo - 1.0).abs());
        let floor_boxed = 100.0 * (bhi - 1.0).abs().max((blo - 1.0).abs());
        let effect = 100.0 * (rm / bm - 1.0);
        println!("AB transpose pair-shrink ceiling (ONE binary, ONE invocation)");
        println!("  binary_sha256 = {}", binary_sha256());
        println!("  worker        = {}", worker_hostname());
        println!(
            "  size_of (String,Column)={}  (String,Box<Column>)={}",
            std::mem::size_of::<(String, Column)>(),
            std::mem::size_of::<(String, Box<Column>)>()
        );
        println!(
            "  REAL  (String,Column)      median={rm:9.3} ms  cv={:5.2}%  A/A null median={nr:.4}x floor={floor_real:.2}%",
            cv_of(&real)
        );
        println!(
            "  BOXED (String,Box<Column>) median={bm:9.3} ms  cv={:5.2}%  A/A null median={nb:.4}x floor={floor_boxed:.2}%",
            cv_of(&boxed)
        );
        println!("  effect (real/boxed) = {:.4}x  ({effect:+.1}%)", rm / bm);
        let decidable = effect.abs() > floor_real.max(floor_boxed);
        println!(
            "  DECIDABLE: |effect|={:.1}% vs max floor={:.1}% -> {}",
            effect.abs(),
            floor_real.max(floor_boxed),
            decidable
        );
    }

    /// Decomposes the 95.9% of transpose CONSTRUCTION that does NOT live in the
    /// per-column ctor (cc_fp). `DataFrame::transpose` finalizes by, per source row:
    /// formatting a decimal `String` label, constructing a `Column`, pushing the pair
    /// into a `Vec<(String, Column)>` in lexical key order, then `collect()`ing that
    /// into `BTreeMap<String, Column>`. Only `Column` is fp-columnar; `String`, `Vec`
    /// and `BTreeMap` are std, so the whole shape is reproducible HERE, without
    /// touching `crates/fp-frame` (cod_fp's live file).
    ///
    /// Cumulative arms, so each delta attributes one component:
    ///   L    = label `String` only
    ///   LC   = label + `Column::from_f64_transpose_row`
    ///   LCV  = label + ctor + push into `Vec<(String, Column)>`
    ///   MAP  = LCV + `BTreeMap::from_iter` (the sort + bulk build)
    ///   NULL = MAP again, identical arm -> the A/A floor, measured FIRST in each rep.
    ///
    /// Keys are pre-sorted into lexical order outside the timer, matching
    /// `push_lexical_transpose_row_entry`. Drops happen outside the timer, matching how
    /// `ab_transpose_materialize`'s construction arm was measured.
    #[test]
    #[ignore = "perf ablation; run with --ignored --nocapture"]
    fn ab_transpose_construction_decomposition() {
        use std::collections::BTreeMap;

        const ROWS: usize = 200_000;
        const COLS: usize = 10;
        const BLOCKS: usize = 9;
        const REPS: usize = 3;

        let handle = plan_for(ROWS, COLS);
        // Lexical key order, exactly as push_lexical_transpose_row_entry emits.
        let mut order: Vec<usize> = (0..ROWS).collect();
        order.sort_by_key(|r| r.to_string());
        let order = order;

        let arm_l = |ord: &[usize]| {
            let mut n = 0usize;
            for &r in ord {
                n += std::hint::black_box(r.to_string()).len();
            }
            n
        };
        let arm_lc = |ord: &[usize], h: &Float64TransposeRows| {
            let mut n = 0usize;
            for &r in ord {
                let k = std::hint::black_box(r.to_string());
                let c = Column::from_f64_transpose_row(h, r);
                n += k.len() + std::hint::black_box(&c).len();
            }
            n
        };
        let arm_lcv = |ord: &[usize], h: &Float64TransposeRows| {
            let mut v: Vec<(String, Column)> = Vec::with_capacity(ord.len());
            for &r in ord {
                v.push((r.to_string(), Column::from_f64_transpose_row(h, r)));
            }
            std::hint::black_box(v)
        };
        let arm_map = |ord: &[usize], h: &Float64TransposeRows| {
            let mut v: Vec<(String, Column)> = Vec::with_capacity(ord.len());
            for &r in ord {
                v.push((r.to_string(), Column::from_f64_transpose_row(h, r)));
            }
            let m: BTreeMap<String, Column> = v.into_iter().collect();
            std::hint::black_box(m)
        };

        for _ in 0..2 {
            let (o, h) = (std::hint::black_box(&order), std::hint::black_box(&handle));
            std::hint::black_box(arm_l(o));
            std::hint::black_box(arm_lc(o, h));
            drop(arm_lcv(o, h));
            drop(arm_map(o, h));
        }

        // PER-ARM A/A NULL CONTROL. The null floor is per-FUNCTION, not global
        // (frankenlibc), so every arm is run twice per block and its own a/b ratio
        // calibrates its own floor. Decisions are made on MEDIANS against the null's
        // observed SPREAD, not on a cv threshold (frankenmermaid harness calibration).
        // cv is still reported, as information.
        let mut t: [Vec<f64>; 4] = [
            Vec::with_capacity(BLOCKS),
            Vec::with_capacity(BLOCKS),
            Vec::with_capacity(BLOCKS),
            Vec::with_capacity(BLOCKS),
        ];
        let mut nullr: [Vec<f64>; 4] = [
            Vec::with_capacity(BLOCKS),
            Vec::with_capacity(BLOCKS),
            Vec::with_capacity(BLOCKS),
            Vec::with_capacity(BLOCKS),
        ];
        for _ in 0..BLOCKS {
            let mut best = [f64::INFINITY; 4];
            let mut a_of = [f64::INFINITY; 4];
            let mut b_of = [f64::INFINITY; 4];
            for _ in 0..REPS {
                let (o, h) = (std::hint::black_box(&order), std::hint::black_box(&handle));

                // A/A pairs must be ADJACENT: the previous layout separated each
                // arm's a and b by ~50 ms of the other arms, so inter-arm drift, not
                // the function, set the floor (L read |dev| 61%). Run each arm's two
                // passes back-to-back, then move to the next arm.
                macro_rules! pair {
                    ($idx:expr, $run:expr) => {{
                        let t0 = Instant::now();
                        $run;
                        let a = t0.elapsed().as_secs_f64() * 1e3;
                        let t0 = Instant::now();
                        $run;
                        let b = t0.elapsed().as_secs_f64() * 1e3;
                        a_of[$idx] = a_of[$idx].min(a);
                        b_of[$idx] = b_of[$idx].min(b);
                        best[$idx] = best[$idx].min(a.min(b));
                    }};
                }

                pair!(0, std::hint::black_box(arm_l(o)));
                pair!(1, std::hint::black_box(arm_lc(o, h)));
                pair!(2, drop(arm_lcv(o, h)));
                pair!(3, drop(arm_map(o, h)));
            }
            for i in 0..4 {
                t[i].push(best[i]);
                nullr[i].push(a_of[i] / b_of[i]);
            }
        }

        let names = [
            "L    label String",
            "LC   +Column ctor",
            "LCV  +Vec push",
            "MAP  full finalize",
        ];
        println!("AB transpose construction decomposition (ONE binary, ONE invocation)");
        println!("  binary_sha256 = {}", binary_sha256());
        println!("  worker        = {}", worker_hostname());
        println!("  rows={ROWS} cols={COLS} (lexical key order, drops outside timer)");
        println!(
            "  size_of: Column={} ScalarValues={} (String,Column)={} -> Vec bytes={:.1} MB",
            std::mem::size_of::<Column>(),
            std::mem::size_of::<super::ScalarValues>(),
            std::mem::size_of::<(String, Column)>(),
            (ROWS * std::mem::size_of::<(String, Column)>()) as f64 / 1e6
        );
        println!("  --- per-arm A/A NULL FLOOR (median and observed spread of a/b) ---");
        for i in 0..4 {
            let (lo, hi) = spread_of(&nullr[i]);
            println!(
                "  {:20} null median={:.4}x  spread=[{:.4}x, {:.4}x]  |dev|max={:.2}%   arm median={:8.3} ms  cv={:5.2}%",
                names[i],
                median_of(&nullr[i]),
                lo,
                hi,
                100.0 * (hi - 1.0).abs().max((lo - 1.0).abs()),
                median_of(&t[i]),
                cv_of(&t[i])
            );
        }
        let (l, c, v, m) = (
            median_of(&t[0]),
            median_of(&t[1]),
            median_of(&t[2]),
            median_of(&t[3]),
        );
        let per = |ms: f64| 1e6 * ms / ROWS as f64;
        println!("  --- attributed components (medians, per source row) ---");
        println!(
            "  label String      = {:8.3} ms ({:6.2} ns/row, {:5.1}% of MAP)",
            l,
            per(l),
            100.0 * l / m
        );
        println!(
            "  Column ctor       = {:8.3} ms ({:6.2} ns/row, {:5.1}% of MAP)",
            c - l,
            per(c - l),
            100.0 * (c - l) / m
        );
        println!(
            "  Vec<(S,C)> push   = {:8.3} ms ({:6.2} ns/row, {:5.1}% of MAP)",
            v - c,
            per(v - c),
            100.0 * (v - c) / m
        );
        println!(
            "  BTreeMap collect  = {:8.3} ms ({:6.2} ns/row, {:5.1}% of MAP)",
            m - v,
            per(m - v),
            100.0 * (m - v) / m
        );
        println!(
            "  DECIDABILITY: each component's share must exceed its arm's max null deviation above."
        );
    }

    /// Localizes the transpose CONSTRUCTION wall (cc_fp). `df.transpose()` construction
    /// = per-column `Column::from_f64_transpose_row` (fp-columnar) + the `String` label,
    /// the `(String, Column)` stable sort, and the `BTreeMap` bulk build (fp-frame).
    /// This prices ONLY the fp-columnar half, so the remainder is attributable to
    /// fp-frame. Null control included: the identical arm registered twice.
    #[test]
    #[ignore = "perf ablation; run with --ignored --nocapture"]
    fn ab_transpose_row_ctor_share() {
        // First run gave cv 6.06%/9.05% on a 2.87 ms arm -- above the gate, so the
        // arm was lengthened rather than the number harvested. Null control was
        // already tight (0.9979x), so the harness was sound; only the arm was short.
        const ROWS: usize = 500_000;
        const COLS: usize = 10;
        const BLOCKS: usize = 11;
        const REPS: usize = 9;

        let handle = plan_for(ROWS, COLS);
        for _ in 0..2 {
            let h = std::hint::black_box(&handle);
            for r in 0..ROWS {
                std::hint::black_box(Column::from_f64_transpose_row(h, std::hint::black_box(r)));
            }
        }

        let mut ctor = Vec::with_capacity(BLOCKS);
        let mut null = Vec::with_capacity(BLOCKS);
        for _ in 0..BLOCKS {
            let (mut bc, mut bn) = (f64::INFINITY, f64::INFINITY);
            for _ in 0..REPS {
                let h = std::hint::black_box(&handle);

                let t0 = Instant::now();
                for r in 0..ROWS {
                    std::hint::black_box(Column::from_f64_transpose_row(
                        h,
                        std::hint::black_box(r),
                    ));
                }
                bc = bc.min(t0.elapsed().as_secs_f64() * 1e3);

                // identical arm: the null control
                let t0 = Instant::now();
                for r in 0..ROWS {
                    std::hint::black_box(Column::from_f64_transpose_row(
                        h,
                        std::hint::black_box(r),
                    ));
                }
                bn = bn.min(t0.elapsed().as_secs_f64() * 1e3);
            }
            ctor.push(bc);
            null.push(bn);
        }

        let (c, n) = (min_of(&ctor), min_of(&null));
        println!("AB transpose per-column ctor share (ONE binary, ONE invocation)");
        println!("  binary_sha256 = {}", binary_sha256());
        println!("  worker        = {}", worker_hostname());
        println!("  columns={ROWS} (each {COLS} cells)");
        println!(
            "  CTOR from_f64_transpose_row  min={c:9.3} ms  cv={:5.2}%",
            cv_of(&ctor)
        );
        println!(
            "  NULL identical arm           min={n:9.3} ms  cv={:5.2}%",
            cv_of(&null)
        );
        println!("  NULL-CONTROL ratio = {:.4}x", c / n);
        println!("  per-column ctor = {:.2} ns", 1e6 * c / ROWS as f64);
        println!(
            "  cv<5% both arms: ctor={} null={}",
            cv_of(&ctor) < 5.0,
            cv_of(&null) < 5.0
        );
    }

    #[test]
    #[ignore = "perf A/B; run with --ignored --nocapture"]
    fn ab_transpose_row_typed() {
        // Longer per-rep work + more reps: the first run on a loaded worker gave
        // cv 6.81%/11.54%, above the 5% gate, so its 1.715x was not claimable.
        const ROWS: usize = 200_000;
        const COLS: usize = 10;
        const BLOCKS: usize = 11;
        const REPS: usize = 5;

        let handle = plan_for(ROWS, COLS);

        // Parity, same binary, before timing: typed slice == boxed values, every row.
        for r in [0usize, 1, ROWS / 2, ROWS - 1] {
            let col = Column::from_f64_transpose_row(&handle, r);
            let typed: Vec<f64> = col.as_f64_slice().expect("typed arm").to_vec();
            let boxed: Vec<f64> = col
                .values()
                .iter()
                .map(|s| match s {
                    Scalar::Float64(v) => *v,
                    other => panic!("unexpected {other:?}"),
                })
                .collect();
            assert_eq!(typed, boxed, "row {r}: typed arm diverged from values()");
        }

        let warm = |h: &Float64TransposeRows| {
            let mut acc = 0usize;
            for r in 0..1024 {
                let col = Column::from_f64_transpose_row(h, r);
                acc += col.values().len();
                let col = Column::from_f64_transpose_row(h, r);
                acc += col.as_f64_slice().expect("typed").len();
            }
            acc
        };
        std::hint::black_box(warm(std::hint::black_box(&handle)));

        // NULL CONTROL: `null` runs the IDENTICAL arm as `orig` (values()). The ratio
        // orig/null is this harness's noise floor -- any effect smaller than that
        // deviation is indistinguishable from drift. All three arms alternate inside
        // the one measured routine, so they share the same scheduler/thermal history.
        let mut orig = Vec::with_capacity(BLOCKS);
        let mut null = Vec::with_capacity(BLOCKS);
        let mut cand = Vec::with_capacity(BLOCKS);
        for _ in 0..BLOCKS {
            let (mut bo, mut bn, mut bc) = (f64::INFINITY, f64::INFINITY, f64::INFINITY);
            for _ in 0..REPS {
                let h = std::hint::black_box(&handle);

                let t0 = Instant::now();
                let mut acc = 0usize;
                for r in 0..ROWS {
                    let col = Column::from_f64_transpose_row(h, std::hint::black_box(r));
                    acc += col.values().len();
                }
                std::hint::black_box(acc);
                bo = bo.min(t0.elapsed().as_secs_f64() * 1e3);

                // Identical to the ORIG arm, on purpose: this is the null control.
                let t0 = Instant::now();
                let mut acc = 0usize;
                for r in 0..ROWS {
                    let col = Column::from_f64_transpose_row(h, std::hint::black_box(r));
                    acc += col.values().len();
                }
                std::hint::black_box(acc);
                bn = bn.min(t0.elapsed().as_secs_f64() * 1e3);

                let t0 = Instant::now();
                let mut acc = 0usize;
                for r in 0..ROWS {
                    let col = Column::from_f64_transpose_row(h, std::hint::black_box(r));
                    acc += col.as_f64_slice().expect("typed").len();
                }
                std::hint::black_box(acc);
                bc = bc.min(t0.elapsed().as_secs_f64() * 1e3);
            }
            orig.push(bo);
            null.push(bn);
            cand.push(bc);
        }

        let (o, n, c) = (min_of(&orig), min_of(&null), min_of(&cand));
        let cells = (ROWS * COLS) as f64;
        println!("AB transpose-row typed access (ONE binary, ONE invocation, interleaved)");
        println!("  binary_sha256 = {}", binary_sha256());
        println!("  worker        = {}", worker_hostname());
        println!("  rows={ROWS} cols={COLS} cells={}", ROWS * COLS);
        println!(
            "  ORIG values()      min={o:9.3} ms  cv={:5.2}%",
            cv_of(&orig)
        );
        println!(
            "  CAND as_f64_slice  min={c:9.3} ms  cv={:5.2}%",
            cv_of(&cand)
        );
        println!(
            "  boxing tax (ORIG-CAND) = {:8.3} ms ({:5.2} ns/cell)",
            o - c,
            1e6 * (o - c) / cells
        );
        println!(
            "  NULL  values()     min={n:9.3} ms  cv={:5.2}%   <- identical arm",
            cv_of(&null)
        );
        println!(
            "  NULL-CONTROL ratio (orig/null) = {:.4}x   <- noise floor",
            o / n
        );
        println!("  fp-side ratio (orig/cand)      = {:.4}x", o / c);
        println!(
            "  effect deviation {:.1}x the null-control deviation",
            (o / c - 1.0).abs() / (o / n - 1.0).abs().max(1e-9)
        );
        println!(
            "  cv<5% all arms: orig={} null={} cand={}",
            cv_of(&orig) < 5.0,
            cv_of(&null) < 5.0,
            cv_of(&cand) < 5.0
        );
    }
}

/// A/B for routing all-valid, NaT-free Datetime64/Timedelta64 argsort through the
/// i64 radix instead of the generic `Scalar` na-last comparison sort (cc_fp).
/// ORIG = the exact generic path (materialize `Scalar`s, stable `sort_by`), kept
/// here as a bench-only reference so both arms live in ONE binary; CAND = the new
/// `argsort_with` radix path. Interleaved in a single measured routine with a
/// per-arm adjacent A/A null control; gate on median vs the null floor.
///
/// Run: `RCH_REQUIRE_REMOTE=1 env -u CARGO_TARGET_DIR rch exec -- \
///        cargo test -p fp-columnar --release --lib -- --ignored --nocapture ab_temporal_argsort`
#[cfg(test)]
mod ab_temporal_argsort_ccfp {
    use std::{process::Command, time::Instant};

    use fp_types::Scalar;

    use super::{Column, compare_scalars_na_last};

    // Byte-for-byte the generic argsort tail (lib.rs ~17627): the path a Datetime64
    // column took before the radix branch. Reference arm only.
    fn argsort_scalar_ref(col: &Column, ascending: bool) -> Vec<usize> {
        let vals = col.values();
        let mut indexed: Vec<(usize, &Scalar)> = vals.iter().enumerate().collect();
        indexed.sort_by(|a, b| compare_scalars_na_last(a.1, b.1, ascending));
        indexed.into_iter().map(|(i, _)| i).collect()
    }

    // Deterministic splitmix, no rand dep; nanos kept well away from i64::MIN (NaT).
    fn nanos(n: usize) -> Vec<i64> {
        let mut s: u64 = 0x9E37_79B9_7F4A_7C15;
        (0..n)
            .map(|_| {
                s = s.wrapping_add(0x9E37_79B9_7F4A_7C15);
                let mut z = s;
                z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
                z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
                z ^= z >> 31;
                // base 2000-01-01 + up to ~50 years of jitter; always > i64::MIN
                946_684_800_000_000_000_i64.wrapping_add((z % 1_600_000_000_000_000_000) as i64)
            })
            .collect()
    }

    fn min_of(xs: &[f64]) -> f64 {
        xs.iter().copied().fold(f64::INFINITY, f64::min)
    }
    fn median_of(xs: &[f64]) -> f64 {
        let mut v = xs.to_vec();
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        v[v.len() / 2]
    }
    fn cv_of(xs: &[f64]) -> f64 {
        let m = xs.iter().sum::<f64>() / xs.len() as f64;
        100.0 * (xs.iter().map(|x| (x - m).powi(2)).sum::<f64>() / xs.len() as f64).sqrt() / m
    }

    #[test]
    #[ignore = "perf A/B; run with --ignored --nocapture"]
    fn ab_temporal_argsort() {
        const N: usize = 1_000_000;
        const BLOCKS: usize = 9;
        const REPS: usize = 3;
        let col = Column::from_datetime64_values(nanos(N));

        // Parity in this same binary: radix perm must equal the Scalar-sort perm.
        for asc in [true, false] {
            assert_eq!(
                argsort_scalar_ref(&col, asc),
                col.argsort_with(asc),
                "radix argsort diverged from the Scalar path (ascending={asc})"
            );
        }

        for _ in 0..2 {
            std::hint::black_box(argsort_scalar_ref(std::hint::black_box(&col), true));
            std::hint::black_box(col.argsort_with(true));
        }

        let (mut orig, mut cand, mut null) = (Vec::new(), Vec::new(), Vec::new());
        for _ in 0..BLOCKS {
            let (mut bo, mut bc, mut bn) = (f64::INFINITY, f64::INFINITY, f64::INFINITY);
            for _ in 0..REPS {
                let c = std::hint::black_box(&col);
                let t0 = Instant::now();
                std::hint::black_box(argsort_scalar_ref(c, true));
                bo = bo.min(t0.elapsed().as_secs_f64() * 1e3);

                // CAND adjacent A/A -> its own null floor
                let t0 = Instant::now();
                std::hint::black_box(c.argsort_with(true));
                let a = t0.elapsed().as_secs_f64() * 1e3;
                let t0 = Instant::now();
                std::hint::black_box(c.argsort_with(true));
                let b = t0.elapsed().as_secs_f64() * 1e3;
                bc = bc.min(a.min(b));
                bn = bn.min(a.max(b) / a.min(b).max(1e-9));
            }
            orig.push(bo);
            cand.push(bc);
            null.push(bn);
        }
        let (o, c) = (min_of(&orig), min_of(&cand));
        let sha = Command::new("sha256sum")
            .arg(std::env::current_exe().unwrap())
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .and_then(|s| s.split_whitespace().next().map(str::to_owned))
            .unwrap_or_default();
        let host = Command::new("hostname")
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .map_or_else(|| "?".into(), |s| s.trim().to_owned());
        println!("AB temporal argsort (ONE binary, ONE invocation) N={N}");
        println!("  binary_sha256 = {sha}");
        println!("  worker        = {host}");
        println!(
            "  ORIG Scalar-sort  min={o:8.3} ms  cv={:.2}%",
            cv_of(&orig)
        );
        println!(
            "  CAND i64-radix    min={c:8.3} ms  cv={:.2}%",
            cv_of(&cand)
        );
        let nullmed = median_of(&null);
        println!(
            "  NULL-CONTROL (CAND A/A) median ratio={nullmed:.4}x  floor={:.2}%",
            100.0 * (nullmed - 1.0)
        );
        println!(
            "  fp-side ratio (ORIG/CAND) = {:.3}x  ({:+.1}%)  DECIDABLE={}",
            o / c,
            100.0 * (o / c - 1.0),
            100.0 * (o / c - 1.0) > 100.0 * (nullmed - 1.0)
        );
    }
}

/// A/B for routing all-valid, NaT-free Datetime64/Timedelta64 min/max through the
/// raw-i64 scan instead of materializing the `Scalar` Vec for `nanmin`/`nanmax`
/// (cc_fp). Fresh column per rep so the ORIG arm pays the materialization it pays
/// in production (min/max is typically called once per built column). ORIG =
/// `nanmin(col.values())`; CAND = `col.min()` (now the i64 scan). Interleaved in
/// one binary, per-arm adjacent A/A null control, median gate.
#[cfg(test)]
mod ab_temporal_minmax_ccfp {
    use std::{process::Command, time::Instant};

    use super::Column;

    fn nanos(n: usize) -> Vec<i64> {
        let mut s: u64 = 0x2545_F491_4F6C_DD1D;
        (0..n)
            .map(|_| {
                s = s.wrapping_add(0x9E37_79B9_7F4A_7C15);
                let mut z = s;
                z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
                z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
                z ^= z >> 31;
                946_684_800_000_000_000_i64.wrapping_add((z % 1_600_000_000_000_000_000) as i64)
            })
            .collect()
    }
    fn min_of(xs: &[f64]) -> f64 {
        xs.iter().copied().fold(f64::INFINITY, f64::min)
    }
    fn median_of(xs: &[f64]) -> f64 {
        let mut v = xs.to_vec();
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        v[v.len() / 2]
    }
    fn cv_of(xs: &[f64]) -> f64 {
        let m = xs.iter().sum::<f64>() / xs.len() as f64;
        100.0 * (xs.iter().map(|x| (x - m).powi(2)).sum::<f64>() / xs.len() as f64).sqrt() / m
    }

    #[test]
    #[ignore = "perf A/B; run with --ignored --nocapture"]
    fn ab_temporal_minmax() {
        const N: usize = 2_000_000;
        const BLOCKS: usize = 9;
        const REPS: usize = 5;
        let src = nanos(N);

        // Correctness: col.min()/max() equal the EXACT i64-nanos extremum. Note the
        // OLD path (nanmin) compares Datetime64 via a LOSSY `to_f64()` (nanos > 2^53
        // lose precision), so this exact-i64 fold is a correctness FIX for Datetime64
        // (and bit-identical for Timedelta64, whose nanmin arm is already exact i64).
        {
            let exact_min = *src.iter().min().unwrap();
            let exact_max = *src.iter().max().unwrap();
            let col = Column::from_datetime64_values(src.clone());
            assert_eq!(
                col.min(),
                fp_types::Scalar::Datetime64(exact_min),
                "min not exact"
            );
            assert_eq!(
                col.max(),
                fp_types::Scalar::Datetime64(exact_max),
                "max not exact"
            );
        }

        for _ in 0..2 {
            let col = Column::from_datetime64_values(src.clone());
            std::hint::black_box(fp_types::nanmin(col.values()));
            let col = Column::from_datetime64_values(src.clone());
            std::hint::black_box(col.min());
        }

        let (mut orig, mut cand, mut null) = (Vec::new(), Vec::new(), Vec::new());
        for _ in 0..BLOCKS {
            let (mut bo, mut bc, mut bn) = (f64::INFINITY, f64::INFINITY, f64::INFINITY);
            for _ in 0..REPS {
                // ORIG: fresh column, materialize Scalars, nanmin.
                let col = Column::from_datetime64_values(src.clone());
                let t0 = Instant::now();
                std::hint::black_box(fp_types::nanmin(std::hint::black_box(&col).values()));
                bo = bo.min(t0.elapsed().as_secs_f64() * 1e3);

                // CAND adjacent A/A: fresh column, i64 scan.
                let col2 = Column::from_datetime64_values(src.clone());
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&col2).min());
                let a = t0.elapsed().as_secs_f64() * 1e3;
                let col3 = Column::from_datetime64_values(src.clone());
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&col3).min());
                let b = t0.elapsed().as_secs_f64() * 1e3;
                bc = bc.min(a.min(b));
                bn = bn.min(a.max(b) / a.min(b).max(1e-9));
            }
            orig.push(bo);
            cand.push(bc);
            null.push(bn);
        }
        let (o, c) = (min_of(&orig), min_of(&cand));
        let sha = Command::new("sha256sum")
            .arg(std::env::current_exe().unwrap())
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .and_then(|s| s.split_whitespace().next().map(str::to_owned))
            .unwrap_or_default();
        let host = Command::new("hostname")
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .map_or_else(|| "?".into(), |s| s.trim().to_owned());
        let nullmed = median_of(&null);
        println!("AB temporal min (ONE binary, ONE invocation) N={N}");
        println!("  binary_sha256 = {sha}");
        println!("  worker        = {host}");
        println!(
            "  ORIG nanmin(materialize)  min={o:8.3} ms  cv={:.2}%",
            cv_of(&orig)
        );
        println!(
            "  CAND i64-scan             min={c:8.3} ms  cv={:.2}%",
            cv_of(&cand)
        );
        println!(
            "  NULL-CONTROL (CAND A/A) median={nullmed:.4}x  floor={:.2}%",
            100.0 * (nullmed - 1.0)
        );
        println!(
            "  fp-side ratio (ORIG/CAND) = {:.3}x  ({:+.1}%)  DECIDABLE={}",
            o / c,
            100.0 * (o / c - 1.0),
            100.0 * (o / c - 1.0) > 100.0 * (nullmed - 1.0)
        );
    }
}

/// A/B for routing all-valid, non-empty, NaT-free Timedelta64 sum/mean through the
/// raw-i64 i128 fold instead of materializing the `Scalar` Vec for `nansum`/
/// `nanmean` (cc_fp). Bit-identical: `nansum`/`nanmean` already accumulate
/// Timedelta64 in exact i128 via `collect_timedelta_ns`; this reads the same nanos
/// from the raw backing. Fresh column per rep so ORIG pays materialization; per-arm
/// adjacent A/A null control; median gate.
#[cfg(test)]
mod ab_timedelta_sum_ccfp {
    use std::{process::Command, time::Instant};

    use super::{Column, ValidityMask};

    fn ns(n: usize) -> Vec<i64> {
        let mut s: u64 = 0xD1B5_4A32_D192_ED03;
        (0..n)
            .map(|_| {
                s = s.wrapping_add(0x9E37_79B9_7F4A_7C15);
                let mut z = s;
                z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
                z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
                z ^= z >> 31;
                // durations in [-5e11, 5e11) ns (~ +/- 8 minutes), never i64::MIN
                (z % 1_000_000_000_000) as i64 - 500_000_000_000
            })
            .collect()
    }
    fn mk(src: &[i64]) -> Column {
        Column::from_timedelta64_values_with_validity(
            src.to_vec(),
            ValidityMask::all_valid(src.len()),
        )
    }
    fn min_of(xs: &[f64]) -> f64 {
        xs.iter().copied().fold(f64::INFINITY, f64::min)
    }
    fn median_of(xs: &[f64]) -> f64 {
        let mut v = xs.to_vec();
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        v[v.len() / 2]
    }
    fn cv_of(xs: &[f64]) -> f64 {
        let m = xs.iter().sum::<f64>() / xs.len() as f64;
        100.0 * (xs.iter().map(|x| (x - m).powi(2)).sum::<f64>() / xs.len() as f64).sqrt() / m
    }

    #[test]
    #[ignore = "perf A/B; run with --ignored --nocapture"]
    fn ab_timedelta_sum() {
        const N: usize = 2_000_000;
        const BLOCKS: usize = 9;
        const REPS: usize = 5;
        let src = ns(N);

        // Parity: col.sum()/mean() == nansum/nanmean over the materialized Scalars.
        {
            let col = mk(&src);
            assert_eq!(col.sum(), fp_types::nansum(col.values()), "sum diverged");
            assert_eq!(col.mean(), fp_types::nanmean(col.values()), "mean diverged");
        }

        for _ in 0..2 {
            std::hint::black_box(fp_types::nansum(mk(&src).values()));
            std::hint::black_box(mk(&src).sum());
        }

        let (mut orig, mut cand, mut null) = (Vec::new(), Vec::new(), Vec::new());
        for _ in 0..BLOCKS {
            let (mut bo, mut bc, mut bn) = (f64::INFINITY, f64::INFINITY, f64::INFINITY);
            for _ in 0..REPS {
                let col = mk(&src);
                let t0 = Instant::now();
                std::hint::black_box(fp_types::nansum(std::hint::black_box(&col).values()));
                bo = bo.min(t0.elapsed().as_secs_f64() * 1e3);

                let col2 = mk(&src);
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&col2).sum());
                let a = t0.elapsed().as_secs_f64() * 1e3;
                let col3 = mk(&src);
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&col3).sum());
                let b = t0.elapsed().as_secs_f64() * 1e3;
                bc = bc.min(a.min(b));
                bn = bn.min(a.max(b) / a.min(b).max(1e-9));
            }
            orig.push(bo);
            cand.push(bc);
            null.push(bn);
        }
        let (o, c) = (min_of(&orig), min_of(&cand));
        let sha = Command::new("sha256sum")
            .arg(std::env::current_exe().unwrap())
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .and_then(|s| s.split_whitespace().next().map(str::to_owned))
            .unwrap_or_default();
        let host = Command::new("hostname")
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .map_or_else(|| "?".into(), |s| s.trim().to_owned());
        let nullmed = median_of(&null);
        println!("AB timedelta sum (ONE binary, ONE invocation) N={N}");
        println!("  binary_sha256 = {sha}");
        println!("  worker        = {host}");
        println!(
            "  ORIG nansum(materialize)  min={o:8.3} ms  cv={:.2}%",
            cv_of(&orig)
        );
        println!(
            "  CAND i128-fold            min={c:8.3} ms  cv={:.2}%",
            cv_of(&cand)
        );
        println!(
            "  NULL-CONTROL (CAND A/A) median={nullmed:.4}x  floor={:.2}%",
            100.0 * (nullmed - 1.0)
        );
        println!(
            "  fp-side ratio (ORIG/CAND) = {:.3}x  ({:+.1}%)  DECIDABLE={}",
            o / c,
            100.0 * (o / c - 1.0),
            100.0 * (o / c - 1.0) > 100.0 * (nullmed - 1.0)
        );
    }
}

/// A/B for routing all-valid, NaT-free Datetime64/Timedelta64 value_counts through
/// the typed i64 tally (`value_counts_i64_typed`) + a re-tag, instead of the generic
/// `set_member_key` Scalar tally (cc_fp). Parity is proven against the Int64-column
/// value_counts (which shares `value_counts_i64_typed`, documented bit-identical to
/// the generic path) — same counts, same distinct nanos. ORIG timing forces the
/// generic path by planting one NAT sentinel (my branch's `!contains(i64::MIN)` gate
/// skips it); the one dropped value is negligible for timing. Median gate, per-arm
/// adjacent A/A null control.
#[cfg(test)]
mod ab_temporal_value_counts_ccfp {
    use std::{process::Command, time::Instant};

    use super::Column;

    fn nanos(n: usize, distinct: i64) -> Vec<i64> {
        let mut s: u64 = 0x7C15_9E37_79B9_4F6C;
        (0..n)
            .map(|_| {
                s = s.wrapping_add(0x9E37_79B9_7F4A_7C15);
                let mut z = s;
                z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
                z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
                z ^= z >> 31;
                946_684_800_000_000_000_i64 + (z % distinct as u64) as i64
            })
            .collect()
    }
    fn min_of(xs: &[f64]) -> f64 {
        xs.iter().copied().fold(f64::INFINITY, f64::min)
    }
    fn median_of(xs: &[f64]) -> f64 {
        let mut v = xs.to_vec();
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        v[v.len() / 2]
    }
    fn cv_of(xs: &[f64]) -> f64 {
        let m = xs.iter().sum::<f64>() / xs.len() as f64;
        100.0 * (xs.iter().map(|x| (x - m).powi(2)).sum::<f64>() / xs.len() as f64).sqrt() / m
    }

    #[test]
    #[ignore = "perf A/B; run with --ignored --nocapture"]
    fn ab_temporal_value_counts() {
        const N: usize = 2_000_000;
        const DISTINCT: i64 = 50_000;
        const BLOCKS: usize = 9;
        const REPS: usize = 3;
        let src = nanos(N, DISTINCT);

        // Parity: the fast path's (values, counts) equals the Int64-column tally
        // (both go through value_counts_i64_typed), re-tagged to Datetime64.
        {
            let dt = Column::from_datetime64_values(src.clone());
            let (dv, dc) = dt.value_counts().expect("dt value_counts");
            let iv = Column::from_i64_values_owned(src.clone());
            let (ev, ec) = iv.value_counts().expect("i64 value_counts");
            assert_eq!(dc.values(), ec.values(), "counts diverged");
            assert_eq!(
                dv.as_datetime64_slice().expect("dt values"),
                ev.as_i64_slice().expect("i64 values"),
                "distinct nanos diverged"
            );
        }

        // ORIG timing column: plant one NAT so the fast path's no-NAT gate skips it
        // -> generic set_member_key path. CAND: all-valid -> fast path.
        let mut src_orig = src.clone();
        src_orig[0] = i64::MIN;

        for _ in 0..2 {
            std::hint::black_box(
                Column::from_datetime64_values(src_orig.clone())
                    .value_counts()
                    .unwrap(),
            );
            std::hint::black_box(
                Column::from_datetime64_values(src.clone())
                    .value_counts()
                    .unwrap(),
            );
        }

        let (mut orig, mut cand, mut null) = (Vec::new(), Vec::new(), Vec::new());
        for _ in 0..BLOCKS {
            let (mut bo, mut bc, mut bn) = (f64::INFINITY, f64::INFINITY, f64::INFINITY);
            for _ in 0..REPS {
                let co = Column::from_datetime64_values(src_orig.clone());
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&co).value_counts().unwrap());
                bo = bo.min(t0.elapsed().as_secs_f64() * 1e3);

                let c1 = Column::from_datetime64_values(src.clone());
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c1).value_counts().unwrap());
                let a = t0.elapsed().as_secs_f64() * 1e3;
                let c2 = Column::from_datetime64_values(src.clone());
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c2).value_counts().unwrap());
                let b = t0.elapsed().as_secs_f64() * 1e3;
                bc = bc.min(a.min(b));
                bn = bn.min(a.max(b) / a.min(b).max(1e-9));
            }
            orig.push(bo);
            cand.push(bc);
            null.push(bn);
        }
        let (o, c) = (min_of(&orig), min_of(&cand));
        let sha = Command::new("sha256sum")
            .arg(std::env::current_exe().unwrap())
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .and_then(|s| s.split_whitespace().next().map(str::to_owned))
            .unwrap_or_default();
        let host = Command::new("hostname")
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .map_or_else(|| "?".into(), |s| s.trim().to_owned());
        let nullmed = median_of(&null);
        println!("AB temporal value_counts (ONE binary, ONE invocation) N={N} distinct={DISTINCT}");
        println!("  binary_sha256 = {sha}");
        println!("  worker        = {host}");
        println!(
            "  ORIG generic set_member_key  min={o:8.3} ms  cv={:.2}%",
            cv_of(&orig)
        );
        println!(
            "  CAND i64 tally + re-tag      min={c:8.3} ms  cv={:.2}%",
            cv_of(&cand)
        );
        println!(
            "  NULL-CONTROL (CAND A/A) median={nullmed:.4}x  floor={:.2}%",
            100.0 * (nullmed - 1.0)
        );
        println!(
            "  fp-side ratio (ORIG/CAND) = {:.3}x  ({:+.1}%)  DECIDABLE={}",
            o / c,
            100.0 * (o / c - 1.0),
            100.0 * (o / c - 1.0) > 100.0 * (nullmed - 1.0)
        );
    }
}

/// A/B for routing all-valid, NaT-free Timedelta64 unique through the raw-i64
/// open-addressing dedup (`unique_i64_wide`) + re-tag, instead of the generic
/// `Key::Timedelta64` Scalar dedup (cc_fp). Parity vs the Int64-column unique
/// (shared `unique_i64_wide`, first-seen order). ORIG timing forces the generic
/// path via one planted NAT the CAND gate skips. Median gate, per-arm A/A null.
#[cfg(test)]
mod ab_timedelta_unique_ccfp {
    use std::{process::Command, time::Instant};

    use super::{Column, ValidityMask};

    fn ns(n: usize, distinct: i64) -> Vec<i64> {
        let mut s: u64 = 0x4F6C_DD1D_2545_F491;
        (0..n)
            .map(|_| {
                s = s.wrapping_add(0x9E37_79B9_7F4A_7C15);
                let mut z = s;
                z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
                z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
                z ^= z >> 31;
                (z % distinct as u64) as i64 - distinct / 2
            })
            .collect()
    }
    fn td(v: Vec<i64>) -> Column {
        let n = v.len();
        Column::from_timedelta64_values_with_validity(v, ValidityMask::all_valid(n))
    }
    fn min_of(xs: &[f64]) -> f64 {
        xs.iter().copied().fold(f64::INFINITY, f64::min)
    }
    fn median_of(xs: &[f64]) -> f64 {
        let mut v = xs.to_vec();
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        v[v.len() / 2]
    }
    fn cv_of(xs: &[f64]) -> f64 {
        let m = xs.iter().sum::<f64>() / xs.len() as f64;
        100.0 * (xs.iter().map(|x| (x - m).powi(2)).sum::<f64>() / xs.len() as f64).sqrt() / m
    }

    #[test]
    #[ignore = "perf A/B; run with --ignored --nocapture"]
    fn ab_timedelta_unique() {
        const N: usize = 2_000_000;
        const DISTINCT: i64 = 50_000;
        const BLOCKS: usize = 9;
        const REPS: usize = 3;
        let src = ns(N, DISTINCT);

        // Parity: Timedelta unique's distinct ns == Int64-column unique (both
        // unique_i64_wide, first-seen order), re-tagged to Timedelta64.
        {
            let u = td(src.clone()).unique().expect("td unique");
            let e = Column::from_i64_values_owned(src.clone())
                .unique()
                .expect("i64 unique");
            assert_eq!(
                u.as_timedelta64_slice().expect("td values"),
                e.as_i64_slice().expect("i64 values"),
                "distinct ns diverged"
            );
        }

        // ORIG timing: plant a NAT so the no-NAT gate skips -> generic Key path.
        let mut src_orig = src.clone();
        src_orig[0] = i64::MIN;

        for _ in 0..2 {
            std::hint::black_box(td(src_orig.clone()).unique().unwrap());
            std::hint::black_box(td(src.clone()).unique().unwrap());
        }

        let (mut orig, mut cand, mut null) = (Vec::new(), Vec::new(), Vec::new());
        for _ in 0..BLOCKS {
            let (mut bo, mut bc, mut bn) = (f64::INFINITY, f64::INFINITY, f64::INFINITY);
            for _ in 0..REPS {
                let co = td(src_orig.clone());
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&co).unique().unwrap());
                bo = bo.min(t0.elapsed().as_secs_f64() * 1e3);

                let c1 = td(src.clone());
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c1).unique().unwrap());
                let a = t0.elapsed().as_secs_f64() * 1e3;
                let c2 = td(src.clone());
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c2).unique().unwrap());
                let b = t0.elapsed().as_secs_f64() * 1e3;
                bc = bc.min(a.min(b));
                bn = bn.min(a.max(b) / a.min(b).max(1e-9));
            }
            orig.push(bo);
            cand.push(bc);
            null.push(bn);
        }
        let (o, c) = (min_of(&orig), min_of(&cand));
        let sha = Command::new("sha256sum")
            .arg(std::env::current_exe().unwrap())
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .and_then(|s| s.split_whitespace().next().map(str::to_owned))
            .unwrap_or_default();
        let host = Command::new("hostname")
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .map_or_else(|| "?".into(), |s| s.trim().to_owned());
        let nullmed = median_of(&null);
        println!("AB timedelta unique (ONE binary, ONE invocation) N={N} distinct={DISTINCT}");
        println!("  binary_sha256 = {sha}");
        println!("  worker        = {host}");
        println!(
            "  ORIG generic Key dedup   min={o:8.3} ms  cv={:.2}%",
            cv_of(&orig)
        );
        println!(
            "  CAND i64 open-addr+re-tag min={c:8.3} ms  cv={:.2}%",
            cv_of(&cand)
        );
        println!(
            "  NULL-CONTROL (CAND A/A) median={nullmed:.4}x  floor={:.2}%",
            100.0 * (nullmed - 1.0)
        );
        println!(
            "  fp-side ratio (ORIG/CAND) = {:.3}x  ({:+.1}%)  DECIDABLE={}",
            o / c,
            100.0 * (o / c - 1.0),
            100.0 * (o / c - 1.0) > 100.0 * (nullmed - 1.0)
        );
    }
}

#[cfg(test)]
#[allow(clippy::items_after_statements)]
mod ab_utf8_unique_ccfp {
    use std::{process::Command, time::Instant};

    use super::{Column, DType, FxHashSet, Scalar};

    /// Seeded (splitmix64) contiguous-Utf8 buffer: `n` rows drawn from `distinct`
    /// fixed-width `"val_{:07}"` labels. Every label is a distinct heap `String`
    /// once materialized, so the generic path pays one alloc per row.
    fn mk(n: usize, distinct: usize) -> (Vec<u8>, Vec<usize>) {
        let mut s: u64 = 0x1234_5678_9ABC_DEF1;
        let mut bytes: Vec<u8> = Vec::with_capacity(n * 11);
        let mut offsets: Vec<usize> = Vec::with_capacity(n + 1);
        offsets.push(0);
        for _ in 0..n {
            s = s.wrapping_add(0x9E37_79B9_7F4A_7C15);
            let mut z = s;
            z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
            z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
            z ^= z >> 31;
            let key = (z as usize) % distinct;
            bytes.extend_from_slice(b"val_");
            let mut buf = [0u8; 7];
            let mut k = key;
            for slot in buf.iter_mut().rev() {
                *slot = b'0' + (k % 10) as u8;
                k /= 10;
            }
            bytes.extend_from_slice(&buf);
            offsets.push(bytes.len());
        }
        (bytes, offsets)
    }

    /// Reference for the pre-lever generic path: force the `Vec<Scalar::Utf8>`
    /// materialization (one `String` per row) via `as_slice`, then FxHashSet
    /// `&str` first-seen dedup with `Scalar` clone -- byte-for-byte the shipped
    /// `Key::Utf8` arm's cost, minus the fast-path interception.
    fn orig_unique_utf8(col: &Column) -> Column {
        let scalars = col.values.as_slice();
        let mut seen: FxHashSet<&str> = FxHashSet::default();
        let mut out: Vec<Scalar> = Vec::new();
        for v in scalars {
            if let Scalar::Utf8(s) = v
                && seen.insert(s.as_str())
            {
                out.push(v.clone());
            }
        }
        Column::new(DType::Utf8, out).expect("utf8 column")
    }

    fn min_of(xs: &[f64]) -> f64 {
        xs.iter().copied().fold(f64::INFINITY, f64::min)
    }
    fn median_of(xs: &[f64]) -> f64 {
        let mut v = xs.to_vec();
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        v[v.len() / 2]
    }
    fn cv_of(xs: &[f64]) -> f64 {
        let m = xs.iter().sum::<f64>() / xs.len() as f64;
        100.0 * (xs.iter().map(|x| (x - m).powi(2)).sum::<f64>() / xs.len() as f64).sqrt() / m
    }

    #[test]
    #[ignore = "perf A/B; run with --ignored --nocapture"]
    fn ab_utf8_unique() {
        const N: usize = 2_000_000;
        const DISTINCT: usize = 50_000;
        const BLOCKS: usize = 9;
        const REPS: usize = 3;
        let (bytes, offsets) = mk(N, DISTINCT);

        // Parity: the fast-path distinct sequence == the generic reference's,
        // element-for-element (same first-seen order, same bytes, same dtype).
        {
            let orig = orig_unique_utf8(&Column::from_utf8_contiguous(
                bytes.clone(),
                offsets.clone(),
            ));
            let cand = Column::from_utf8_contiguous(bytes.clone(), offsets.clone())
                .unique()
                .expect("utf8 unique");
            assert_eq!(orig.dtype(), cand.dtype(), "dtype diverged");
            assert_eq!(
                orig.values.as_slice(),
                cand.values.as_slice(),
                "distinct utf8 sequence diverged"
            );
        }

        for _ in 0..2 {
            std::hint::black_box(orig_unique_utf8(&Column::from_utf8_contiguous(
                bytes.clone(),
                offsets.clone(),
            )));
            std::hint::black_box(
                Column::from_utf8_contiguous(bytes.clone(), offsets.clone())
                    .unique()
                    .unwrap(),
            );
        }

        let (mut orig, mut cand, mut null) = (Vec::new(), Vec::new(), Vec::new());
        for _ in 0..BLOCKS {
            let (mut bo, mut bc, mut bn) = (f64::INFINITY, f64::INFINITY, f64::INFINITY);
            for _ in 0..REPS {
                let co = Column::from_utf8_contiguous(bytes.clone(), offsets.clone());
                let t0 = Instant::now();
                std::hint::black_box(orig_unique_utf8(std::hint::black_box(&co)));
                bo = bo.min(t0.elapsed().as_secs_f64() * 1e3);

                let c1 = Column::from_utf8_contiguous(bytes.clone(), offsets.clone());
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c1).unique().unwrap());
                let a = t0.elapsed().as_secs_f64() * 1e3;
                let c2 = Column::from_utf8_contiguous(bytes.clone(), offsets.clone());
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c2).unique().unwrap());
                let b = t0.elapsed().as_secs_f64() * 1e3;
                bc = bc.min(a.min(b));
                bn = bn.min(a.max(b) / a.min(b).max(1e-9));
            }
            orig.push(bo);
            cand.push(bc);
            null.push(bn);
        }
        let (o, c) = (min_of(&orig), min_of(&cand));
        let sha = Command::new("sha256sum")
            .arg(std::env::current_exe().unwrap())
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .and_then(|s| s.split_whitespace().next().map(str::to_owned))
            .unwrap_or_default();
        let host = Command::new("hostname")
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .map_or_else(|| "?".into(), |s| s.trim().to_owned());
        let nullmed = median_of(&null);
        println!("AB utf8 unique (ONE binary, ONE invocation) N={N} distinct={DISTINCT}");
        println!("  binary_sha256 = {sha}");
        println!("  worker        = {host}");
        println!(
            "  ORIG generic Scalar::Utf8 dedup min={o:8.3} ms  cv={:.2}%",
            cv_of(&orig)
        );
        println!(
            "  CAND contiguous &[u8] dedup     min={c:8.3} ms  cv={:.2}%",
            cv_of(&cand)
        );
        println!(
            "  NULL-CONTROL (CAND A/A) median={nullmed:.4}x  floor={:.2}%",
            100.0 * (nullmed - 1.0)
        );
        println!(
            "  fp-side ratio (ORIG/CAND) = {:.3}x  ({:+.1}%)  DECIDABLE={}",
            o / c,
            100.0 * (o / c - 1.0),
            100.0 * (o / c - 1.0) > 100.0 * (nullmed - 1.0)
        );
    }
}

#[cfg(test)]
#[allow(clippy::items_after_statements)]
mod ab_utf8_value_counts_ccfp {
    use std::{process::Command, time::Instant};

    use super::{Column, DType, FxHashMap, Scalar};

    /// Seeded (splitmix64) contiguous-Utf8 buffer: `n` rows drawn from `distinct`
    /// fixed-width `"val_{:07}"` labels. Every label is a distinct heap `String`
    /// once materialized, so the generic tally pays one alloc per row.
    fn mk(n: usize, distinct: usize) -> (Vec<u8>, Vec<usize>) {
        let mut s: u64 = 0x1234_5678_9ABC_DEF1;
        let mut bytes: Vec<u8> = Vec::with_capacity(n * 11);
        let mut offsets: Vec<usize> = Vec::with_capacity(n + 1);
        offsets.push(0);
        for _ in 0..n {
            s = s.wrapping_add(0x9E37_79B9_7F4A_7C15);
            let mut z = s;
            z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
            z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
            z ^= z >> 31;
            let key = (z as usize) % distinct;
            bytes.extend_from_slice(b"val_");
            let mut buf = [0u8; 7];
            let mut k = key;
            for slot in buf.iter_mut().rev() {
                *slot = b'0' + (k % 10) as u8;
                k /= 10;
            }
            bytes.extend_from_slice(&buf);
            offsets.push(bytes.len());
        }
        (bytes, offsets)
    }

    /// Reference for the pre-lever generic tally: force the `Vec<Scalar::Utf8>`
    /// materialization (one `String` per row) via `as_slice`, then FxHashMap
    /// `&str` first-seen tally with `Scalar` clone per distinct -- byte-for-byte
    /// the shipped `set_member_key` arm's cost, minus the fast-path interception
    /// (and minus the per-elem `is_missing()` / `SetMemberKey` enum wrap it also
    /// pays, so this is a CONSERVATIVE floor).
    fn orig_value_counts_utf8(
        col: &Column,
        normalize: bool,
        sort: bool,
        ascending: bool,
    ) -> (Column, Column) {
        let scalars = col.values.as_slice();
        let mut index: FxHashMap<&str, usize> = FxHashMap::default();
        let mut counts: Vec<(Scalar, usize)> = Vec::new();
        for v in scalars {
            if let Scalar::Utf8(s) = v {
                if let Some(&i) = index.get(s.as_str()) {
                    counts[i].1 += 1;
                } else {
                    index.insert(s.as_str(), counts.len());
                    counts.push((v.clone(), 1));
                }
            }
        }
        if sort {
            if ascending {
                counts.sort_by_key(|(_, count)| *count);
            } else {
                counts.sort_by_key(|(_, count)| std::cmp::Reverse(*count));
            }
        }
        let total = if normalize {
            counts.iter().map(|(_, count)| *count).sum::<usize>() as f64
        } else {
            1.0
        };
        let mut values_out: Vec<Scalar> = Vec::with_capacity(counts.len());
        let mut counts_out: Vec<Scalar> = Vec::with_capacity(counts.len());
        for (value, count) in counts {
            values_out.push(value);
            if normalize {
                let n = if total == 0.0 {
                    0.0
                } else {
                    count as f64 / total
                };
                counts_out.push(Scalar::Float64(n));
            } else {
                counts_out.push(Scalar::Int64(i64::try_from(count).unwrap_or(i64::MAX)));
            }
        }
        (
            Column::new(DType::Utf8, values_out).expect("utf8 values"),
            Column::new(
                if normalize {
                    DType::Float64
                } else {
                    DType::Int64
                },
                counts_out,
            )
            .expect("counts"),
        )
    }

    fn min_of(xs: &[f64]) -> f64 {
        xs.iter().copied().fold(f64::INFINITY, f64::min)
    }
    fn median_of(xs: &[f64]) -> f64 {
        let mut v = xs.to_vec();
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        v[v.len() / 2]
    }
    fn cv_of(xs: &[f64]) -> f64 {
        let m = xs.iter().sum::<f64>() / xs.len() as f64;
        100.0 * (xs.iter().map(|x| (x - m).powi(2)).sum::<f64>() / xs.len() as f64).sqrt() / m
    }

    #[test]
    #[ignore = "perf A/B; run with --ignored --nocapture"]
    fn ab_utf8_value_counts() {
        const N: usize = 2_000_000;
        const DISTINCT: usize = 50_000;
        const BLOCKS: usize = 9;
        const REPS: usize = 3;
        let (bytes, offsets) = mk(N, DISTINCT);
        let mk_col = || Column::from_utf8_contiguous(bytes.clone(), offsets.clone());

        // Parity across every branch (sort asc/desc/none, normalize): the fast
        // path's (values, counts) pair == the generic reference's, element-for-
        // element -- same first-seen order, same stable count-sort tie-break.
        for &(normalize, sort, ascending) in &[
            (false, true, false),
            (false, true, true),
            (false, false, false),
            (true, true, false),
        ] {
            let (ov, oc) = orig_value_counts_utf8(&mk_col(), normalize, sort, ascending);
            let (cv, cc) = mk_col()
                .value_counts_with_options(normalize, sort, ascending, true)
                .expect("value_counts");
            assert_eq!(ov.dtype(), cv.dtype(), "values dtype diverged");
            assert_eq!(
                ov.values.as_slice(),
                cv.values.as_slice(),
                "distinct values diverged (normalize={normalize} sort={sort} asc={ascending})"
            );
            assert_eq!(
                oc.values.as_slice(),
                cc.values.as_slice(),
                "counts diverged (normalize={normalize} sort={sort} asc={ascending})"
            );
        }

        for _ in 0..2 {
            std::hint::black_box(orig_value_counts_utf8(&mk_col(), false, true, false));
            std::hint::black_box(
                mk_col()
                    .value_counts_with_options(false, true, false, true)
                    .unwrap(),
            );
        }

        let (mut orig, mut cand, mut null) = (Vec::new(), Vec::new(), Vec::new());
        for _ in 0..BLOCKS {
            let (mut bo, mut bc, mut bn) = (f64::INFINITY, f64::INFINITY, f64::INFINITY);
            for _ in 0..REPS {
                let co = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(orig_value_counts_utf8(
                    std::hint::black_box(&co),
                    false,
                    true,
                    false,
                ));
                bo = bo.min(t0.elapsed().as_secs_f64() * 1e3);

                let c1 = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(
                    std::hint::black_box(&c1)
                        .value_counts_with_options(false, true, false, true)
                        .unwrap(),
                );
                let a = t0.elapsed().as_secs_f64() * 1e3;
                let c2 = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(
                    std::hint::black_box(&c2)
                        .value_counts_with_options(false, true, false, true)
                        .unwrap(),
                );
                let b = t0.elapsed().as_secs_f64() * 1e3;
                bc = bc.min(a.min(b));
                bn = bn.min(a.max(b) / a.min(b).max(1e-9));
            }
            orig.push(bo);
            cand.push(bc);
            null.push(bn);
        }
        let (o, c) = (min_of(&orig), min_of(&cand));
        let sha = Command::new("sha256sum")
            .arg(std::env::current_exe().unwrap())
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .and_then(|s| s.split_whitespace().next().map(str::to_owned))
            .unwrap_or_default();
        let host = Command::new("hostname")
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .map_or_else(|| "?".into(), |s| s.trim().to_owned());
        let nullmed = median_of(&null);
        println!("AB utf8 value_counts (ONE binary, ONE invocation) N={N} distinct={DISTINCT}");
        println!("  binary_sha256 = {sha}");
        println!("  worker        = {host}");
        println!(
            "  ORIG generic set_member_key tally min={o:8.3} ms  cv={:.2}%",
            cv_of(&orig)
        );
        println!(
            "  CAND contiguous &[u8] tally       min={c:8.3} ms  cv={:.2}%",
            cv_of(&cand)
        );
        println!(
            "  NULL-CONTROL (CAND A/A) median={nullmed:.4}x  floor={:.2}%",
            100.0 * (nullmed - 1.0)
        );
        println!(
            "  fp-side ratio (ORIG/CAND) = {:.3}x  ({:+.1}%)  DECIDABLE={}",
            o / c,
            100.0 * (o / c - 1.0),
            100.0 * (o / c - 1.0) > 100.0 * (nullmed - 1.0)
        );
    }
}

#[cfg(test)]
#[allow(clippy::items_after_statements)]
mod ab_utf8_nunique_ccfp {
    use std::{process::Command, time::Instant};

    use super::{Column, FxHashSet, Scalar};

    /// Seeded (splitmix64) contiguous-Utf8 buffer: `n` rows drawn from `distinct`
    /// fixed-width `"val_{:07}"` labels. Every label is a distinct heap `String`
    /// once materialized, so the `nannunique` path pays one alloc per row.
    fn mk(n: usize, distinct: usize) -> (Vec<u8>, Vec<usize>) {
        let mut s: u64 = 0x1234_5678_9ABC_DEF1;
        let mut bytes: Vec<u8> = Vec::with_capacity(n * 11);
        let mut offsets: Vec<usize> = Vec::with_capacity(n + 1);
        offsets.push(0);
        for _ in 0..n {
            s = s.wrapping_add(0x9E37_79B9_7F4A_7C15);
            let mut z = s;
            z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
            z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
            z ^= z >> 31;
            let key = (z as usize) % distinct;
            bytes.extend_from_slice(b"val_");
            let mut buf = [0u8; 7];
            let mut k = key;
            for slot in buf.iter_mut().rev() {
                *slot = b'0' + (k % 10) as u8;
                k /= 10;
            }
            bytes.extend_from_slice(&buf);
            offsets.push(bytes.len());
        }
        (bytes, offsets)
    }

    /// Reference for the pre-lever generic path: force the `Vec<Scalar::Utf8>`
    /// materialization (one `String` per row) via `as_slice`, then FxHashSet
    /// `&str` distinct count -- byte-for-byte `nannunique`'s cost for an all-valid
    /// Utf8 column, minus the fast-path interception (CONSERVATIVE: omits the
    /// per-elem `is_missing()` test and `ScalarKey` enum wrap it also pays).
    fn orig_nunique_utf8(col: &Column) -> i64 {
        let scalars = col.values.as_slice();
        let mut seen: FxHashSet<&str> = FxHashSet::default();
        for v in scalars {
            if let Scalar::Utf8(s) = v {
                seen.insert(s.as_str());
            }
        }
        seen.len() as i64
    }

    fn as_i64(s: &Scalar) -> i64 {
        match s {
            Scalar::Int64(v) => *v,
            other => panic!("expected Int64, got {other:?}"),
        }
    }

    fn min_of(xs: &[f64]) -> f64 {
        xs.iter().copied().fold(f64::INFINITY, f64::min)
    }
    fn median_of(xs: &[f64]) -> f64 {
        let mut v = xs.to_vec();
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        v[v.len() / 2]
    }
    fn cv_of(xs: &[f64]) -> f64 {
        let m = xs.iter().sum::<f64>() / xs.len() as f64;
        100.0 * (xs.iter().map(|x| (x - m).powi(2)).sum::<f64>() / xs.len() as f64).sqrt() / m
    }

    #[test]
    #[ignore = "perf A/B; run with --ignored --nocapture"]
    fn ab_utf8_nunique() {
        const N: usize = 2_000_000;
        const DISTINCT: usize = 50_000;
        const BLOCKS: usize = 9;
        const REPS: usize = 3;
        let (bytes, offsets) = mk(N, DISTINCT);
        let mk_col = || Column::from_utf8_contiguous(bytes.clone(), offsets.clone());

        // Parity: fast-path count == generic reference AND == DISTINCT; and both
        // dropna values agree for an all-valid column (no missing bucket).
        {
            let expect = orig_nunique_utf8(&mk_col());
            assert_eq!(expect, DISTINCT as i64, "reference miscounted");
            assert_eq!(expect, as_i64(&mk_col().nunique()), "nunique diverged");
            assert_eq!(
                expect,
                as_i64(&mk_col().nunique_with_dropna(false)),
                "nunique(dropna=false) diverged"
            );
        }

        for _ in 0..2 {
            std::hint::black_box(orig_nunique_utf8(&mk_col()));
            std::hint::black_box(mk_col().nunique());
        }

        let (mut orig, mut cand, mut null) = (Vec::new(), Vec::new(), Vec::new());
        for _ in 0..BLOCKS {
            let (mut bo, mut bc, mut bn) = (f64::INFINITY, f64::INFINITY, f64::INFINITY);
            for _ in 0..REPS {
                let co = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(orig_nunique_utf8(std::hint::black_box(&co)));
                bo = bo.min(t0.elapsed().as_secs_f64() * 1e3);

                let c1 = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c1).nunique());
                let a = t0.elapsed().as_secs_f64() * 1e3;
                let c2 = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c2).nunique());
                let b = t0.elapsed().as_secs_f64() * 1e3;
                bc = bc.min(a.min(b));
                bn = bn.min(a.max(b) / a.min(b).max(1e-9));
            }
            orig.push(bo);
            cand.push(bc);
            null.push(bn);
        }
        let (o, c) = (min_of(&orig), min_of(&cand));
        let sha = Command::new("sha256sum")
            .arg(std::env::current_exe().unwrap())
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .and_then(|s| s.split_whitespace().next().map(str::to_owned))
            .unwrap_or_default();
        let host = Command::new("hostname")
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .map_or_else(|| "?".into(), |s| s.trim().to_owned());
        let nullmed = median_of(&null);
        println!("AB utf8 nunique (ONE binary, ONE invocation) N={N} distinct={DISTINCT}");
        println!("  binary_sha256 = {sha}");
        println!("  worker        = {host}");
        println!(
            "  ORIG nannunique Scalar::Utf8 count min={o:8.3} ms  cv={:.2}%",
            cv_of(&orig)
        );
        println!(
            "  CAND contiguous &[u8] count        min={c:8.3} ms  cv={:.2}%",
            cv_of(&cand)
        );
        println!(
            "  NULL-CONTROL (CAND A/A) median={nullmed:.4}x  floor={:.2}%",
            100.0 * (nullmed - 1.0)
        );
        println!(
            "  fp-side ratio (ORIG/CAND) = {:.3}x  ({:+.1}%)  DECIDABLE={}",
            o / c,
            100.0 * (o / c - 1.0),
            100.0 * (o / c - 1.0) > 100.0 * (nullmed - 1.0)
        );
    }
}

#[cfg(test)]
#[allow(clippy::items_after_statements)]
mod ab_utf8_mode_ccfp {
    use std::{process::Command, time::Instant};

    use super::{Column, DType, FxHashMap, Scalar, compare_scalars_na_last};

    /// Seeded (splitmix64) contiguous-Utf8 buffer: `n` rows drawn from `distinct`
    /// fixed-width `"val_{:07}"` labels. Every label is a distinct heap `String`
    /// once materialized, so the generic tally pays one alloc per row.
    fn mk(n: usize, distinct: usize) -> (Vec<u8>, Vec<usize>) {
        let mut s: u64 = 0x1234_5678_9ABC_DEF1;
        let mut bytes: Vec<u8> = Vec::with_capacity(n * 11);
        let mut offsets: Vec<usize> = Vec::with_capacity(n + 1);
        offsets.push(0);
        for _ in 0..n {
            s = s.wrapping_add(0x9E37_79B9_7F4A_7C15);
            let mut z = s;
            z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
            z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
            z ^= z >> 31;
            let key = (z as usize) % distinct;
            bytes.extend_from_slice(b"val_");
            let mut buf = [0u8; 7];
            let mut k = key;
            for slot in buf.iter_mut().rev() {
                *slot = b'0' + (k % 10) as u8;
                k /= 10;
            }
            bytes.extend_from_slice(&buf);
            offsets.push(bytes.len());
        }
        (bytes, offsets)
    }

    fn col_of(strs: &[&str]) -> Column {
        let mut b: Vec<u8> = Vec::new();
        let mut o: Vec<usize> = vec![0];
        for s in strs {
            b.extend_from_slice(s.as_bytes());
            o.push(b.len());
        }
        Column::from_utf8_contiguous(b, o)
    }

    /// Reference for the pre-lever generic mode path over an all-valid Utf8
    /// column: force `Vec<Scalar::Utf8>` materialization via `as_slice`, tally
    /// into an FxHashMap keyed by `&str` (first-seen `Scalar` kept for output),
    /// then the winners = max-count values sorted by the SHIPPED
    /// `compare_scalars_na_last(.., true)`. CONSERVATIVE: omits the per-elem
    /// `is_missing()` / `key_of` enum wrap the shipped arm also pays.
    fn orig_mode_utf8(col: &Column) -> Column {
        let scalars = col.values.as_slice();
        let mut counts: FxHashMap<&str, (usize, &Scalar)> = FxHashMap::default();
        for v in scalars {
            if let Scalar::Utf8(s) = v {
                counts
                    .entry(s.as_str())
                    .and_modify(|entry| entry.0 += 1)
                    .or_insert((1, v));
            }
        }
        if counts.is_empty() {
            return Column::new(DType::Utf8, Vec::new()).expect("empty utf8");
        }
        let max_count = counts.values().map(|(c, _)| *c).max().unwrap_or(0);
        let mut winners: Vec<Scalar> = counts
            .values()
            .filter_map(|(c, v)| {
                if *c == max_count {
                    Some((*v).clone())
                } else {
                    None
                }
            })
            .collect();
        winners.sort_by(|a, b| compare_scalars_na_last(a, b, true));
        Column::new(DType::Utf8, winners).expect("utf8 winners")
    }

    fn min_of(xs: &[f64]) -> f64 {
        xs.iter().copied().fold(f64::INFINITY, f64::min)
    }
    fn median_of(xs: &[f64]) -> f64 {
        let mut v = xs.to_vec();
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        v[v.len() / 2]
    }
    fn cv_of(xs: &[f64]) -> f64 {
        let m = xs.iter().sum::<f64>() / xs.len() as f64;
        100.0 * (xs.iter().map(|x| (x - m).powi(2)).sum::<f64>() / xs.len() as f64).sqrt() / m
    }

    #[test]
    #[ignore = "perf A/B; run with --ignored --nocapture"]
    fn ab_utf8_mode() {
        const N: usize = 2_000_000;
        const DISTINCT: usize = 50_000;
        const BLOCKS: usize = 9;
        const REPS: usize = 3;
        let (bytes, offsets) = mk(N, DISTINCT);
        let mk_col = || Column::from_utf8_contiguous(bytes.clone(), offsets.clone());

        // Parity: fast-path winners == generic reference on the big column.
        {
            let om = orig_mode_utf8(&mk_col());
            let cm = mk_col().mode().expect("mode");
            assert_eq!(om.dtype(), cm.dtype(), "dtype diverged");
            assert_eq!(
                om.values.as_slice(),
                cm.values.as_slice(),
                "mode winners diverged (big column)"
            );
        }
        // Multi-winner tie exercises the winner sort: a,b both count 2 -> ["a","b"].
        {
            let tie = col_of(&["b", "a", "b", "a", "c"]);
            let cm = tie.mode().expect("tie mode");
            assert_eq!(
                cm.values.as_slice(),
                orig_mode_utf8(&tie).values.as_slice(),
                "tie winners diverged vs reference"
            );
            assert_eq!(
                cm.values.as_slice(),
                col_of(&["a", "b"]).values.as_slice(),
                "tie winners not the expected sorted [a,b]"
            );
        }
        // Empty column -> empty same-dtype column.
        {
            let empty = col_of(&[]);
            assert_eq!(
                empty.mode().expect("empty mode").values.as_slice(),
                orig_mode_utf8(&empty).values.as_slice(),
                "empty mode diverged"
            );
        }

        for _ in 0..2 {
            std::hint::black_box(orig_mode_utf8(&mk_col()));
            std::hint::black_box(mk_col().mode().unwrap());
        }

        let (mut orig, mut cand, mut null) = (Vec::new(), Vec::new(), Vec::new());
        for _ in 0..BLOCKS {
            let (mut bo, mut bc, mut bn) = (f64::INFINITY, f64::INFINITY, f64::INFINITY);
            for _ in 0..REPS {
                let co = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(orig_mode_utf8(std::hint::black_box(&co)));
                bo = bo.min(t0.elapsed().as_secs_f64() * 1e3);

                let c1 = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c1).mode().unwrap());
                let a = t0.elapsed().as_secs_f64() * 1e3;
                let c2 = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c2).mode().unwrap());
                let b = t0.elapsed().as_secs_f64() * 1e3;
                bc = bc.min(a.min(b));
                bn = bn.min(a.max(b) / a.min(b).max(1e-9));
            }
            orig.push(bo);
            cand.push(bc);
            null.push(bn);
        }
        let (o, c) = (min_of(&orig), min_of(&cand));
        let sha = Command::new("sha256sum")
            .arg(std::env::current_exe().unwrap())
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .and_then(|s| s.split_whitespace().next().map(str::to_owned))
            .unwrap_or_default();
        let host = Command::new("hostname")
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .map_or_else(|| "?".into(), |s| s.trim().to_owned());
        let nullmed = median_of(&null);
        println!("AB utf8 mode (ONE binary, ONE invocation) N={N} distinct={DISTINCT}");
        println!("  binary_sha256 = {sha}");
        println!("  worker        = {host}");
        println!(
            "  ORIG generic Key::Utf8 tally  min={o:8.3} ms  cv={:.2}%",
            cv_of(&orig)
        );
        println!(
            "  CAND contiguous &[u8] tally   min={c:8.3} ms  cv={:.2}%",
            cv_of(&cand)
        );
        println!(
            "  NULL-CONTROL (CAND A/A) median={nullmed:.4}x  floor={:.2}%",
            100.0 * (nullmed - 1.0)
        );
        println!(
            "  fp-side ratio (ORIG/CAND) = {:.3}x  ({:+.1}%)  DECIDABLE={}",
            o / c,
            100.0 * (o / c - 1.0),
            100.0 * (o / c - 1.0) > 100.0 * (nullmed - 1.0)
        );
    }
}

#[cfg(test)]
#[allow(clippy::items_after_statements)]
mod ab_utf8_duplicated_ccfp {
    use std::{process::Command, time::Instant};

    use super::{Column, DType, FxHashSet, Scalar};

    /// Seeded (splitmix64) contiguous-Utf8 buffer: `n` rows drawn from `distinct`
    /// fixed-width `"val_{:07}"` labels. Every label is a distinct heap `String`
    /// once materialized, so the generic path pays one alloc per row.
    fn mk(n: usize, distinct: usize) -> (Vec<u8>, Vec<usize>) {
        let mut s: u64 = 0x1234_5678_9ABC_DEF1;
        let mut bytes: Vec<u8> = Vec::with_capacity(n * 11);
        let mut offsets: Vec<usize> = Vec::with_capacity(n + 1);
        offsets.push(0);
        for _ in 0..n {
            s = s.wrapping_add(0x9E37_79B9_7F4A_7C15);
            let mut z = s;
            z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
            z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
            z ^= z >> 31;
            let key = (z as usize) % distinct;
            bytes.extend_from_slice(b"val_");
            let mut buf = [0u8; 7];
            let mut k = key;
            for slot in buf.iter_mut().rev() {
                *slot = b'0' + (k % 10) as u8;
                k /= 10;
            }
            bytes.extend_from_slice(&buf);
            offsets.push(bytes.len());
        }
        (bytes, offsets)
    }

    /// Reference for the pre-lever generic path: force the `Vec<Scalar::Utf8>`
    /// materialization (one `String` per row) via `as_slice`, then FxHashSet
    /// `&str` duplicate-flag computation per policy -- byte-for-byte the shipped
    /// `Key` path's cost for an all-valid Utf8 column, minus the fast-path
    /// interception (CONSERVATIVE: omits the per-elem `is_missing()` / `Key` enum
    /// wrap it also pays).
    fn orig_duplicated_utf8(col: &Column, policy: &str) -> Column {
        let scalars = col.values.as_slice();
        let n = scalars.len();
        let mut flags = vec![false; n];
        match policy {
            "first" => {
                let mut seen: FxHashSet<&str> = FxHashSet::default();
                for (idx, v) in scalars.iter().enumerate() {
                    if let Scalar::Utf8(s) = v {
                        flags[idx] = !seen.insert(s.as_str());
                    }
                }
            }
            "last" => {
                let mut seen: FxHashSet<&str> = FxHashSet::default();
                for idx in (0..n).rev() {
                    if let Scalar::Utf8(s) = &scalars[idx] {
                        flags[idx] = !seen.insert(s.as_str());
                    }
                }
            }
            _ => {
                let mut seen_once: FxHashSet<&str> = FxHashSet::default();
                let mut seen_multiple: FxHashSet<&str> = FxHashSet::default();
                for v in scalars {
                    if let Scalar::Utf8(s) = v
                        && !seen_once.insert(s.as_str())
                    {
                        seen_multiple.insert(s.as_str());
                    }
                }
                for (idx, v) in scalars.iter().enumerate() {
                    if let Scalar::Utf8(s) = v {
                        flags[idx] = seen_multiple.contains(s.as_str());
                    }
                }
            }
        }
        Column::new(DType::Bool, flags.into_iter().map(Scalar::Bool).collect()).expect("bool")
    }

    fn min_of(xs: &[f64]) -> f64 {
        xs.iter().copied().fold(f64::INFINITY, f64::min)
    }
    fn median_of(xs: &[f64]) -> f64 {
        let mut v = xs.to_vec();
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        v[v.len() / 2]
    }
    fn cv_of(xs: &[f64]) -> f64 {
        let m = xs.iter().sum::<f64>() / xs.len() as f64;
        100.0 * (xs.iter().map(|x| (x - m).powi(2)).sum::<f64>() / xs.len() as f64).sqrt() / m
    }

    #[test]
    #[ignore = "perf A/B; run with --ignored --nocapture"]
    fn ab_utf8_duplicated() {
        const N: usize = 2_000_000;
        const DISTINCT: usize = 50_000;
        const BLOCKS: usize = 9;
        const REPS: usize = 3;
        let (bytes, offsets) = mk(N, DISTINCT);
        let mk_col = || Column::from_utf8_contiguous(bytes.clone(), offsets.clone());

        // Parity across every policy (first/last/none): the fast path's Bool
        // flags == the generic reference's, element-for-element. Also checks
        // drop_duplicates (= duplicated + filter) agrees for keep="first".
        for policy in ["first", "last", "false"] {
            let orig = orig_duplicated_utf8(&mk_col(), policy);
            let cand = mk_col().duplicated_keep(policy).expect("duplicated");
            assert_eq!(orig.dtype(), cand.dtype(), "dtype diverged");
            assert_eq!(
                orig.values.as_slice(),
                cand.values.as_slice(),
                "duplicated flags diverged (policy={policy})"
            );
        }
        {
            let dd = mk_col().drop_duplicates_keep("first").expect("drop_dup");
            // distinct count preserved: drop_duplicates("first") keeps DISTINCT rows.
            assert_eq!(dd.len(), DISTINCT, "drop_duplicates kept wrong count");
        }

        for _ in 0..2 {
            std::hint::black_box(orig_duplicated_utf8(&mk_col(), "first"));
            std::hint::black_box(mk_col().duplicated_keep("first").unwrap());
        }

        let (mut orig, mut cand, mut null) = (Vec::new(), Vec::new(), Vec::new());
        for _ in 0..BLOCKS {
            let (mut bo, mut bc, mut bn) = (f64::INFINITY, f64::INFINITY, f64::INFINITY);
            for _ in 0..REPS {
                let co = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(orig_duplicated_utf8(std::hint::black_box(&co), "first"));
                bo = bo.min(t0.elapsed().as_secs_f64() * 1e3);

                let c1 = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c1).duplicated_keep("first").unwrap());
                let a = t0.elapsed().as_secs_f64() * 1e3;
                let c2 = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c2).duplicated_keep("first").unwrap());
                let b = t0.elapsed().as_secs_f64() * 1e3;
                bc = bc.min(a.min(b));
                bn = bn.min(a.max(b) / a.min(b).max(1e-9));
            }
            orig.push(bo);
            cand.push(bc);
            null.push(bn);
        }
        let (o, c) = (min_of(&orig), min_of(&cand));
        let sha = Command::new("sha256sum")
            .arg(std::env::current_exe().unwrap())
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .and_then(|s| s.split_whitespace().next().map(str::to_owned))
            .unwrap_or_default();
        let host = Command::new("hostname")
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .map_or_else(|| "?".into(), |s| s.trim().to_owned());
        let nullmed = median_of(&null);
        println!(
            "AB utf8 duplicated keep=first (ONE binary, ONE invocation) N={N} distinct={DISTINCT}"
        );
        println!("  binary_sha256 = {sha}");
        println!("  worker        = {host}");
        println!(
            "  ORIG generic Key::Utf8 flags min={o:8.3} ms  cv={:.2}%",
            cv_of(&orig)
        );
        println!(
            "  CAND contiguous &[u8] flags  min={c:8.3} ms  cv={:.2}%",
            cv_of(&cand)
        );
        println!(
            "  NULL-CONTROL (CAND A/A) median={nullmed:.4}x  floor={:.2}%",
            100.0 * (nullmed - 1.0)
        );
        println!(
            "  fp-side ratio (ORIG/CAND) = {:.3}x  ({:+.1}%)  DECIDABLE={}",
            o / c,
            100.0 * (o / c - 1.0),
            100.0 * (o / c - 1.0) > 100.0 * (nullmed - 1.0)
        );
    }
}

#[cfg(test)]
#[allow(clippy::items_after_statements)]
mod ab_utf8_isin_ccfp {
    use std::{process::Command, time::Instant};

    use super::{Column, DType, FxHashSet, Scalar};

    /// Seeded (splitmix64) contiguous-Utf8 buffer: `n` rows drawn from `distinct`
    /// fixed-width `"val_{:07}"` labels.
    fn mk(n: usize, distinct: usize) -> (Vec<u8>, Vec<usize>) {
        let mut s: u64 = 0x1234_5678_9ABC_DEF1;
        let mut bytes: Vec<u8> = Vec::with_capacity(n * 11);
        let mut offsets: Vec<usize> = Vec::with_capacity(n + 1);
        offsets.push(0);
        for _ in 0..n {
            s = s.wrapping_add(0x9E37_79B9_7F4A_7C15);
            let mut z = s;
            z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
            z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
            z ^= z >> 31;
            let key = (z as usize) % distinct;
            bytes.extend_from_slice(b"val_");
            let mut buf = [0u8; 7];
            let mut k = key;
            for slot in buf.iter_mut().rev() {
                *slot = b'0' + (k % 10) as u8;
                k /= 10;
            }
            bytes.extend_from_slice(&buf);
            offsets.push(bytes.len());
        }
        (bytes, offsets)
    }

    /// `count` needle labels `"val_{:07}"` for keys `0..count` (same alphabet as
    /// `mk`), so ~`count/distinct` of the rows match.
    fn needle_scalars(count: usize) -> Vec<Scalar> {
        (0..count)
            .map(|k| Scalar::Utf8(format!("val_{k:07}")))
            .collect()
    }

    /// Reference for the pre-lever generic scan: build the `&str` needle set,
    /// force `Vec<Scalar::Utf8>` materialization via `as_slice`, probe membership
    /// per row -- byte-for-byte the shipped `Key::Utf8` scan minus the fast-path
    /// interception (CONSERVATIVE: omits the per-elem `key_of` is_missing/enum
    /// wrap the shipped arm pays).
    fn orig_isin_utf8(col: &Column, needles: &[Scalar]) -> Column {
        let mut lookup: FxHashSet<&str> = FxHashSet::default();
        for n in needles {
            if let Scalar::Utf8(s) = n {
                lookup.insert(s.as_str());
            }
        }
        let scalars = col.values.as_slice();
        let out: Vec<Scalar> = scalars
            .iter()
            .map(|v| {
                Scalar::Bool(match v {
                    Scalar::Utf8(s) => lookup.contains(s.as_str()),
                    _ => false,
                })
            })
            .collect();
        Column::new(DType::Bool, out).expect("bool")
    }

    fn min_of(xs: &[f64]) -> f64 {
        xs.iter().copied().fold(f64::INFINITY, f64::min)
    }
    fn median_of(xs: &[f64]) -> f64 {
        let mut v = xs.to_vec();
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        v[v.len() / 2]
    }
    fn cv_of(xs: &[f64]) -> f64 {
        let m = xs.iter().sum::<f64>() / xs.len() as f64;
        100.0 * (xs.iter().map(|x| (x - m).powi(2)).sum::<f64>() / xs.len() as f64).sqrt() / m
    }

    #[test]
    #[ignore = "perf A/B; run with --ignored --nocapture"]
    fn ab_utf8_isin() {
        const N: usize = 2_000_000;
        const DISTINCT: usize = 50_000;
        const NEEDLES: usize = 5_000;
        const BLOCKS: usize = 9;
        const REPS: usize = 3;
        let (bytes, offsets) = mk(N, DISTINCT);
        let mk_col = || Column::from_utf8_contiguous(bytes.clone(), offsets.clone());
        let needles = needle_scalars(NEEDLES);

        // Parity: fast path == generic reference (~10% hit); empty needle set =>
        // all false; a mixed non-Utf8 (Int64) needle is inert (only Utf8 matches).
        {
            let orig = orig_isin_utf8(&mk_col(), &needles);
            let cand = mk_col().isin(&needles).expect("isin");
            assert_eq!(orig.dtype(), cand.dtype(), "dtype diverged");
            assert_eq!(
                orig.values.as_slice(),
                cand.values.as_slice(),
                "isin flags diverged"
            );

            let empty: Vec<Scalar> = Vec::new();
            assert_eq!(
                mk_col().isin(&empty).expect("isin empty").values.as_slice(),
                orig_isin_utf8(&mk_col(), &empty).values.as_slice(),
                "empty-needle isin diverged"
            );

            let mut mixed = needles.clone();
            mixed.push(Scalar::Int64(42));
            assert_eq!(
                mk_col().isin(&mixed).expect("isin mixed").values.as_slice(),
                cand.values.as_slice(),
                "non-Utf8 needle was not inert"
            );
        }

        for _ in 0..2 {
            std::hint::black_box(orig_isin_utf8(&mk_col(), &needles));
            std::hint::black_box(mk_col().isin(&needles).unwrap());
        }

        let (mut orig, mut cand, mut null) = (Vec::new(), Vec::new(), Vec::new());
        for _ in 0..BLOCKS {
            let (mut bo, mut bc, mut bn) = (f64::INFINITY, f64::INFINITY, f64::INFINITY);
            for _ in 0..REPS {
                let co = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(orig_isin_utf8(std::hint::black_box(&co), &needles));
                bo = bo.min(t0.elapsed().as_secs_f64() * 1e3);

                let c1 = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c1).isin(&needles).unwrap());
                let a = t0.elapsed().as_secs_f64() * 1e3;
                let c2 = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c2).isin(&needles).unwrap());
                let b = t0.elapsed().as_secs_f64() * 1e3;
                bc = bc.min(a.min(b));
                bn = bn.min(a.max(b) / a.min(b).max(1e-9));
            }
            orig.push(bo);
            cand.push(bc);
            null.push(bn);
        }
        let (o, c) = (min_of(&orig), min_of(&cand));
        let sha = Command::new("sha256sum")
            .arg(std::env::current_exe().unwrap())
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .and_then(|s| s.split_whitespace().next().map(str::to_owned))
            .unwrap_or_default();
        let host = Command::new("hostname")
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .map_or_else(|| "?".into(), |s| s.trim().to_owned());
        let nullmed = median_of(&null);
        println!(
            "AB utf8 isin (ONE binary, ONE invocation) N={N} distinct={DISTINCT} needles={NEEDLES}"
        );
        println!("  binary_sha256 = {sha}");
        println!("  worker        = {host}");
        println!(
            "  ORIG generic Key::Utf8 probe min={o:8.3} ms  cv={:.2}%",
            cv_of(&orig)
        );
        println!(
            "  CAND contiguous &[u8] probe  min={c:8.3} ms  cv={:.2}%",
            cv_of(&cand)
        );
        println!(
            "  NULL-CONTROL (CAND A/A) median={nullmed:.4}x  floor={:.2}%",
            100.0 * (nullmed - 1.0)
        );
        println!(
            "  fp-side ratio (ORIG/CAND) = {:.3}x  ({:+.1}%)  DECIDABLE={}",
            o / c,
            100.0 * (o / c - 1.0),
            100.0 * (o / c - 1.0) > 100.0 * (nullmed - 1.0)
        );
    }
}

#[cfg(test)]
#[allow(clippy::items_after_statements)]
mod ab_utf8_replace_ccfp {
    use std::{process::Command, time::Instant};

    use super::{Column, DType, Scalar};

    /// Seeded (splitmix64) contiguous-Utf8 buffer: `n` rows drawn from `distinct`
    /// fixed-width `"val_{:07}"` labels.
    fn mk(n: usize, distinct: usize) -> (Vec<u8>, Vec<usize>) {
        let mut s: u64 = 0x1234_5678_9ABC_DEF1;
        let mut bytes: Vec<u8> = Vec::with_capacity(n * 11);
        let mut offsets: Vec<usize> = Vec::with_capacity(n + 1);
        offsets.push(0);
        for _ in 0..n {
            s = s.wrapping_add(0x9E37_79B9_7F4A_7C15);
            let mut z = s;
            z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
            z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
            z ^= z >> 31;
            let key = (z as usize) % distinct;
            bytes.extend_from_slice(b"val_");
            let mut buf = [0u8; 7];
            let mut k = key;
            for slot in buf.iter_mut().rev() {
                *slot = b'0' + (k % 10) as u8;
                k /= 10;
            }
            bytes.extend_from_slice(&buf);
            offsets.push(bytes.len());
        }
        (bytes, offsets)
    }

    /// `count` (target, replacement) label pairs: `"val_{:07}"` -> `"REPL_{:05}"`
    /// for keys `0..count` (targets are real labels present in `mk`).
    fn pairs(count: usize) -> (Vec<Scalar>, Vec<Scalar>) {
        let t = (0..count)
            .map(|k| Scalar::Utf8(format!("val_{k:07}")))
            .collect();
        let r = (0..count)
            .map(|k| Scalar::Utf8(format!("REPL_{k:05}")))
            .collect();
        (t, r)
    }

    /// Reference for the pre-lever generic path: force `Vec<Scalar::Utf8>`
    /// materialization via `as_slice`, then the SHIPPED per-row O(k) linear
    /// `semantic_eq` scan over targets (byte-for-byte the generic body, minus the
    /// fast-path interception).
    fn orig_replace_utf8(col: &Column, to_replace: &[Scalar], replacement: &[Scalar]) -> Column {
        let scalars = col.values.as_slice();
        let out: Vec<Scalar> = scalars
            .iter()
            .map(|v| {
                for (target, rep) in to_replace.iter().zip(replacement.iter()) {
                    let matches = if target.is_missing() && v.is_missing() {
                        true
                    } else if target.is_missing() || v.is_missing() {
                        false
                    } else {
                        v.semantic_eq(target)
                    };
                    if matches {
                        return rep.clone();
                    }
                }
                v.clone()
            })
            .collect();
        let inferred = super::infer_dtype(&out).unwrap_or(DType::Utf8);
        Column::new(inferred, out).expect("replace out")
    }

    fn min_of(xs: &[f64]) -> f64 {
        xs.iter().copied().fold(f64::INFINITY, f64::min)
    }
    fn median_of(xs: &[f64]) -> f64 {
        let mut v = xs.to_vec();
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        v[v.len() / 2]
    }
    fn cv_of(xs: &[f64]) -> f64 {
        let m = xs.iter().sum::<f64>() / xs.len() as f64;
        100.0 * (xs.iter().map(|x| (x - m).powi(2)).sum::<f64>() / xs.len() as f64).sqrt() / m
    }

    #[test]
    #[ignore = "perf A/B; run with --ignored --nocapture"]
    fn ab_utf8_replace() {
        const N: usize = 2_000_000;
        const DISTINCT: usize = 50_000;
        const K: usize = 10;
        const BLOCKS: usize = 9;
        const REPS: usize = 3;
        let (bytes, offsets) = mk(N, DISTINCT);
        let mk_col = || Column::from_utf8_contiguous(bytes.clone(), offsets.clone());
        let (to_replace, replacement) = pairs(K);

        // Parity: fast path == generic reference. Also: empty map = identity;
        // a target NOT present leaves the column unchanged; duplicate targets are
        // first-match-wins.
        {
            let orig = orig_replace_utf8(&mk_col(), &to_replace, &replacement);
            let cand = mk_col()
                .replace_values(&to_replace, &replacement)
                .expect("replace");
            assert_eq!(orig.dtype(), cand.dtype(), "dtype diverged");
            assert_eq!(
                orig.values.as_slice(),
                cand.values.as_slice(),
                "replace output diverged"
            );

            let empty: Vec<Scalar> = Vec::new();
            assert_eq!(
                mk_col()
                    .replace_values(&empty, &empty)
                    .expect("empty replace")
                    .values
                    .as_slice(),
                mk_col().values.as_slice(),
                "empty-map replace was not identity"
            );

            // Duplicate target, different replacements: first wins.
            let dt = vec![
                Scalar::Utf8("val_0000000".into()),
                Scalar::Utf8("val_0000000".into()),
            ];
            let dr = vec![Scalar::Utf8("FIRST".into()), Scalar::Utf8("SECOND".into())];
            let cd = mk_col().replace_values(&dt, &dr).expect("dup replace");
            let od = orig_replace_utf8(&mk_col(), &dt, &dr);
            assert_eq!(
                cd.values.as_slice(),
                od.values.as_slice(),
                "duplicate-target first-match-wins diverged"
            );
        }

        for _ in 0..2 {
            std::hint::black_box(orig_replace_utf8(&mk_col(), &to_replace, &replacement));
            std::hint::black_box(mk_col().replace_values(&to_replace, &replacement).unwrap());
        }

        let (mut orig, mut cand, mut null) = (Vec::new(), Vec::new(), Vec::new());
        for _ in 0..BLOCKS {
            let (mut bo, mut bc, mut bn) = (f64::INFINITY, f64::INFINITY, f64::INFINITY);
            for _ in 0..REPS {
                let co = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(orig_replace_utf8(
                    std::hint::black_box(&co),
                    &to_replace,
                    &replacement,
                ));
                bo = bo.min(t0.elapsed().as_secs_f64() * 1e3);

                let c1 = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(
                    std::hint::black_box(&c1)
                        .replace_values(&to_replace, &replacement)
                        .unwrap(),
                );
                let a = t0.elapsed().as_secs_f64() * 1e3;
                let c2 = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(
                    std::hint::black_box(&c2)
                        .replace_values(&to_replace, &replacement)
                        .unwrap(),
                );
                let b = t0.elapsed().as_secs_f64() * 1e3;
                bc = bc.min(a.min(b));
                bn = bn.min(a.max(b) / a.min(b).max(1e-9));
            }
            orig.push(bo);
            cand.push(bc);
            null.push(bn);
        }
        let (o, c) = (min_of(&orig), min_of(&cand));
        let sha = Command::new("sha256sum")
            .arg(std::env::current_exe().unwrap())
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .and_then(|s| s.split_whitespace().next().map(str::to_owned))
            .unwrap_or_default();
        let host = Command::new("hostname")
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .map_or_else(|| "?".into(), |s| s.trim().to_owned());
        let nullmed = median_of(&null);
        println!("AB utf8 replace (ONE binary, ONE invocation) N={N} distinct={DISTINCT} k={K}");
        println!("  binary_sha256 = {sha}");
        println!("  worker        = {host}");
        println!(
            "  ORIG generic O(k) semantic_eq scan min={o:8.3} ms  cv={:.2}%",
            cv_of(&orig)
        );
        println!(
            "  CAND contiguous &[u8] map lookup   min={c:8.3} ms  cv={:.2}%",
            cv_of(&cand)
        );
        println!(
            "  NULL-CONTROL (CAND A/A) median={nullmed:.4}x  floor={:.2}%",
            100.0 * (nullmed - 1.0)
        );
        println!(
            "  fp-side ratio (ORIG/CAND) = {:.3}x  ({:+.1}%)  DECIDABLE={}",
            o / c,
            100.0 * (o / c - 1.0),
            100.0 * (o / c - 1.0) > 100.0 * (nullmed - 1.0)
        );
    }
}

#[cfg(test)]
mod ab_temporal_duplicated_ccfp {
    use std::{process::Command, time::Instant};

    use super::Column;

    /// Seeded (splitmix64) Datetime64 ns: `n` rows drawn from `distinct` distinct
    /// 1-second-spaced timestamps around a 2024 base (wide range => the wide
    /// open-addressing dedup path, the realistic timestamp case). No `i64::MIN`.
    fn ns(n: usize, distinct: i64) -> Vec<i64> {
        const BASE: i64 = 1_700_000_000_000_000_000;
        let mut s: u64 = 0x51ED_2701_A3B4_C5D6;
        (0..n)
            .map(|_| {
                s = s.wrapping_add(0x9E37_79B9_7F4A_7C15);
                let mut z = s;
                z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
                z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
                z ^= z >> 31;
                BASE + (z % distinct as u64) as i64 * 1_000_000_000
            })
            .collect()
    }
    fn dt(v: Vec<i64>) -> Column {
        Column::from_datetime64_values(v)
    }
    fn min_of(xs: &[f64]) -> f64 {
        xs.iter().copied().fold(f64::INFINITY, f64::min)
    }
    fn median_of(xs: &[f64]) -> f64 {
        let mut v = xs.to_vec();
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        v[v.len() / 2]
    }
    fn cv_of(xs: &[f64]) -> f64 {
        let m = xs.iter().sum::<f64>() / xs.len() as f64;
        100.0 * (xs.iter().map(|x| (x - m).powi(2)).sum::<f64>() / xs.len() as f64).sqrt() / m
    }

    #[test]
    #[ignore = "perf A/B; run with --ignored --nocapture"]
    fn ab_temporal_duplicated() {
        const N: usize = 2_000_000;
        const DISTINCT: i64 = 50_000;
        const BLOCKS: usize = 9;
        const REPS: usize = 3;
        let src = ns(N, DISTINCT);

        // Parity 1: keep="first" flags == an independent first-seen reference over
        // the raw ns (unambiguous ground truth for the generic Key path).
        {
            use super::FxHashSet;
            let mut seen: FxHashSet<i64> = FxHashSet::default();
            let expect: Vec<bool> = src.iter().map(|&v| !seen.insert(v)).collect();
            let got = dt(src.clone()).duplicated_keep("first").expect("dup first");
            let got_bools: Vec<bool> = got
                .values
                .as_slice()
                .iter()
                .map(|s| matches!(s, super::Scalar::Bool(true)))
                .collect();
            assert_eq!(got_bools, expect, "temporal first-seen flags diverged");
        }
        // Parity 2: all 3 policies match the conformance-verified Int64 path on the
        // same raw ns (Bool output is dtype-independent).
        for policy in ["first", "last", "false"] {
            let temporal = dt(src.clone()).duplicated_keep(policy).expect("dt dup");
            let as_i64 = Column::from_i64_values_owned(src.clone())
                .duplicated_keep(policy)
                .expect("i64 dup");
            assert_eq!(
                temporal.values.as_slice(),
                as_i64.values.as_slice(),
                "temporal vs i64 duplicated diverged (policy={policy})"
            );
        }

        // ORIG timing: plant one NaT (i64::MIN) so the CAND no-NaT gate skips ->
        // the generic Key path runs (measures the ACTUAL pre-lever cost).
        let mut src_orig = src.clone();
        src_orig[0] = i64::MIN;

        for _ in 0..2 {
            std::hint::black_box(dt(src_orig.clone()).duplicated_keep("first").unwrap());
            std::hint::black_box(dt(src.clone()).duplicated_keep("first").unwrap());
        }

        let (mut orig, mut cand, mut null) = (Vec::new(), Vec::new(), Vec::new());
        for _ in 0..BLOCKS {
            let (mut bo, mut bc, mut bn) = (f64::INFINITY, f64::INFINITY, f64::INFINITY);
            for _ in 0..REPS {
                let co = dt(src_orig.clone());
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&co).duplicated_keep("first").unwrap());
                bo = bo.min(t0.elapsed().as_secs_f64() * 1e3);

                let c1 = dt(src.clone());
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c1).duplicated_keep("first").unwrap());
                let a = t0.elapsed().as_secs_f64() * 1e3;
                let c2 = dt(src.clone());
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c2).duplicated_keep("first").unwrap());
                let b = t0.elapsed().as_secs_f64() * 1e3;
                bc = bc.min(a.min(b));
                bn = bn.min(a.max(b) / a.min(b).max(1e-9));
            }
            orig.push(bo);
            cand.push(bc);
            null.push(bn);
        }
        let (o, c) = (min_of(&orig), min_of(&cand));
        let sha = Command::new("sha256sum")
            .arg(std::env::current_exe().unwrap())
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .and_then(|s| s.split_whitespace().next().map(str::to_owned))
            .unwrap_or_default();
        let host = Command::new("hostname")
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .map_or_else(|| "?".into(), |s| s.trim().to_owned());
        let nullmed = median_of(&null);
        println!(
            "AB temporal duplicated keep=first (ONE binary, ONE invocation) N={N} distinct={DISTINCT}"
        );
        println!("  binary_sha256 = {sha}");
        println!("  worker        = {host}");
        println!(
            "  ORIG generic Key::Datetime64 flags min={o:8.3} ms  cv={:.2}%",
            cv_of(&orig)
        );
        println!(
            "  CAND raw-i64 ns dedup flags        min={c:8.3} ms  cv={:.2}%",
            cv_of(&cand)
        );
        println!(
            "  NULL-CONTROL (CAND A/A) median={nullmed:.4}x  floor={:.2}%",
            100.0 * (nullmed - 1.0)
        );
        println!(
            "  fp-side ratio (ORIG/CAND) = {:.3}x  ({:+.1}%)  DECIDABLE={}",
            o / c,
            100.0 * (o / c - 1.0),
            100.0 * (o / c - 1.0) > 100.0 * (nullmed - 1.0)
        );
    }
}

#[cfg(test)]
mod ab_temporal_nunique_ccfp {
    use std::{process::Command, time::Instant};

    use super::{Column, Scalar};

    /// Seeded (splitmix64) Datetime64 ns: `n` rows drawn from `distinct` distinct
    /// 1-second-spaced timestamps around a 2024 base (wide range => the wide
    /// open-addressing `count_distinct_i64_wide` path). No `i64::MIN`.
    fn ns(n: usize, distinct: i64) -> Vec<i64> {
        const BASE: i64 = 1_700_000_000_000_000_000;
        let mut s: u64 = 0x2C1B_3A9F_77E0_6D15;
        (0..n)
            .map(|_| {
                s = s.wrapping_add(0x9E37_79B9_7F4A_7C15);
                let mut z = s;
                z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
                z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
                z ^= z >> 31;
                BASE + (z % distinct as u64) as i64 * 1_000_000_000
            })
            .collect()
    }
    fn dt(v: Vec<i64>) -> Column {
        Column::from_datetime64_values(v)
    }
    fn as_i64(s: &Scalar) -> i64 {
        match s {
            Scalar::Int64(v) => *v,
            other => panic!("expected Int64, got {other:?}"),
        }
    }
    fn min_of(xs: &[f64]) -> f64 {
        xs.iter().copied().fold(f64::INFINITY, f64::min)
    }
    fn median_of(xs: &[f64]) -> f64 {
        let mut v = xs.to_vec();
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        v[v.len() / 2]
    }
    fn cv_of(xs: &[f64]) -> f64 {
        let m = xs.iter().sum::<f64>() / xs.len() as f64;
        100.0 * (xs.iter().map(|x| (x - m).powi(2)).sum::<f64>() / xs.len() as f64).sqrt() / m
    }

    #[test]
    #[ignore = "perf A/B; run with --ignored --nocapture"]
    fn ab_temporal_nunique() {
        const N: usize = 2_000_000;
        const DISTINCT: i64 = 50_000;
        const BLOCKS: usize = 9;
        const REPS: usize = 3;
        let src = ns(N, DISTINCT);

        // Parity: temporal count == ground-truth distinct == Int64-column nunique
        // (conformance-verified), and both dropna values agree for all-valid.
        {
            use super::FxHashSet;
            let expect = src.iter().copied().collect::<FxHashSet<i64>>().len() as i64;
            assert_eq!(
                expect,
                as_i64(&dt(src.clone()).nunique()),
                "temporal nunique diverged"
            );
            assert_eq!(
                expect,
                as_i64(&Column::from_i64_values_owned(src.clone()).nunique()),
                "temporal vs i64 nunique diverged"
            );
            assert_eq!(
                expect,
                as_i64(&dt(src.clone()).nunique_with_dropna(false)),
                "temporal nunique(dropna=false) diverged"
            );
        }

        // ORIG timing: plant one NaT (i64::MIN) so the CAND no-NaT gate skips ->
        // the generic `nannunique` (materialize) path runs.
        let mut src_orig = src.clone();
        src_orig[0] = i64::MIN;

        for _ in 0..2 {
            std::hint::black_box(dt(src_orig.clone()).nunique());
            std::hint::black_box(dt(src.clone()).nunique());
        }

        let (mut orig, mut cand, mut null) = (Vec::new(), Vec::new(), Vec::new());
        for _ in 0..BLOCKS {
            let (mut bo, mut bc, mut bn) = (f64::INFINITY, f64::INFINITY, f64::INFINITY);
            for _ in 0..REPS {
                let co = dt(src_orig.clone());
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&co).nunique());
                bo = bo.min(t0.elapsed().as_secs_f64() * 1e3);

                let c1 = dt(src.clone());
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c1).nunique());
                let a = t0.elapsed().as_secs_f64() * 1e3;
                let c2 = dt(src.clone());
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c2).nunique());
                let b = t0.elapsed().as_secs_f64() * 1e3;
                bc = bc.min(a.min(b));
                bn = bn.min(a.max(b) / a.min(b).max(1e-9));
            }
            orig.push(bo);
            cand.push(bc);
            null.push(bn);
        }
        let (o, c) = (min_of(&orig), min_of(&cand));
        let sha = Command::new("sha256sum")
            .arg(std::env::current_exe().unwrap())
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .and_then(|s| s.split_whitespace().next().map(str::to_owned))
            .unwrap_or_default();
        let host = Command::new("hostname")
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .map_or_else(|| "?".into(), |s| s.trim().to_owned());
        let nullmed = median_of(&null);
        println!("AB temporal nunique (ONE binary, ONE invocation) N={N} distinct={DISTINCT}");
        println!("  binary_sha256 = {sha}");
        println!("  worker        = {host}");
        println!(
            "  ORIG generic nannunique count min={o:8.3} ms  cv={:.2}%",
            cv_of(&orig)
        );
        println!(
            "  CAND raw-i64 ns distinct count min={c:8.3} ms  cv={:.2}%",
            cv_of(&cand)
        );
        println!(
            "  NULL-CONTROL (CAND A/A) median={nullmed:.4}x  floor={:.2}%",
            100.0 * (nullmed - 1.0)
        );
        println!(
            "  fp-side ratio (ORIG/CAND) = {:.3}x  ({:+.1}%)  DECIDABLE={}",
            o / c,
            100.0 * (o / c - 1.0),
            100.0 * (o / c - 1.0) > 100.0 * (nullmed - 1.0)
        );
    }
}

#[cfg(test)]
mod ab_temporal_mode_ccfp {
    use std::{process::Command, time::Instant};

    use super::{Column, ValidityMask};

    /// Seeded (splitmix64) Datetime64 ns: `n` rows drawn from `distinct` distinct
    /// 1-second-spaced timestamps around a 2024 base (wide range => `mode_i64_wide`
    /// open-addressing path). No `i64::MIN`.
    fn ns(n: usize, distinct: i64) -> Vec<i64> {
        const BASE: i64 = 1_700_000_000_000_000_000;
        let mut s: u64 = 0x7F4A_2C19_A3D0_51EB;
        (0..n)
            .map(|_| {
                s = s.wrapping_add(0x9E37_79B9_7F4A_7C15);
                let mut z = s;
                z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
                z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
                z ^= z >> 31;
                BASE + (z % distinct as u64) as i64 * 1_000_000_000
            })
            .collect()
    }
    fn dt(v: Vec<i64>) -> Column {
        Column::from_datetime64_values(v)
    }
    /// Independent ground-truth mode over raw ns: max-count values, ascending.
    fn ground_truth_mode(data: &[i64]) -> Vec<i64> {
        use super::FxHashMap;
        let mut counts: FxHashMap<i64, u64> = FxHashMap::default();
        for &v in data {
            *counts.entry(v).or_insert(0) += 1;
        }
        let max_c = counts.values().copied().max().unwrap_or(0);
        let mut w: Vec<i64> = counts
            .iter()
            .filter_map(|(&k, &c)| (c == max_c).then_some(k))
            .collect();
        w.sort_unstable();
        w
    }
    fn min_of(xs: &[f64]) -> f64 {
        xs.iter().copied().fold(f64::INFINITY, f64::min)
    }
    fn median_of(xs: &[f64]) -> f64 {
        let mut v = xs.to_vec();
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        v[v.len() / 2]
    }
    fn cv_of(xs: &[f64]) -> f64 {
        let m = xs.iter().sum::<f64>() / xs.len() as f64;
        100.0 * (xs.iter().map(|x| (x - m).powi(2)).sum::<f64>() / xs.len() as f64).sqrt() / m
    }

    #[test]
    #[ignore = "perf A/B; run with --ignored --nocapture"]
    fn ab_temporal_mode() {
        const N: usize = 2_000_000;
        const DISTINCT: i64 = 50_000;
        const BLOCKS: usize = 9;
        const REPS: usize = 3;
        let src = ns(N, DISTINCT);

        // Parity: Datetime64 mode winners (ns) == ground truth AND == the
        // conformance-verified Int64-column mode. Timedelta64 re-tag branch too.
        {
            let expect = ground_truth_mode(&src);
            let dt_mode = dt(src.clone()).mode().expect("dt mode");
            assert_eq!(
                dt_mode.as_datetime64_slice().expect("dt64 winners"),
                expect.as_slice(),
                "datetime mode diverged from ground truth"
            );
            assert_eq!(
                dt_mode.as_datetime64_slice().expect("dt64 winners"),
                Column::from_i64_values_owned(src.clone())
                    .mode()
                    .expect("i64 mode")
                    .as_i64_slice()
                    .expect("i64 winners"),
                "datetime vs i64 mode diverged"
            );
            let td = Column::from_timedelta64_values_with_validity(
                src.clone(),
                ValidityMask::all_valid(src.len()),
            );
            assert_eq!(
                td.mode()
                    .expect("td mode")
                    .as_timedelta64_slice()
                    .expect("td winners"),
                expect.as_slice(),
                "timedelta mode diverged from ground truth"
            );
        }

        // ORIG timing: plant one NaT (i64::MIN) so the CAND no-NaT gate skips ->
        // the generic Key path (materialize) runs.
        let mut src_orig = src.clone();
        src_orig[0] = i64::MIN;

        for _ in 0..2 {
            std::hint::black_box(dt(src_orig.clone()).mode().unwrap());
            std::hint::black_box(dt(src.clone()).mode().unwrap());
        }

        let (mut orig, mut cand, mut null) = (Vec::new(), Vec::new(), Vec::new());
        for _ in 0..BLOCKS {
            let (mut bo, mut bc, mut bn) = (f64::INFINITY, f64::INFINITY, f64::INFINITY);
            for _ in 0..REPS {
                let co = dt(src_orig.clone());
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&co).mode().unwrap());
                bo = bo.min(t0.elapsed().as_secs_f64() * 1e3);

                let c1 = dt(src.clone());
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c1).mode().unwrap());
                let a = t0.elapsed().as_secs_f64() * 1e3;
                let c2 = dt(src.clone());
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c2).mode().unwrap());
                let b = t0.elapsed().as_secs_f64() * 1e3;
                bc = bc.min(a.min(b));
                bn = bn.min(a.max(b) / a.min(b).max(1e-9));
            }
            orig.push(bo);
            cand.push(bc);
            null.push(bn);
        }
        let (o, c) = (min_of(&orig), min_of(&cand));
        let sha = Command::new("sha256sum")
            .arg(std::env::current_exe().unwrap())
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .and_then(|s| s.split_whitespace().next().map(str::to_owned))
            .unwrap_or_default();
        let host = Command::new("hostname")
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .map_or_else(|| "?".into(), |s| s.trim().to_owned());
        let nullmed = median_of(&null);
        println!("AB temporal mode (ONE binary, ONE invocation) N={N} distinct={DISTINCT}");
        println!("  binary_sha256 = {sha}");
        println!("  worker        = {host}");
        println!(
            "  ORIG generic Key::Datetime64 tally min={o:8.3} ms  cv={:.2}%",
            cv_of(&orig)
        );
        println!(
            "  CAND raw-i64 ns mode + re-tag      min={c:8.3} ms  cv={:.2}%",
            cv_of(&cand)
        );
        println!(
            "  NULL-CONTROL (CAND A/A) median={nullmed:.4}x  floor={:.2}%",
            100.0 * (nullmed - 1.0)
        );
        println!(
            "  fp-side ratio (ORIG/CAND) = {:.3}x  ({:+.1}%)  DECIDABLE={}",
            o / c,
            100.0 * (o / c - 1.0),
            100.0 * (o / c - 1.0) > 100.0 * (nullmed - 1.0)
        );
    }
}

#[cfg(test)]
mod ab_f64_median_ccfp {
    use std::{process::Command, time::Instant};

    use super::{Column, Scalar, nanmedian};

    /// Seeded (splitmix64) finite f64 values in [0, 1e6).
    fn f64s(n: usize) -> Vec<f64> {
        let mut s: u64 = 0x9B1D_2E4C_75A0_31F7;
        (0..n)
            .map(|_| {
                s = s.wrapping_add(0x9E37_79B9_7F4A_7C15);
                let mut z = s;
                z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
                z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
                z ^= z >> 31;
                (z >> 11) as f64 / (1u64 << 53) as f64 * 1.0e6
            })
            .collect()
    }
    /// Exact pre-lever path: materialize the Scalars then `nanmedian`.
    fn orig_median(col: &Column) -> Scalar {
        nanmedian(col.values.as_slice())
    }
    fn min_of(xs: &[f64]) -> f64 {
        xs.iter().copied().fold(f64::INFINITY, f64::min)
    }
    fn median_of(xs: &[f64]) -> f64 {
        let mut v = xs.to_vec();
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        v[v.len() / 2]
    }
    fn cv_of(xs: &[f64]) -> f64 {
        let m = xs.iter().sum::<f64>() / xs.len() as f64;
        100.0 * (xs.iter().map(|x| (x - m).powi(2)).sum::<f64>() / xs.len() as f64).sqrt() / m
    }

    #[test]
    #[ignore = "perf A/B; run with --ignored --nocapture"]
    fn ab_f64_median() {
        const N: usize = 4_000_000;
        const BLOCKS: usize = 9;
        const REPS: usize = 3;
        let src = f64s(N);
        let mk_col = || Column::from_f64_values(src.clone());

        // Parity: fast path == the exact Scalar `nanmedian` path (odd AND even n),
        // plus the empty column.
        {
            let a = orig_median(&mk_col());
            let b = mk_col().median();
            assert_eq!(a, b, "median diverged (even n)");
            let odd: Vec<f64> = src[..N - 1].to_vec();
            let ao = nanmedian(Column::from_f64_values(odd.clone()).values.as_slice());
            let bo = Column::from_f64_values(odd).median();
            assert_eq!(ao, bo, "median diverged (odd n)");
            let ae = nanmedian(Column::from_f64_values(Vec::new()).values.as_slice());
            let be = Column::from_f64_values(Vec::new()).median();
            assert_eq!(ae, be, "empty median diverged");
        }

        for _ in 0..2 {
            std::hint::black_box(orig_median(&mk_col()));
            std::hint::black_box(mk_col().median());
        }

        let (mut orig, mut cand, mut null) = (Vec::new(), Vec::new(), Vec::new());
        for _ in 0..BLOCKS {
            let (mut bo, mut bc, mut bn) = (f64::INFINITY, f64::INFINITY, f64::INFINITY);
            for _ in 0..REPS {
                let co = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(orig_median(std::hint::black_box(&co)));
                bo = bo.min(t0.elapsed().as_secs_f64() * 1e3);

                let c1 = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c1).median());
                let a = t0.elapsed().as_secs_f64() * 1e3;
                let c2 = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c2).median());
                let b = t0.elapsed().as_secs_f64() * 1e3;
                bc = bc.min(a.min(b));
                bn = bn.min(a.max(b) / a.min(b).max(1e-9));
            }
            orig.push(bo);
            cand.push(bc);
            null.push(bn);
        }
        let (o, c) = (min_of(&orig), min_of(&cand));
        let sha = Command::new("sha256sum")
            .arg(std::env::current_exe().unwrap())
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .and_then(|s| s.split_whitespace().next().map(str::to_owned))
            .unwrap_or_default();
        let host = Command::new("hostname")
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .map_or_else(|| "?".into(), |s| s.trim().to_owned());
        let nullmed = median_of(&null);
        println!("AB f64 median (ONE binary, ONE invocation) N={N}");
        println!("  binary_sha256 = {sha}");
        println!("  worker        = {host}");
        println!(
            "  ORIG nanmedian(Vec<Scalar>) min={o:8.3} ms  cv={:.2}%",
            cv_of(&orig)
        );
        println!(
            "  CAND typed &[f64] select    min={c:8.3} ms  cv={:.2}%",
            cv_of(&cand)
        );
        println!(
            "  NULL-CONTROL (CAND A/A) median={nullmed:.4}x  floor={:.2}%",
            100.0 * (nullmed - 1.0)
        );
        println!(
            "  fp-side ratio (ORIG/CAND) = {:.3}x  ({:+.1}%)  DECIDABLE={}",
            o / c,
            100.0 * (o / c - 1.0),
            100.0 * (o / c - 1.0) > 100.0 * (nullmed - 1.0)
        );
    }
}

#[cfg(test)]
mod ab_count_distinct_radix_ccfp {
    use std::{process::Command, time::Instant};

    use super::{
        count_distinct_i64_radix, count_distinct_i64_singletable, count_distinct_i64_wide,
    };

    /// Seeded (splitmix64) i64. `distinct == 0` => ~all-distinct raw stream
    /// (i64::MIN remapped to 0); otherwise values in `0..distinct`.
    fn mkdata(n: usize, distinct: u64) -> Vec<i64> {
        let mut s: u64 = 0xA5A5_1234_DEAD_BEEF;
        (0..n)
            .map(|_| {
                s = s.wrapping_add(0x9E37_79B9_7F4A_7C15);
                let mut z = s;
                z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
                z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
                z ^= z >> 31;
                if distinct == 0 {
                    let v = z as i64;
                    if v == i64::MIN { 0 } else { v }
                } else {
                    (z % distinct) as i64
                }
            })
            .collect()
    }
    fn min_of(xs: &[f64]) -> f64 {
        xs.iter().copied().fold(f64::INFINITY, f64::min)
    }
    fn median_of(xs: &[f64]) -> f64 {
        let mut v = xs.to_vec();
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        v[v.len() / 2]
    }
    fn cv_of(xs: &[f64]) -> f64 {
        let m = xs.iter().sum::<f64>() / xs.len() as f64;
        100.0 * (xs.iter().map(|x| (x - m).powi(2)).sum::<f64>() / xs.len() as f64).sqrt() / m
    }

    #[test]
    #[ignore = "perf A/B; run with --ignored --nocapture"]
    fn ab_count_distinct_radix() {
        const N: usize = 8_000_000;
        const BLOCKS: usize = 9;
        const REPS: usize = 3;
        let src = mkdata(N, 0); // ~all-distinct: worst case for the single table

        // Parity: radix == single-table across distributions incl. a planted
        // i64::MIN sentinel and a moderate-cardinality case.
        {
            let base = count_distinct_i64_singletable(&src);
            assert_eq!(
                count_distinct_i64_radix(&src),
                base,
                "radix vs single (all-distinct)"
            );
            assert_eq!(
                count_distinct_i64_wide(&src),
                base,
                "dispatch vs single (all-distinct)"
            );
            let moderate = mkdata(N, 100_000);
            let base_m = count_distinct_i64_singletable(&moderate);
            assert_eq!(
                count_distinct_i64_radix(&moderate),
                base_m,
                "radix vs single (moderate)"
            );
            assert_eq!(
                count_distinct_i64_wide(&moderate),
                base_m,
                "dispatch vs single (moderate)"
            );
            let mut with_nat = src.clone();
            with_nat[0] = i64::MIN;
            with_nat[1] = i64::MIN;
            let base_n = count_distinct_i64_singletable(&with_nat);
            assert_eq!(
                count_distinct_i64_radix(&with_nat),
                base_n,
                "radix vs single (sentinel)"
            );
            assert_eq!(
                count_distinct_i64_wide(&with_nat),
                base_n,
                "dispatch vs single (sentinel)"
            );
            assert_eq!(count_distinct_i64_radix(&[]), 0, "empty radix");
        }

        let sha = Command::new("sha256sum")
            .arg(std::env::current_exe().unwrap())
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .and_then(|s| s.split_whitespace().next().map(str::to_owned))
            .unwrap_or_default();
        let host = Command::new("hostname")
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .map_or_else(|| "?".into(), |s| s.trim().to_owned());

        let measure = |data: &[i64]| {
            for _ in 0..2 {
                std::hint::black_box(count_distinct_i64_singletable(std::hint::black_box(data)));
                std::hint::black_box(count_distinct_i64_wide(std::hint::black_box(data)));
            }
            let (mut orig, mut cand, mut null) = (Vec::new(), Vec::new(), Vec::new());
            for _ in 0..BLOCKS {
                let (mut bo, mut bc, mut bn) = (f64::INFINITY, f64::INFINITY, f64::INFINITY);
                for _ in 0..REPS {
                    let t0 = Instant::now();
                    std::hint::black_box(count_distinct_i64_singletable(std::hint::black_box(
                        data,
                    )));
                    bo = bo.min(t0.elapsed().as_secs_f64() * 1e3);

                    let t0 = Instant::now();
                    std::hint::black_box(count_distinct_i64_wide(std::hint::black_box(data)));
                    let a = t0.elapsed().as_secs_f64() * 1e3;
                    let t0 = Instant::now();
                    std::hint::black_box(count_distinct_i64_wide(std::hint::black_box(data)));
                    let b = t0.elapsed().as_secs_f64() * 1e3;
                    bc = bc.min(a.min(b));
                    bn = bn.min(a.max(b) / a.min(b).max(1e-9));
                }
                orig.push(bo);
                cand.push(bc);
                null.push(bn);
            }
            (
                min_of(&orig),
                min_of(&cand),
                median_of(&null),
                cv_of(&orig),
                cv_of(&cand),
            )
        };

        let lowcard = mkdata(N, 1000);
        println!("AB count_distinct radix (ONE binary, ONE invocation) N={N}");
        println!("  binary_sha256 = {sha}");
        println!("  worker        = {host}");
        for (label, data) in [
            ("~all-distinct (HIGH card)", src.as_slice()),
            ("1000 distinct (LOW card)", lowcard.as_slice()),
        ] {
            let (o, c, nullmed, cvo, cvc) = measure(data);
            println!("  --- {label} ---");
            println!("    ORIG single-table 2n probe    min={o:8.3} ms  cv={cvo:.2}%");
            println!("    CAND dispatch (radix|single)  min={c:8.3} ms  cv={cvc:.2}%");
            println!(
                "    NULL floor={:.2}%   ratio (ORIG/CAND) = {:.3}x  ({:+.1}%)  DECIDABLE={}",
                100.0 * (nullmed - 1.0),
                o / c,
                100.0 * (o / c - 1.0),
                100.0 * (o / c - 1.0) > 100.0 * (nullmed - 1.0)
            );
        }
    }
}

#[cfg(test)]
mod ab_f64_quantile_ccfp {
    use std::{process::Command, time::Instant};

    use super::{Column, Scalar, nanquantile};

    /// Seeded (splitmix64) finite f64 values in [0, 1e6).
    fn f64s(n: usize) -> Vec<f64> {
        let mut s: u64 = 0x3C79_9A1B_D45E_2F08;
        (0..n)
            .map(|_| {
                s = s.wrapping_add(0x9E37_79B9_7F4A_7C15);
                let mut z = s;
                z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
                z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
                z ^= z >> 31;
                (z >> 11) as f64 / (1u64 << 53) as f64 * 1.0e6
            })
            .collect()
    }
    fn orig_quantile(col: &Column, q: f64) -> Scalar {
        nanquantile(col.values.as_slice(), q)
    }
    fn min_of(xs: &[f64]) -> f64 {
        xs.iter().copied().fold(f64::INFINITY, f64::min)
    }
    fn median_of(xs: &[f64]) -> f64 {
        let mut v = xs.to_vec();
        v.sort_by(|a, b| a.partial_cmp(b).unwrap());
        v[v.len() / 2]
    }
    fn cv_of(xs: &[f64]) -> f64 {
        let m = xs.iter().sum::<f64>() / xs.len() as f64;
        100.0 * (xs.iter().map(|x| (x - m).powi(2)).sum::<f64>() / xs.len() as f64).sqrt() / m
    }

    #[test]
    #[ignore = "perf A/B; run with --ignored --nocapture"]
    fn ab_f64_quantile() {
        const N: usize = 4_000_000;
        const BLOCKS: usize = 9;
        const REPS: usize = 3;
        let src = f64s(N);
        let mk_col = || Column::from_f64_values(src.clone());

        // Parity: fast path == the exact Scalar `nanquantile` path across q
        // (interpolating + boundary + out-of-range), n==1, and empty.
        {
            for &q in &[0.0_f64, 0.25, 0.5, 0.75, 0.9, 1.0, -0.1, 1.5] {
                assert_eq!(
                    orig_quantile(&mk_col(), q),
                    mk_col().quantile(q),
                    "quantile diverged at q={q}"
                );
            }
            let one = Column::from_f64_values(vec![42.0]);
            assert_eq!(
                nanquantile(one.values.as_slice(), 0.3),
                one.quantile(0.3),
                "n=1"
            );
            let empty = Column::from_f64_values(Vec::new());
            assert_eq!(
                nanquantile(empty.values.as_slice(), 0.5),
                empty.quantile(0.5),
                "empty quantile diverged"
            );
        }

        const Q: f64 = 0.25;
        for _ in 0..2 {
            std::hint::black_box(orig_quantile(&mk_col(), Q));
            std::hint::black_box(mk_col().quantile(Q));
        }

        let (mut orig, mut cand, mut null) = (Vec::new(), Vec::new(), Vec::new());
        for _ in 0..BLOCKS {
            let (mut bo, mut bc, mut bn) = (f64::INFINITY, f64::INFINITY, f64::INFINITY);
            for _ in 0..REPS {
                let co = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(orig_quantile(std::hint::black_box(&co), Q));
                bo = bo.min(t0.elapsed().as_secs_f64() * 1e3);

                let c1 = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c1).quantile(Q));
                let a = t0.elapsed().as_secs_f64() * 1e3;
                let c2 = mk_col();
                let t0 = Instant::now();
                std::hint::black_box(std::hint::black_box(&c2).quantile(Q));
                let b = t0.elapsed().as_secs_f64() * 1e3;
                bc = bc.min(a.min(b));
                bn = bn.min(a.max(b) / a.min(b).max(1e-9));
            }
            orig.push(bo);
            cand.push(bc);
            null.push(bn);
        }
        let (o, c) = (min_of(&orig), min_of(&cand));
        let sha = Command::new("sha256sum")
            .arg(std::env::current_exe().unwrap())
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .and_then(|s| s.split_whitespace().next().map(str::to_owned))
            .unwrap_or_default();
        let host = Command::new("hostname")
            .output()
            .ok()
            .and_then(|x| String::from_utf8(x.stdout).ok())
            .map_or_else(|| "?".into(), |s| s.trim().to_owned());
        let nullmed = median_of(&null);
        println!("AB f64 quantile q={Q} (ONE binary, ONE invocation) N={N}");
        println!("  binary_sha256 = {sha}");
        println!("  worker        = {host}");
        println!(
            "  ORIG nanquantile(Vec<Scalar>) min={o:8.3} ms  cv={:.2}%",
            cv_of(&orig)
        );
        println!(
            "  CAND typed &[f64] select      min={c:8.3} ms  cv={:.2}%",
            cv_of(&cand)
        );
        println!(
            "  NULL-CONTROL (CAND A/A) median={nullmed:.4}x  floor={:.2}%",
            100.0 * (nullmed - 1.0)
        );
        println!(
            "  fp-side ratio (ORIG/CAND) = {:.3}x  ({:+.1}%)  DECIDABLE={}",
            o / c,
            100.0 * (o / c - 1.0),
            100.0 * (o / c - 1.0) > 100.0 * (nullmed - 1.0)
        );
    }
}

